# ─── Управление позицией ────────────────────────────────────────────────────
# Коэффициенты для стопа/тейков (в единицах ATR).
# Российский рынок МОСБИРЖА: стоп 1.5×ATR — стандарт для ликвидных акций.
# Тейк1 = 1×ATR (50% позиции), Тейк2 = 2×ATR (50% позиции).
# После Тейк1 — стоп переносится в безубыток (БУ = цена входа).
STOP_ATR_MULT  = float(os.environ.get("STOP_ATR_MULT",  "1.5"))  # стоп
TAKE1_ATR_MULT = float(os.environ.get("TAKE1_ATR_MULT", "1.0"))  # тейк 1 (50%)
TAKE2_ATR_MULT = float(os.environ.get("TAKE2_ATR_MULT", "2.0"))  # тейк 2 (50%)
# Максимальный стоп в % от цены (защита при аномально большом ATR)
MAX_STOP_PCT   = float(os.environ.get("MAX_STOP_PCT",   "2.5"))   # не более 2.5% (v0.9.5 — снижено с 4%)
# H1 ATR sizing — калиброван под реальные дневные диапазоны МОСБИРЖИ (v0.9.10):
# Типовой ход ликвидной акции ≈ 1.5–2.5% в день. Тейк2 > 2.5% — только на новостях.
# Стоп:  2×H1_ATR ≈ 1–1.5%  (достаточно пространства, не выбивает на шуме)
# Тейк1: 1.5×H1_ATR ≈ 1–1.4% (достижимо в 40–50% сигналов, закрываем 50% позиции)
# Тейк2: 2.5×H1_ATR ≈ 1.5–2.5% (достижимо в 25–35%, трейлим остаток)
# R/R номинально 1:1.25, со структурным стопом ≈ 1:2 — стандарт для интрадея MOEX.
H1_STOP_MULT   = float(os.environ.get("H1_STOP_MULT",   "2.0"))   # стоп:  2.0×H1_ATR ≈ 1–1.5%
H1_TAKE1_MULT  = float(os.environ.get("H1_TAKE1_MULT",  "1.5"))   # тейк1: 1.5×H1_ATR ≈ 1–1.4% (было 2.0)
H1_TAKE2_MULT  = float(os.environ.get("H1_TAKE2_MULT",  "3.0"))   # тейк2: 3.0×H1_ATR ≈ 1.8–3.0% (было 2.5→3.0 v0.9.20 R/R fix)
# v0.9.13: минимальная дистанция стопа = MIN_STOP_ATR_MULT × H1_ATR.
# Защита от ультра-узких структурных стопов (R/R > 15 → почти наверняка шум выбьет).
# Пример: PHOR H1_ATR=44 → min_stop = 0.5×44 = 22₽. Стоп 4.83 → заменяется на ATR-стоп.
MIN_STOP_ATR_MULT = float(os.environ.get("MIN_STOP_ATR_MULT", "0.5"))  # × H1_ATR

# ─── v0.9.14: Недельный TF фильтр ────────────────────────────────────────────
# Недельный тренд — старший контекст. Торговля против недельного тренда = высокий риск.
# Алгоритм: MA5 недельных закрытий. Выше MA5 → бычья структура, ниже → медвежья.
# Влияние на score: совпадение с недельным трендом = +WEEKLY_ALIGNED_BONUS.
#                   против недельного тренда = -WEEKLY_AGAINST_PENALTY.
# Кэш: данные обновляются раз в WEEKLY_CACHE_TTL_HOURS (недельный тренд меняется редко).
WEEKLY_TREND_FILTER     = bool(int(os.environ.get("WEEKLY_TREND_FILTER",     "1")))
WEEKLY_ALIGNED_BONUS    = int(os.environ.get("WEEKLY_ALIGNED_BONUS",    "2"))  # +2 pts если тренд за нас
WEEKLY_AGAINST_PENALTY  = int(os.environ.get("WEEKLY_AGAINST_PENALTY",  "3"))  # -3 pts если против
WEEKLY_CACHE_TTL_HOURS  = float(os.environ.get("WEEKLY_CACHE_TTL_HOURS", "2")) # TTL кэша в часах

# ─── v0.9.14: Маржинальные расходы для SHORT ─────────────────────────────────
# SHORT на MOEX = маржинальная позиция.
# v0.9.22: Т-Инвест берёт ФИКСИРОВАННУЮ плату в ₽/день (не % годовых!).
# Актуальный тариф (c сентября 2025, проверено 01.04.2026):
#   до 5 000 ₽   → 0 ₽/день
#   5–50 тыс.    → 35 ₽/день
#   50–100 тыс.  → 70 ₽/день
#   100–200 тыс. → 135 ₽/день
#   200–300 тыс. → 200 ₽/день
#   300–500 тыс. → 310 ₽/день
#   0.5–1 млн    → 600 ₽/день
#   1–2 млн      → 1 200 ₽/день
#   2–5 млн      → 3 000 ₽/день
#   > 5 млн      → 0.06%/день
# Эффективная ставка для типичной позиции 200–500k ₽: ~22-25% годовых (было хардкодом 17% — занижено).
MARGIN_RATE_ANNUAL   = float(os.environ.get("MARGIN_RATE_ANNUAL",  "0.25"))  # fallback если нет позиции
SHORT_MARGIN_MAX_DAYS = int(os.environ.get("SHORT_MARGIN_MAX_DAYS", "7"))    # макс. дней удержания


def tinvest_margin_daily_rub(position_value_rub: float) -> float:
    """
    v0.9.22: Точный расчёт дневной комиссии T-Invest за перенос шорт-позиции.
    Источник: tbank.ru/invest/help/brokerage/account/margin/short/ (актуально 2025-2026).
    """
    v = position_value_rub
    if v <= 5_000:         return 0.0
    elif v <= 50_000:      return 35.0
    elif v <= 100_000:     return 70.0
    elif v <= 200_000:     return 135.0
    elif v <= 300_000:     return 200.0
    elif v <= 500_000:     return 310.0
    elif v <= 1_000_000:   return 600.0
    elif v <= 2_000_000:   return 1_200.0
    elif v <= 5_000_000:   return 3_000.0
    else:                  return v * 0.0006  # 0.06%/день

