def is_moex_open() -> bool:
    """True если сейчас открыт канонический торговый интервал этой версии."""
    is_open, _, _ = _session_window()
    return is_open


_CBR_RATE_CACHE_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "cbr_rate_cache.json")
_CBR_RATE_CACHE_TTL  = 6 * 3600   # обновляем не чаще 1 раза в 6 часов


def fetch_cbr_rate() -> float:
    """
    v0.9.21: Получаем актуальную ключевую ставку ЦБ РФ из интернета.
    Источник: cbr.ru/hd_base/KeyRate/  (официальный сайт ЦБ)
    Кэш: cbr_rate_cache.json (TTL 6ч) — чтобы не дёргать сайт при каждом скане.
    Fallback: значение CBR_KEY_RATE из конфига/env.
    """
    import re as _re

    # ── проверяем кэш ────────────────────────────────────────────────────────
    try:
        with open(_CBR_RATE_CACHE_FILE) as f:
            cached = json.load(f)
        if time.time() - cached.get("ts", 0) < _CBR_RATE_CACHE_TTL:
            rate = float(cached["rate"])
            logger.debug("CBR rate из кэша: %.2f%%", rate)
            return rate
    except Exception:
        pass

    # ── пробуем получить с cbr.ru ────────────────────────────────────────────
    rate = None
    try:
        # ЦБ публикует XML статистику ключевой ставки
        # Запрашиваем последние 30 дней, берём последнюю запись
        date_to   = now_msk().strftime("%d/%m/%Y")
        date_from = (now_msk() - timedelta(days=30)).strftime("%d/%m/%Y")
        url = (
            "https://www.cbr.ru/scripts/XML_val.asp"
        )
        # Используем официальный XML эндпоинт статистики
        stat_url = (
            f"https://www.cbr.ru/scripts/XML_stat.asp"
            f"?d=0&FromDate={date_from}&ToDate={date_to}"
            f"&UniDbQuery.Posted=True&UniDbQuery.sid=45"
        )
        r = requests.get(stat_url, timeout=10,
                         headers={"User-Agent": "Mozilla/5.0 (moex_bot trading)"})
        r.raise_for_status()
        # XML вида: <KeyRate Date="..."><Rate>21,00</Rate></KeyRate>
        # Берём последнее вхождение Rate
        matches = _re.findall(r"<Rate>([\d,\.]+)</Rate>", r.text)
        if matches:
            rate_str = matches[-1].replace(",", ".")
            rate = float(rate_str)
            logger.info("CBR key rate получен с cbr.ru: %.2f%%", rate)
    except Exception as e:
        logger.warning("CBR rate: cbr.ru XML не ответил (%s), пробуем страницу...", e)

    # ── fallback: парсим HTML страницу ────────────────────────────────────────
    if rate is None:
        try:
            r = requests.get(
                "https://www.cbr.ru/hd_base/KeyRate/",
                timeout=10,
                headers={"User-Agent": "Mozilla/5.0 (moex_bot trading)"},
            )
            r.raise_for_status()
            # В таблице ищем числа вида "21,00" или "21.00" рядом с датой
            matches = _re.findall(
                r"(\d{2}\.\d{2}\.\d{4}).*?(\d{1,2}[,\.]\d{2})\s*(?:%|</td>)",
                r.text, _re.DOTALL
            )
            if matches:
                rate_str = matches[-1][1].replace(",", ".")
                rate = float(rate_str)
                logger.info("CBR key rate с HTML-страницы: %.2f%%", rate)
        except Exception as e2:
            logger.warning("CBR rate: HTML тоже не удалось (%s)", e2)

    # ── сохраняем в кэш и возвращаем ─────────────────────────────────────────
    if rate is not None:
        try:
            with open(_CBR_RATE_CACHE_FILE, "w") as f:
                json.dump({"rate": rate, "ts": time.time()}, f)
        except Exception:
            pass
        return rate

    logger.warning("CBR rate: используем fallback из конфига: %.2f%%", CBR_KEY_RATE)
    return CBR_KEY_RATE


def fetch_brent_price() -> dict:
    """
    v0.9.29: Цена нефти Brent через MOEX ISS (ближайший фьючерс серии BR).
    Алгоритм: получаем список активных фьючерсов BR → берём первый по дате →
    дневные свечи за 5 дней → last price + % изменения.
    Возвращает {"price": float|None, "change_pct": float|None}.
    """
    _empty = {"price": None, "change_pct": None}
    try:
        # Шаг 1: список активных контрактов BR (нефть Brent)
        r = requests.get(
            f"{BASE_URL}/engines/futures/markets/forts/securities.json"
            "?q=BR&is_trading=1&limit=10",
            timeout=10,
        )
        r.raise_for_status()
        data  = r.json()
        cols  = data["securities"]["columns"]
        secs  = [dict(zip(cols, row)) for row in data["securities"]["data"]]
        # Фильтруем только BR* (фьючерсы нефти, не спред-контракты)
        br_contracts = [s for s in secs if str(s.get("SECID", "")).startswith("BR")
                        and len(s.get("SECID", "")) <= 6]
        if not br_contracts:
            logger.debug("brent: нет активных контрактов BR")
            return _empty
        # Берём контракт с ближайшей датой экспирации (LASTTRADEDATE)
        br_contracts.sort(key=lambda s: s.get("LASTTRADEDATE", "9999-99-99"))
        code = br_contracts[0]["SECID"]

        # Шаг 2: дневные свечи за последние 5 торговых дней
        from_dt = (now_msk() - timedelta(days=10)).strftime("%Y-%m-%d")
        till_dt = now_msk().strftime("%Y-%m-%d")
        r2 = requests.get(
            f"{BASE_URL}/engines/futures/markets/forts/boards/RFUD"
            f"/securities/{code}/candles.json"
            f"?from={from_dt}&till={till_dt}&interval=24",
            timeout=10,
        )
        r2.raise_for_status()
        d2   = r2.json()
        c2   = d2["candles"]["columns"]
        rows = [dict(zip(c2, row)) for row in d2["candles"]["data"]]
        if len(rows) < 2:
            return _empty
        last_price  = rows[-1]["close"]
        prev_price  = rows[-2]["close"]
        change_pct  = round((last_price - prev_price) / prev_price * 100, 2) if prev_price else None
        logger.debug("brent %s: %.2f $ (%+.2f%%)", code, last_price, change_pct or 0)
        return {"price": round(last_price, 2), "change_pct": change_pct}
    except Exception as e:
        logger.debug("brent: %s", e)
        return _empty


def fetch_gold_price() -> dict:
    """
    v0.9.29: Цена золота через MOEX ISS (GLDRUB_TOM — спот в ₽/грамм).
    Возвращает {"price_rub_gram": float|None, "change_pct": float|None}.
    """
    _empty = {"price_rub_gram": None, "change_pct": None}
    try:
        from_dt = (now_msk() - timedelta(days=7)).strftime("%Y-%m-%d")
        till_dt = now_msk().strftime("%Y-%m-%d")
        r = requests.get(
            f"{BASE_URL}/engines/currency/markets/selt/boards/CETS"
            "/securities/GLDRUB_TOM/candles.json"
            f"?from={from_dt}&till={till_dt}&interval=24",
            timeout=10,
        )
        r.raise_for_status()
        data = r.json()
        cols = data["candles"]["columns"]
        rows = [dict(zip(cols, row)) for row in data["candles"]["data"]]
        if len(rows) < 2:
            return _empty
        last_price = rows[-1]["close"]
        prev_price = rows[-2]["close"]
        change_pct = round((last_price - prev_price) / prev_price * 100, 2) if prev_price else None
        logger.debug("gold GLDRUB_TOM: %.2f ₽/г (%+.2f%%)", last_price, change_pct or 0)
        return {"price_rub_gram": round(last_price, 2), "change_pct": change_pct}
    except Exception as e:
        logger.debug("gold: %s", e)
        return _empty


def get_market_context() -> dict:
    """
    Получаем USDRUB, IMOEX, Brent, Gold из MOEX ISS.
    Возвращает словарь с курсом рубля, индексом, ставкой ЦБ, нефтью, золотом.
    IMOEX: 21 дн. история → поддержка, сопротивление, ATR, RSI, Фибоначчи, зона.
    v0.9.21: cbr_rate теперь всегда актуальный (fetch_cbr_rate с кэшем).
    v0.9.29: добавлены Brent (фьючерс BR) и Gold (GLDRUB_TOM).
    """
    ctx = {
        "usdrub":            None,
        "usdrub_change_pct": None,
        "imoex":             None,
        "imoex_change_pct":  None,
        "imoex_levels":      None,   # технические уровни IMOEX (добавлено в v0.8)
        "cbr_rate":          fetch_cbr_rate(),  # v0.9.21: всегда актуально с cbr.ru
        # v0.9.29: нефть и золото
        "brent":             None,   # цена Brent ($)
        "brent_change_pct":  None,   # дневное изменение Brent (%)
        "gold_rub_gram":     None,   # золото ₽/грамм (GLDRUB_TOM)
        "gold_change_pct":   None,   # дневное изменение золота (%)
    }
    # v0.9.29: синхронизируем глобальный CBR_KEY_RATE с живой ставкой из кэша/cbr.ru.
    # Это позволяет synthesize_signals() использовать актуальную ставку через CBR_KEY_RATE.
    global CBR_KEY_RATE
    CBR_KEY_RATE = ctx["cbr_rate"]
    yesterday = (now_msk() - timedelta(days=5)).strftime("%Y-%m-%d")
    today     = now_msk().strftime("%Y-%m-%d")

    # USDRUB — дневные свечи валютной секции
    # v0.9.6: используем USD000UTSTOM (TOM, самый ликвидный инструмент) вместо TOD.
    # TOM торгуется весь день и имеет данные даже после 18:00 МСК.
    # Fallback: если TOM не вернул данных — пробуем TOD.
    def _fetch_usdrub(security: str) -> list[dict]:
        r = requests.get(
            f"{BASE_URL}/engines/currency/markets/selt/boards/CETS"
            f"/securities/{security}/candles.json"
            f"?from={yesterday}&till={today}&interval=24",
            timeout=10,
        )
        r.raise_for_status()
        data = r.json()
        return [dict(zip(data["candles"]["columns"], row)) for row in data["candles"]["data"]]

    try:
        rows = _fetch_usdrub("USD000UTSTOM")
        if not rows:                             # fallback на TOD если TOM пуст
            rows = _fetch_usdrub("USD000000TOD")
        if len(rows) >= 2:
            ctx["usdrub"]            = round(rows[-1]["close"], 2)
            ctx["usdrub_change_pct"] = round(
                (rows[-1]["close"] - rows[-2]["close"]) / rows[-2]["close"] * 100, 2
            )
        elif rows:
            ctx["usdrub"] = round(rows[-1]["close"], 2)
    except Exception as e:
        logger.warning("USDRUB: не удалось получить данные: %s", e)

    # IMOEX — индекс МосБиржи (35 дн. → 21 свеча для технического анализа)
    try:
        imoex_from = (now_msk() - timedelta(days=35)).strftime("%Y-%m-%d")
        r = requests.get(
            f"{BASE_URL}/engines/stock/markets/index/boards/SNDX"
            f"/securities/IMOEX/candles.json"
            f"?from={imoex_from}&till={today}&interval=24",
            timeout=10,
        )
        r.raise_for_status()
        data = r.json()
        rows = [dict(zip(data["candles"]["columns"], row)) for row in data["candles"]["data"]]
        if len(rows) >= 2:
            ctx["imoex"]            = round(rows[-1]["close"], 1)
            ctx["imoex_change_pct"] = round(
                (rows[-1]["close"] - rows[-2]["close"]) / rows[-2]["close"] * 100, 2
            )
        elif rows:
            ctx["imoex"] = round(rows[-1]["close"], 1)

        # Технические уровни IMOEX (нужно ≥5 свечей)
        if len(rows) >= 5:
            window  = rows[-21:]   # не более 21 свечи
            highs   = [r["high"]  for r in window if r.get("high")]
            lows    = [r["low"]   for r in window if r.get("low")]
            closes  = [r["close"] for r in window if r.get("close")]
            current = closes[-1] if closes else None

            support    = round(min(lows),   1) if lows   else None
            resistance = round(max(highs),  1) if highs  else None
            atr_val    = round(mean([h - l for h, l in zip(highs, lows)]), 1) if highs else None
            rsi_val    = calc_rsi(closes, RSI_PERIOD)

            # Уровни Фибоначчи на диапазоне IMOEX
            fib_levels: dict = {}
            if support and resistance:
                fib_range = resistance - support
                if fib_range > 0:
                    fib_levels = {
                        "23.6%": round(support + 0.236 * fib_range, 1),
                        "38.2%": round(support + 0.382 * fib_range, 1),
                        "50.0%": round(support + 0.500 * fib_range, 1),
                        "61.8%": round(support + 0.618 * fib_range, 1),
                    }

            # Зона: "рядом" = в пределах 1 ATR от уровня
            zone = "middle"
            if current and support and resistance and atr_val:
                if current - support <= atr_val:
                    zone = "near_support"
                elif resistance - current <= atr_val:
                    zone = "near_resistance"

            ctx["imoex_levels"] = {
                "support":    support,
                "resistance": resistance,
                "atr":        atr_val,
                "rsi":        rsi_val,
                "fib_levels": fib_levels,
                "zone":       zone,
                "candles":    len(rows),
            }

        # v0.9.8: IMOEX MA5 — режим рынка (бычий/медвежий среднесрочный тренд)
        if len(rows) >= 5:
            imoex_ma5 = sum(r["close"] for r in rows[-5:]) / 5
            ctx["imoex_ma5"]    = round(imoex_ma5, 1)
            ctx["imoex_regime"] = "bull" if rows[-1]["close"] >= imoex_ma5 else "bear"

    except Exception as e:
        logger.warning("IMOEX: не удалось получить данные: %s", e)

    # v0.9.29: Brent нефть (влияние на экспортёров)
    try:
        _brent = fetch_brent_price()
        ctx["brent"]            = _brent["price"]
        ctx["brent_change_pct"] = _brent["change_pct"]
    except Exception as e:
        logger.debug("brent context: %s", e)

    # v0.9.29: Золото GLDRUB_TOM (влияние на PLZL)
    try:
        _gold = fetch_gold_price()
        ctx["gold_rub_gram"]    = _gold["price_rub_gram"]
        ctx["gold_change_pct"]  = _gold["change_pct"]
    except Exception as e:
        logger.debug("gold context: %s", e)

    return ctx


def print_market_context(ctx: dict):
    usdrub_str = (
        f"{ctx['usdrub']} ({ctx['usdrub_change_pct']:+.2f}%)"
        if ctx["usdrub"] else "нет данных"
    )
    imoex_str = (
        f"{ctx['imoex']} ({ctx['imoex_change_pct']:+.2f}%)"
        if ctx["imoex"] else "нет данных"
    )
    session_str = "🟢 открыта" if is_moex_open() else "🔴 закрыта"
    brent_str = (f"{ctx['brent']}$ ({ctx['brent_change_pct']:+.2f}%)"
                 if ctx.get("brent") else "нет данных")
    gold_str  = (f"{ctx['gold_rub_gram']}₽/г ({ctx['gold_change_pct']:+.2f}%)"
                 if ctx.get("gold_rub_gram") else "нет данных")
    print(f"\n  💱 USDRUB:    {usdrub_str}")
    print(f"  📈 IMOEX:     {imoex_str}")
    print(f"  🛢️  Brent:     {brent_str}")
    print(f"  🥇 Золото:    {gold_str}")
    lvls = ctx.get("imoex_levels")
    if lvls:
        zone_labels = {
            "near_support":    "🟢 у поддержки",
            "near_resistance": "🔴 у сопротивления",
            "middle":          "⚪ в диапазоне",
        }
        zone_str = zone_labels.get(lvls.get("zone", "middle"), "")
        rsi_str  = f"  RSI={lvls['rsi']}" if lvls.get("rsi") else ""
        n_candles = lvls.get("candles", "?")
        print(
            f"  📊 Тех.уровни ({n_candles} св.): "
            f"S={lvls.get('support')}  R={lvls.get('resistance')}  "
            f"ATR={lvls.get('atr')}  {zone_str}{rsi_str}"
        )
    print(f"  🏦 Ставка ЦБ: {ctx['cbr_rate']}%")
    print(f"  🕐 Сессия:    {session_str}")


