def get_candles(ticker: str, days: int = 21) -> list[dict]:
    date_from = (now_msk() - timedelta(days=days + 10)).strftime("%Y-%m-%d")
    url = (
        f"{BASE_URL}/engines/stock/markets/shares/boards/TQBR"
        f"/securities/{ticker}/candles.json?from={date_from}&interval=24"
    )
    last_error = None
    for attempt in range(3):
        try:
            r = requests.get(url, timeout=10 + attempt * 5)
            r.raise_for_status()
            data = r.json()
            cols   = data["candles"]["columns"]
            candles = [dict(zip(cols, row)) for row in data["candles"]["data"]]
            if attempt:
                logger.info("get_candles(%s): recovered after retry=%d", ticker, attempt)
            return candles[-days:] if len(candles) >= days else candles
        except requests.exceptions.RequestException as e:
            last_error = e
            if attempt < 2:
                logger.warning("get_candles(%s): transient network error, retry %d/2: %s", ticker, attempt + 1, e)
                time.sleep(0.6 * (attempt + 1))
                continue
            break
        except Exception as e:
            print(f"    [!] {ticker}: {e}")
            logger.error("get_candles(%s): %s", ticker, e)
            return []
    print(f"    [!] {ticker}: {last_error}")
    logger.error("get_candles(%s): %s", ticker, last_error)
    return []


def get_h1_candles_moex(ticker: str, days: int = 5) -> list[dict]:
    """
    v0.9.7: Fallback источник H1-свечей через MOEX ISS (interval=60).
    Используется когда T-Invest недоступен или тикер не имеет FIGI (FLOT и др.).
    Возвращает список {"open","close","high","low","value","begin"}.
    """
    date_from = (now_msk() - timedelta(days=days + 3)).strftime("%Y-%m-%d")
    date_to   = now_msk().strftime("%Y-%m-%d")
    url = (
        f"{BASE_URL}/engines/stock/markets/shares/boards/TQBR"
        f"/securities/{ticker}/candles.json"
        f"?from={date_from}&till={date_to}&interval=60"
    )
    try:
        r = requests.get(url, timeout=10)
        r.raise_for_status()
        data  = r.json()
        cols  = data["candles"]["columns"]
        rows  = [dict(zip(cols, row)) for row in data["candles"]["data"]]
        # Нормализуем поля: MOEX ISS отдаёт "begin","open","close","high","low","value"
        result = []
        for c in rows:
            result.append({
                "open":  c.get("open")  or c.get("OPEN"),
                "close": c.get("close") or c.get("CLOSE"),
                "high":  c.get("high")  or c.get("HIGH"),
                "low":   c.get("low")   or c.get("LOW"),
                "value": c.get("value") or c.get("VALUE") or 0.0,
                "begin": c.get("begin") or c.get("BEGIN") or "",
            })
        return result
    except Exception as e:
        logger.debug("get_h1_candles_moex(%s): %s", ticker, e)
        return []


# ─── v0.9.14: Кэш недельных трендов (TTL = WEEKLY_CACHE_TTL_HOURS) ───────────
_weekly_trend_cache: dict[str, dict] = {}  # ticker → {trend, ma5_weekly, ..., _fetched_at}
# ─── v0.9.14: Текущие интрадей-цены (обновляются в run_once каждый скан) ─────
_current_intraday: dict[str, dict] = {}    # ticker → {last, change_pct, vwap, ...}


def get_weekly_trend(ticker: str) -> dict:
    """
    v0.9.14: Недельный тренд тикера через MOEX ISS (interval=7).

    Возвращает dict:
      trend           : "bull" | "bear" | "flat"
      weekly_change   : изменение за последнюю неделю (%)
      ma5_weekly      : MA5 недельных закрытий
      last_close      : последнее недельное закрытие
      candles_count   : число полученных свечей

    Кэш: результат хранится WEEKLY_CACHE_TTL_HOURS часов, затем обновляется.
    При ошибке возвращает {"trend": "flat", ...} — безопасный fallback.
    """
    global _weekly_trend_cache
    now = datetime.now(timezone.utc)

    # Проверяем кэш
    cached = _weekly_trend_cache.get(ticker)
    if cached:
        fetched_at = cached.get("_fetched_at")
        if fetched_at and (now - fetched_at).total_seconds() < WEEKLY_CACHE_TTL_HOURS * 3600:
            return cached

    _empty = {"trend": "flat", "weekly_change": 0.0,
              "ma5_weekly": None, "last_close": None, "candles_count": 0}

    try:
        from_date = (now_msk() - timedelta(weeks=12)).strftime("%Y-%m-%d")
        today     = now_msk().strftime("%Y-%m-%d")
        url = (
            f"{BASE_URL}/engines/stock/markets/shares/boards/TQBR"
            f"/securities/{ticker}/candles.json"
            f"?from={from_date}&till={today}&interval=7"
        )
        r = requests.get(url, timeout=10)
        r.raise_for_status()
        data    = r.json()
        cols    = data["candles"]["columns"]
        candles = [dict(zip(cols, row)) for row in data["candles"]["data"]]

        if len(candles) < 3:
            result = {**_empty, "_fetched_at": now}
            _weekly_trend_cache[ticker] = result
            return result

        closes = [float(c.get("close") or 0) for c in candles if c.get("close")]
        if len(closes) < 3:
            result = {**_empty, "_fetched_at": now}
            _weekly_trend_cache[ticker] = result
            return result

        # MA5 (или меньше свечей если данных нет)
        n    = min(5, len(closes))
        ma5  = sum(closes[-n:]) / n
        last = closes[-1]
        prev = closes[-2]
        weekly_change = round((last - prev) / prev * 100, 2) if prev else 0.0

        # Тренд: цена vs MA5, буфер ±0.3% для флэта
        if   last > ma5 * 1.003:  trend = "bull"
        elif last < ma5 * 0.997:  trend = "bear"
        else:                     trend = "flat"

        result = {
            "trend":         trend,
            "weekly_change": weekly_change,
            "ma5_weekly":    round(ma5, 2),
            "last_close":    round(last, 2),
            "candles_count": len(candles),
            "_fetched_at":   now,
        }
        _weekly_trend_cache[ticker] = result
        logger.debug("weekly_trend(%s): %s  MA5=%.2f  last=%.2f  Δ%+.1f%%",
                     ticker, trend.upper(), ma5, last, weekly_change)
        return result

    except Exception as e:
        logger.debug("get_weekly_trend(%s): %s", ticker, e)
        result = {**_empty, "_fetched_at": now}
        _weekly_trend_cache[ticker] = result
        return result


def calc_vwap(candles: list[dict]) -> float | None:
    """
    VWAP = Σ(типичная_цена × объём) / Σ(объём)
    типичная_цена = (High + Low + Close) / 3

    Приоритет весов:
      1. "volume" — количество лотов/акций (если > 0)
      2. "value"  — оборот в рублях (если volume недоступен)
         Прокси: weight = value / typical (≈ количество акций по средней цене)
    """
    pv_sum = 0.0
    v_sum  = 0.0
    for c in candles:
        h   = c.get("high")  or 0.0
        lo  = c.get("low")   or 0.0
        cl  = c.get("close") or 0.0
        vol = c.get("volume") or 0
        val = c.get("value")  or 0.0
        if not (h and lo and cl):
            continue
        typical = (h + lo + cl) / 3.0
        weight  = vol if vol > 0 else (val / typical if (val > 0 and typical > 0) else 0.0)
        if weight <= 0:
            continue
        pv_sum += typical * weight
        v_sum  += weight
    if v_sum == 0:
        return None
    return round(pv_sum / v_sum, 2)


def get_intraday_price(ticker: str) -> dict:
    """10-минутные свечи текущего дня → дневное изменение цены + VWAP."""
    today = now_msk().strftime("%Y-%m-%d")
    url = (
        f"{BASE_URL}/engines/stock/markets/shares/boards/TQBR"
        f"/securities/{ticker}/candles.json?from={today}&till={today}&interval=10"
    )
    try:
        r = requests.get(url, timeout=10)
        r.raise_for_status()
        data    = r.json()
        cols    = data["candles"]["columns"]
        rows    = data["candles"]["data"]
        if not rows:
            return {}
        candles    = [dict(zip(cols, row)) for row in rows]
        open_price = candles[0]["open"]
        last_price = candles[-1]["close"]
        change_pct = (last_price - open_price) / open_price * 100
        vwap       = calc_vwap(candles)
        rebound    = calc_intraday_rebound(candles)
        volumes = [float(c.get("value") or 0) for c in candles]
        recent_window = max(1, min(6, len(volumes)))
        avg_hourly_volume = round(sum(volumes) / len(volumes), 2) if volumes else 0.0
        current_window_volume = round(sum(volumes[-recent_window:]), 2) if volumes else 0.0
        last_begin = candles[-1].get("begin") or ""
        return {
            "open":       round(open_price, 2),
            "last":       round(last_price, 2),
            "change_pct": round(change_pct, 2),
            "vwap":       vwap,
            **rebound,
            "candle_count": len(candles),
            "last_begin": last_begin,
            "volume": current_window_volume,
            "avg_hourly_volume": avg_hourly_volume,
        }
    except Exception as e:
        logger.warning("get_intraday_price(%s): %s", ticker, e)
        return {}


def calc_intraday_rebound(candles: list[dict]) -> dict:
    """Intraday rebound metrics from the current day's low."""
    if not candles:
        return {}
    low_idx, low_candle = min(
        enumerate(candles),
        key=lambda item: item[1].get("low") if item[1].get("low") is not None else float("inf"),
    )
    low = low_candle.get("low")
    last = candles[-1].get("close")
    if not low or not last:
        return {}
    after_low = candles[low_idx:]
    high_after_low = max((c.get("high") or 0) for c in after_low) if after_low else 0
    return {
        "intraday_low": round(low, 2),
        "intraday_low_time": str(low_candle.get("begin") or "")[11:16],
        "rebound_from_low_pct": round((last - low) / low * 100, 2),
        "rebound_high_from_low_pct": round((high_after_low - low) / low * 100, 2) if high_after_low else None,
    }


def get_index_intraday_context() -> dict:
    """10-minute IMOEX context for broad-market rebound diagnostics."""
    today = now_msk().strftime("%Y-%m-%d")
    url = (
        f"{BASE_URL}/engines/stock/markets/index/boards/SNDX"
        f"/securities/IMOEX/candles.json?from={today}&till={today}&interval=10"
    )
    try:
        r = requests.get(url, timeout=10)
        r.raise_for_status()
        data = r.json()
        cols = data["candles"]["columns"]
        rows = data["candles"]["data"]
        if not rows:
            return {}
        candles = [dict(zip(cols, row)) for row in rows]
        open_price = candles[0]["open"]
        last_price = candles[-1]["close"]
        rebound = calc_intraday_rebound(candles)
        return {
            "ticker": "IMOEX",
            "open": round(open_price, 2),
            "last": round(last_price, 2),
            "change_pct": round((last_price - open_price) / open_price * 100, 2),
            "vwap": calc_vwap(candles),
            "candle_count": len(candles),
            "last_begin": candles[-1].get("begin") or "",
            **rebound,
        }
    except Exception as e:
        logger.warning("get_index_intraday_context(IMOEX): %s", e)
        return {}


def calc_rsi(closes: list[float], period: int = RSI_PERIOD) -> float | None:
    """
    RSI по методу Уайлдера — EMA-сглаженное среднее прибылей/убытков.
    Отличие от простого SMA: даёт более плавный и точный RSI.
    """
    if len(closes) < period + 1:
        return None
    deltas = [closes[i] - closes[i - 1] for i in range(1, len(closes))]
    gains  = [max(d, 0.0) for d in deltas]
    losses = [abs(min(d, 0.0)) for d in deltas]

    # Первое значение — SMA за period свечей
    avg_gain = mean(gains[:period])
    avg_loss = mean(losses[:period])

    # Сглаживаем по Уайлдеру (EMA с alpha = 1/period)
    for i in range(period, len(gains)):
        avg_gain = (avg_gain * (period - 1) + gains[i]) / period
        avg_loss = (avg_loss * (period - 1) + losses[i]) / period

    if avg_loss == 0:
        return 100.0
    rs = avg_gain / avg_loss
    return round(100 - (100 / (1 + rs)), 1)


def calc_ma(closes: list[float], period: int = MA_PERIOD) -> float | None:
    if len(closes) < period:
        return None
    return round(mean(closes[-period:]), 2)


def calc_adx(candles: list[dict], period: int = 14) -> float | None:
    """
    ADX(14) по методу Уайлдера — измеряет СИЛУ тренда (не направление).
    ADX < 20: флэт/слабый тренд (mean-reversion предпочтительна)
    ADX 20–25: умеренный тренд
    ADX > 25: сильный тренд (momentum предпочтительна)
    ADX > 40: очень сильный тренд (осторожно — возможна коррекция)
    Требует минимум 2×period+1 свечей (~29 дней).
    """
    if len(candles) < period * 2 + 1:
        return None
    highs  = [c["high"]  for c in candles if c.get("high")  and c.get("low") and c.get("close")]
    lows   = [c["low"]   for c in candles if c.get("high")  and c.get("low") and c.get("close")]
    closes = [c["close"] for c in candles if c.get("high")  and c.get("low") and c.get("close")]
    if len(highs) < period * 2 + 1:
        return None

    tr_list, pdm_list, mdm_list = [], [], []
    for i in range(1, len(highs)):
        h, l, pc = highs[i], lows[i], closes[i - 1]
        tr = max(h - l, abs(h - pc), abs(l - pc))
        pdm = max(highs[i] - highs[i - 1], 0.0) if (highs[i] - highs[i - 1]) > (lows[i - 1] - lows[i]) else 0.0
        mdm = max(lows[i - 1] - lows[i], 0.0) if (lows[i - 1] - lows[i]) > (highs[i] - highs[i - 1]) else 0.0
        tr_list.append(tr)
        pdm_list.append(pdm)
        mdm_list.append(mdm)

    # Wilder smoothing: начальное значение — SMA за period
    atr_w  = mean(tr_list[:period])
    pdm_w  = mean(pdm_list[:period])
    mdm_w  = mean(mdm_list[:period])

    dx_list = []
    for i in range(period, len(tr_list)):
        atr_w = (atr_w * (period - 1) + tr_list[i])  / period
        pdm_w = (pdm_w * (period - 1) + pdm_list[i]) / period
        mdm_w = (mdm_w * (period - 1) + mdm_list[i]) / period
        pdi = 100 * pdm_w / atr_w if atr_w else 0
        mdi = 100 * mdm_w / atr_w if atr_w else 0
        dx  = 100 * abs(pdi - mdi) / (pdi + mdi) if (pdi + mdi) else 0
        dx_list.append(dx)

    if len(dx_list) < period:
        return None

    # ADX = Wilder EMA(DX) за period
    adx = mean(dx_list[:period])
    for dx in dx_list[period:]:
        adx = (adx * (period - 1) + dx) / period
    return round(adx, 1)


def get_session_quality() -> tuple[float, str]:
    """
    Качество торговой сессии МОСБИРЖА по времени дня (v0.9.5).
    Возвращает (score_bonus, label) — bonus добавляется к score сигнала.
    Основано на статистике МОСБИРЖА: наибольший объём 10:30–12:00 и 14:00–17:00.
    """
    current = now_msk()
    h, m = current.hour, current.minute
    t = h + m / 60.0  # дробное время в часах

    if 10.5 <= t < 12.0:
        return 1, "10:30–12:00 🟢 прайм"    # утренний импульс — максимальный объём
    elif 14.0 <= t < 17.0:
        return 1, "14:00–17:00 🟢 прайм"    # послеобеденный тренд, европейская сессия
    elif 10.0 <= t < 10.5:
        return 0, "10:00–10:30 🟡 открытие" # открытие — высокая волатильность, осторожно
    elif 12.0 <= t < 14.0:
        return 0, "12:00–14:00 🟡 обед"     # обеденный флэт
    elif 17.0 <= t < 18.5:
        return 0, "17:00–18:30 🟡 закрытие" # предзакрытие, тренды теряют силу
    elif is_moex_open():
        return 0, "внутри сессии"
    else:
        return 0, "вне сессии"


def determine_direction(price: float, levels: dict) -> tuple[str, str]:
    """
    Определяет направление сигнала и его тип (v0.9.4).

    Логика:
      • Цена ВЫШЕ MA50 + RSI не экстремален (< 82) → momentum LONG  (тренд вверх)
      • Цена НИЖЕ MA50 + RSI не экстремален (> 18) → momentum SHORT (тренд вниз)
      • RSI перепродан (< 30)                       → mean_reversion LONG  (отскок)
      • RSI перекуплен (> 70)                       → mean_reversion SHORT (откат)
      • Иначе                                       → range-based (середина диапазона)

    Возвращает: (direction, signal_type)
      direction:   "LONG" | "SHORT"
      signal_type: "momentum" | "mean_reversion"
    """
    ma50       = levels.get("ma50")
    rsi        = levels.get("rsi")
    support    = levels.get("support", 0)
    resistance = levels.get("resistance", 0)

    # Momentum: RSI должен быть в «здоровой» зоне тренда.
    # LONG: цена выше MA50, RSI не перекуплен экстремально (< 82)
    # SHORT: цена ниже MA50, RSI не перепродан (> RSI_OVERSOLD=30) — не шортим уже перепроданное
    if ma50 and price > ma50 and (rsi is None or rsi < 82):
        return "LONG", "momentum"
    if ma50 and price < ma50 and (rsi is None or rsi > RSI_OVERSOLD):
        return "SHORT", "momentum"
    # Экстремальный RSI — mean-reversion отскок/откат
    if rsi and rsi < RSI_OVERSOLD:
        return "LONG", "mean_reversion"
    if rsi and rsi > RSI_OVERBOUGHT:
        return "SHORT", "mean_reversion"
    # Дефолт: середина диапазона (как в v0.9.3)
    mid = (support + resistance) / 2 if support and resistance else price
    return ("LONG" if price < mid else "SHORT"), "mean_reversion"


def detect_volume_anomaly(candles: list[dict], ticker: str = "") -> dict:
    """
    Определяет аномальный объём.
    v0.9.7: минимальный порог берётся из MIN_VOL_RUB_MAP (по тикеру),
            с фолбэком на глобальный MIN_VOLUME_RUB.
    """
    volumes = [c["value"] for c in candles if c.get("value")]
    if len(volumes) < 3:
        return {"anomaly": False}
    last_vol  = volumes[-1]
    avg_vol   = mean(volumes[:-1])
    ratio     = last_vol / avg_vol if avg_vol > 0 else 0
    # v0.9.7: per-ticker порог вместо единого глобального
    min_vol   = MIN_VOL_RUB_MAP.get(ticker, MIN_VOLUME_RUB)
    absolute_ok = last_vol >= min_vol
    return {
        "anomaly":     ratio >= VOLUME_THRESHOLD and absolute_ok,
        "ratio":       round(ratio, 2),
        "last_volume": last_vol,
        "avg_volume":  round(avg_vol, 0),
        "absolute_ok": absolute_ok,
        "min_vol_used": min_vol,
    }


def calc_obv(candles: list[dict]) -> dict:
    """
    v0.9.29: On-Balance Volume (OBV) — накопление/распределение объёма.

    Логика: если цена закрытия выше предыдущей → объём прибавляем (покупатели),
    ниже → вычитаем (продавцы). OBV растёт без роста цены = скрытое накопление.

    Возвращает:
      obv_trend   : "up" | "down" | "flat"  — направление OBV за 5 дней
      obv_bull_div: True если OBV ↑ а цена ↓ (бычья дивергенция → LONG сигнал)
      obv_bear_div: True если OBV ↓ а цена ↑ (медвежья дивергенция → SHORT сигнал)
    """
    if len(candles) < 6:
        return {"obv_trend": "flat", "obv_bull_div": False, "obv_bear_div": False}

    obv = 0.0
    obv_series: list[float] = []
    for i, c in enumerate(candles):
        vol = c.get("value", 0) or 0
        if i == 0:
            obv_series.append(0.0)
            continue
        if (c.get("close") or 0) > (candles[i - 1].get("close") or 0):
            obv += vol
        elif (c.get("close") or 0) < (candles[i - 1].get("close") or 0):
            obv -= vol
        obv_series.append(obv)

    if len(obv_series) < 5:
        return {"obv_trend": "flat", "obv_bull_div": False, "obv_bear_div": False}

    # OBV тренд за последние 5 дней
    obv_recent   = obv_series[-5:]
    obv_slope    = obv_recent[-1] - obv_recent[0]
    obv_trend    = "up" if obv_slope > 0 else ("down" if obv_slope < 0 else "flat")

    # Ценовой тренд за те же 5 дней
    price_recent = [c.get("close", 0) or 0 for c in candles[-5:]]
    price_slope  = price_recent[-1] - price_recent[0] if price_recent else 0

    # Дивергенции
    bull_div = obv_slope > 0 and price_slope < 0   # OBV растёт, цена падает → накопление
    bear_div = obv_slope < 0 and price_slope > 0   # OBV падает, цена растёт → распределение

    return {
        "obv_trend":    obv_trend,
        "obv_bull_div": bull_div,
        "obv_bear_div": bear_div,
    }


def detect_ma_crossover(candles: list[dict]) -> str | None:
    """
    v0.9.29: Детектор пересечения MA20/MA50 — Golden Cross и Death Cross.

    Golden Cross: MA20 пересекает MA50 снизу вверх → долгосрочный LONG сигнал.
    Death Cross:  MA20 пересекает MA50 сверху вниз → долгосрочный SHORT сигнал.

    Проверяем факт пересечения за последние 2 свечи:
    Вчера MA20 ≤ MA50, сегодня MA20 > MA50 → golden_cross.
    Вчера MA20 ≥ MA50, сегодня MA20 < MA50 → death_cross.

    Требует ≥ 52 свечей (50 для MA50 + 2 сравнения).
    """
    closes = [c.get("close") for c in candles if c.get("close")]
    if len(closes) < 52:
        return None

    ma20_now  = sum(closes[-20:]) / 20
    ma50_now  = sum(closes[-50:]) / 50
    ma20_prev = sum(closes[-21:-1]) / 20
    ma50_prev = sum(closes[-51:-1]) / 50

    if ma20_prev <= ma50_prev and ma20_now > ma50_now:
        return "golden_cross"   # MA20 пробила MA50 снизу вверх
    if ma20_prev >= ma50_prev and ma20_now < ma50_now:
        return "death_cross"    # MA20 пробила MA50 сверху вниз
    return None


def calc_bb_squeeze(closes: list[float], period: int = 20) -> bool:
    """
    v0.9.8: Bollinger Band Squeeze — детектор сжатия и последующего прорыва.

    Алгоритм:
      1. Вычисляем ширину BB (upper-lower)/MA для последних 15 скользящих окон.
      2. "Сжатие" = в окнах 1–10 (1 = 1 свеча назад) ширина < 70% от средней исторической.
      3. "Прорыв" = текущее окно (lag=0) ширина > предыдущего * 1.05 — полосы расходятся.
      Возвращает True если оба условия выполнены — надёжный пробой из зоны низкой волатильности.
    """
    if len(closes) < period + 10:
        return False

    def _width(window: list[float]) -> float | None:
        if len(window) < period:
            return None
        ma  = sum(window) / period
        std = (sum((x - ma) ** 2 for x in window) / period) ** 0.5
        return (4.0 * std) / ma if ma > 0 else 0.0

    widths: list[float] = []
    for lag in range(15):
        end   = len(closes) - lag
        start = end - period
        if start < 0:
            break
        w = _width(closes[start:end])
        if w is not None:
            widths.append(w)

    if len(widths) < 5:
        return False

    hist_avg      = sum(widths) / len(widths)
    squeeze_zone  = any(w < hist_avg * 0.70 for w in widths[1:10])  # было сжатие?
    expanding_now = len(widths) >= 2 and widths[0] > widths[1] * 1.05  # сейчас расширяется?
    return squeeze_zone and expanding_now


def calc_levels(candles: list[dict]) -> dict:
    highs  = [c["high"]  for c in candles if c.get("high")]
    lows   = [c["low"]   for c in candles if c.get("low")]
    closes = [c["close"] for c in candles if c.get("close")]
    if not highs:
        return {}
    atr  = mean([h - l for h, l in zip(highs, lows)])
    obv_data     = calc_obv(candles)        # v0.9.29: OBV накопление/распределение
    ma_cross     = detect_ma_crossover(candles)  # v0.9.29: Golden/Death cross
    return {
        "resistance":    round(max(highs), 2),
        "support":       round(min(lows), 2),
        "atr":           round(atr, 2),
        "last_close":    round(closes[-1], 2) if closes else None,
        "rsi":           calc_rsi(closes),
        "ma20":          calc_ma(closes),
        "ma50":          calc_ma(closes, 50),
        "adx":           calc_adx(candles),       # v0.9.5: сила тренда
        "bb_squeeze":    calc_bb_squeeze(closes),  # v0.9.8: сжатие BB
        "obv_trend":     obv_data["obv_trend"],    # v0.9.29: направление OBV
        "obv_bull_div":  obv_data["obv_bull_div"], # v0.9.29: бычья дивергенция
        "obv_bear_div":  obv_data["obv_bear_div"], # v0.9.29: медвежья дивергенция
        "ma_crossover":  ma_cross,                 # v0.9.29: "golden_cross" | "death_cross" | None
    }


def calc_h1_levels(h1_candles: list[dict]) -> dict | None:
    """
    Анализирует H1 свечи: находит ближайшие локальные max/min как уровни.
    Логика: скользящее окно 3 свечи — локальный max если high[i] > high[i-1] и high[i] > high[i+1].
    Берём 5 последних локальных уровней каждого типа, возвращаем ближайший к текущей цене.

    Returns: {"h1_resistance", "h1_support", "h1_atr", "h1_candles_count"} или None
    """
    if len(h1_candles) < 5:
        return None

    highs  = [c["high"]  for c in h1_candles if c.get("high")]
    lows   = [c["low"]   for c in h1_candles if c.get("low")]

    if not highs:
        return None

    # Локальные максимумы (pivot high)
    pivot_highs: list[float] = []
    for i in range(1, len(highs) - 1):
        if highs[i] > highs[i-1] and highs[i] > highs[i+1]:
            pivot_highs.append(highs[i])

    # Локальные минимумы (pivot low)
    pivot_lows: list[float] = []
    for i in range(1, len(lows) - 1):
        if lows[i] < lows[i-1] and lows[i] < lows[i+1]:
            pivot_lows.append(lows[i])

    # Берём последние 5 уровней каждого типа (наиболее актуальные)
    recent_highs = pivot_highs[-5:] if pivot_highs else []
    recent_lows  = pivot_lows[-5:]  if pivot_lows  else []

    current      = h1_candles[-1].get("close", 0)
    h1_atr       = round(mean([h - l for h, l in zip(highs, lows)]), 2) if highs else None

    # Ближайшее сопротивление — ближайший pivot_high ВЫШЕ текущей цены
    resistances_above = [h for h in recent_highs if h > current]
    h1_resistance     = round(min(resistances_above), 2) if resistances_above else round(max(recent_highs), 2) if recent_highs else None

    # Ближайшая поддержка — ближайший pivot_low НИЖЕ текущей цены
    supports_below    = [l for l in recent_lows if l < current]
    h1_support        = round(max(supports_below), 2) if supports_below else round(min(recent_lows), 2) if recent_lows else None

    return {
        "h1_resistance":    h1_resistance,
        "h1_support":       h1_support,
        "h1_atr":           h1_atr,
        "h1_candles_count": len(h1_candles),
    }


def calc_position_size(entry: float, stop: float, lot_size: int = 1) -> dict | None:
    """
    Калькулятор размера позиции по формуле фиксированного % риска.
    Использует DEPOSIT_RUB и RISK_PCT из конфига.
    Возвращает None если DEPOSIT_RUB не задан (= 0).

    Формула: кол-во лотов = (депозит × риск%) / (|entry - stop| × lot_size)
    """
    if DEPOSIT_RUB <= 0 or entry <= 0 or stop <= 0:
        return None
    stop_dist = abs(entry - stop)
    if stop_dist <= 0:
        return None

    risk_rub     = DEPOSIT_RUB * RISK_PCT / 100.0
    lots         = int(risk_rub / (stop_dist * lot_size))
    lots         = max(1, lots)           # минимум 1 лот
    position_rub = lots * lot_size * entry
    actual_risk  = round(lots * lot_size * stop_dist, 0)
    actual_risk_pct = round(actual_risk / DEPOSIT_RUB * 100, 2)

    return {
        "deposit_rub":      DEPOSIT_RUB,
        "risk_pct":         RISK_PCT,
        "risk_rub":         round(risk_rub, 0),
        "lots":             lots,
        "lot_size":         lot_size,
        "position_rub":     round(position_rub, 0),
        "actual_risk_rub":  actual_risk,
        "actual_risk_pct":  actual_risk_pct,
    }


def rsi_label(rsi: float | None) -> str:
    if rsi is None:
        return ""
    if rsi >= RSI_OVERBOUGHT:
        return f"RSI {rsi} 🔴 перекуплен"
    if rsi <= RSI_OVERSOLD:
        return f"RSI {rsi} 🟢 перепродан"
    return f"RSI {rsi}"


def _avoid_round_number_stop(stop: float, price: float, direction: str) -> float:
    """
    v0.9.14: Физики ставят стопы на круглых числах (650.00, 38.00, 1400.00).
    Маркет-мейкеры знают об этом и "охотятся" за этими уровнями.
    Смещаем свой стоп на ROUND_STOP_BUFFER (0.3%) дальше от ближайшего круглого числа.

    Логика: для каждого порога (1000, 500, 100, 50, 10, 5, 1) находим ближайший
    кратный уровень. Если стоп в пределах 0.3% от него — отодвигаем ещё на 0.3%.
    """
    ROUND_STOP_BUFFER = 0.003  # 0.3% буфер от круглого числа

    # Определяем подходящий "шаг круглости" по цене
    if   price >= 5000:  round_steps = [1000, 500, 100]
    elif price >= 1000:  round_steps = [500,  100,  50]
    elif price >= 100:   round_steps = [100,   50,  10]
    elif price >= 10:    round_steps = [10,     5,   1]
    else:                round_steps = [5,    1,   0.5]

    for step in round_steps:
        nearest = round(round(stop / step) * step, 4)
        if abs(stop - nearest) / max(price, 1e-9) < ROUND_STOP_BUFFER:
            # Стоп слишком близко к круглому уровню — двигаем дальше
            buf = price * ROUND_STOP_BUFFER
            if direction == "LONG":
                new_stop = round(nearest - buf, 2)   # чуть ниже
            else:
                new_stop = round(nearest + buf, 2)   # чуть выше
            logger.info(
                "round_stop_guard: стоп %.2f → %.2f (далеко от круглого %s, шаг=%s)",
                stop, new_stop, nearest, step,
            )
            return new_stop

    return stop


def _validate_entry(ticker: str, entry: float, last_price: float | None,
                    tol: float = 0.05) -> float:
    """
    v0.9.36: Sanity-чек entry против last_price.

    Кейс 16.04.2026: OZON entry=4368 при реальной цене 548 ₽ (ratio ×8).
    Причина пока не выяснена (возможно, получили котировку с другого инструмента
    с тем же тикером, либо где-то в пайплайне умножается на lot/notional).
    Этот guard защищает от проблемы до выяснения корневой причины.

    Если отклонение >×5 или <×0.2 — возвращаем last_price (с ERROR в лог).
    Если 5%..×5 — WARNING, но entry не меняем (может быть запаздывание котировки).
    """
    if not last_price or last_price <= 0:
        return entry
    if not entry or entry <= 0:
        logger.error("[%s] entry=%r некорректный → using last_price=%s",
                     ticker, entry, last_price)
        return last_price
    ratio = entry / last_price
    if ratio > 5 or ratio < 0.2:
        logger.error(
            "[%s] entry_sanity FAIL: entry=%s last=%s ratio=×%.2f → using last_price",
            ticker, entry, last_price, ratio,
        )
        return last_price
    if abs(ratio - 1) > tol:
        logger.warning(
            "[%s] entry отклонение от last >%d%%: entry=%s last=%s (ratio=×%.2f)",
            ticker, int(tol * 100), entry, last_price, ratio,
        )
    return entry


def build_market_signal(
    ticker: str,
    levels: dict,
    anomaly: dict,
    ctx: dict,
    intraday: dict | None = None,
    h1_levels: dict | None = None,
    h1_confirm: dict | None = None,   # v0.9.3: {"type": "breakout"|"momentum", "note": ...}
    direction_override: str | None = None,
    signal_type_override: str | None = None,
    signal_kind: str = "VOLUME",
) -> dict | None:
    """
    intraday — результат get_intraday_price(ticker): {"open", "last", "change_pct", "vwap"}
    Если передан — используем intraday["last"] как entry-цену и считаем VWAP-фильтр.
    Если нет — entry из daily close (как раньше).

    h1_levels — результат calc_h1_levels() (v0.9.2): {"h1_resistance", "h1_support", ...}
    Используется для уточнения стопа за структурный уровень и подтверждения направления.

    h1_confirm — результат check_h1_confirmation() (v0.9.3):
    {"type": "breakout"|"momentum", "h1_close": ..., "note": ...}
    Если передан — сигнал уже прошёл H1-фильтр.
    Если None — сигнал без H1-подтверждения (watch-mode или T-Invest недоступен).
    """
    if not anomaly.get("anomaly"):
        return None
    decision_reasons: list[str] = []
    data_quality_flags: list[str] = []
    price      = levels.get("last_close")
    support    = levels.get("support")
    resistance = levels.get("resistance")
    atr        = levels.get("atr", 0)
    rsi        = levels.get("rsi")
    ma20       = levels.get("ma20")
    ma50       = levels.get("ma50")
    if not all([price, support, resistance, atr]):
        return None

    # Уточняем цену входа по intraday (точнее daily close)
    if intraday and intraday.get("last"):
        price = intraday["last"]
        decision_reasons.append("intraday_price_used")
    else:
        data_quality_flags.append("intraday_missing")

    # v0.9.36: Sanity-guard против абсурдных entry (кейс OZON 16.04: 4368 vs 548).
    original_price = price
    price = _validate_entry(ticker, price, intraday.get("last") if intraday else None)
    if original_price != price:
        data_quality_flags.append("invalid_price")
        decision_reasons.append("invalid_price_guard")

    if intraday and intraday.get("last_begin"):
        try:
            last_begin = datetime.fromisoformat(str(intraday["last_begin"]).replace("Z", "+00:00"))
            last_begin_msk = last_begin.astimezone(_MSK_TZ)
            if is_moex_open() and (now_msk() - last_begin_msk) > timedelta(minutes=30):
                data_quality_flags.append("stale_intraday")
                decision_reasons.append("stale_intraday")
        except ValueError:
            data_quality_flags.append("intraday_timestamp_invalid")

    # v0.9.4: умное определение направления с учётом MA50-тренда
    direction, signal_type = determine_direction(price, levels)
    if direction_override in ("LONG", "SHORT"):
        direction = direction_override
    if signal_type_override in ("momentum", "mean_reversion"):
        signal_type = signal_type_override
    decision_reasons.append(f"signal_type:{signal_type}")

    # RSI подтверждение: для momentum — расширенный диапазон (тренд может держать RSI высоко)
    rsi_confirm = True
    if signal_type == "momentum":
        if direction == "LONG"  and rsi and rsi >= 82:
            rsi_confirm = False   # RSI экстремально перекуплен даже для momentum
        if direction == "SHORT" and rsi and rsi <= 18:
            rsi_confirm = False   # RSI экстремально перепродан даже для momentum
    else:
        if direction == "LONG"  and rsi and rsi > RSI_OVERBOUGHT:
            rsi_confirm = False
        if direction == "SHORT" and rsi and rsi < RSI_OVERSOLD:
            rsi_confirm = False

    # MA20 тренд
    ma_trend = None
    if ma20:
        ma_trend = "bullish" if price > ma20 else "bearish"

    # MA50 тренд-фильтр (v0.9.2 — идея #2)
    # Торгуем против тренда MA50 = снижаем уверенность
    ma50_trend  = None
    ma50_note   = None
    ma50_against = False
    if ma50:
        ma50_trend = "bullish" if price > ma50 else "bearish"
        if MA50_TREND_FILTER:
            if direction == "LONG"  and ma50_trend == "bearish":
                ma50_against = True
                ma50_note    = f"MA50 {ma50:.1f} — тренд нисходящий, LONG против тренда ⚠️"
                decision_reasons.append("ma50_against")
            elif direction == "SHORT" and ma50_trend == "bullish":
                ma50_against = True
                ma50_note    = f"MA50 {ma50:.1f} — тренд восходящий, SHORT против тренда ⚠️"
                decision_reasons.append("ma50_against")
            elif direction == "LONG"  and ma50_trend == "bullish":
                ma50_note    = f"MA50 {ma50:.1f} — тренд восходящий, LONG по тренду ✅"
            elif direction == "SHORT" and ma50_trend == "bearish":
                ma50_note    = f"MA50 {ma50:.1f} — тренд нисходящий, SHORT по тренду ✅"

    # USDRUB влияние для экспортёров
    usdrub_note    = None
    usdrub_confirm = None
    usd_chg = ctx.get("usdrub_change_pct")
    if usd_chg is not None and ticker in EXPORTER_TICKERS:
        if usd_chg >= 0.5 and direction == "LONG":
            usdrub_confirm = True
            usdrub_note    = f"₽ −{usd_chg}% → поддерживает LONG экспортёра"
        elif usd_chg >= 0.5 and direction == "SHORT":
            usdrub_confirm = False
            usdrub_note    = f"₽ −{usd_chg}% → против SHORT экспортёра"
        elif usd_chg <= -0.5 and direction == "SHORT":
            usdrub_confirm = True
            usdrub_note    = f"₽ +{abs(usd_chg)}% → поддерживает SHORT экспортёра"
        elif usd_chg <= -0.5 and direction == "LONG":
            usdrub_confirm = False
            usdrub_note    = f"₽ +{abs(usd_chg)}% → против LONG экспортёра"

    # v0.9.29: Brent нефть — влияние на нефтегазовые тикеры
    brent_note    = None
    brent_confirm = None   # None=нейтр., True=подтверждает, False=против
    brent_chg = ctx.get("brent_change_pct")
    if brent_chg is not None and ticker in OIL_TICKERS:
        brent_price = ctx.get("brent", "?")
        if brent_chg >= 1.5 and direction == "LONG":
            brent_confirm = True
            brent_note    = f"Brent {brent_price}$ +{brent_chg}% → LONG нефтяника усилен"
        elif brent_chg >= 1.5 and direction == "SHORT":
            brent_confirm = False
            brent_note    = f"Brent {brent_price}$ +{brent_chg}% → против SHORT нефтяника"
        elif brent_chg <= -1.5 and direction == "SHORT":
            brent_confirm = True
            brent_note    = f"Brent {brent_price}$ {brent_chg}% → SHORT нефтяника усилен"
        elif brent_chg <= -1.5 and direction == "LONG":
            brent_confirm = False
            brent_note    = f"Brent {brent_price}$ {brent_chg}% → против LONG нефтяника"

    # v0.9.29: Золото — влияние на PLZL (Полюс Золото)
    gold_note    = None
    gold_confirm = None
    gold_chg = ctx.get("gold_change_pct")
    if gold_chg is not None and ticker == "PLZL":
        gold_price = ctx.get("gold_rub_gram", "?")
        if gold_chg >= 1.0 and direction == "LONG":
            gold_confirm = True
            gold_note    = f"Золото {gold_price}₽/г +{gold_chg}% → LONG PLZL усилен"
        elif gold_chg >= 1.0 and direction == "SHORT":
            gold_confirm = False
            gold_note    = f"Золото {gold_price}₽/г +{gold_chg}% → против SHORT PLZL"
        elif gold_chg <= -1.0 and direction == "SHORT":
            gold_confirm = True
            gold_note    = f"Золото {gold_price}₽/г {gold_chg}% → SHORT PLZL усилен"
        elif gold_chg <= -1.0 and direction == "LONG":
            gold_confirm = False
            gold_note    = f"Золото {gold_price}₽/г {gold_chg}% → против LONG PLZL"

    # IMOEX: дневной фон + технические уровни (top-down анализ, добавлено в v0.8)
    imoex_note    = None
    imoex_confirm = None   # None=нейтрально, True=подтверждает, False=против
    imoex_chg     = ctx.get("imoex_change_pct")
    imoex_lvls    = ctx.get("imoex_levels")

    # 1. Дневное изменение — базовый фон
    if imoex_chg is not None:
        if imoex_chg <= -1.5 and direction == "SHORT":
            imoex_note    = f"IMOEX {imoex_chg:+.1f}% — медвежий фон, SHORT сильнее"
            imoex_confirm = True
        elif imoex_chg >= 1.5 and direction == "LONG":
            imoex_note    = f"IMOEX {imoex_chg:+.1f}% — бычий фон, LONG сильнее"
            imoex_confirm = True
        elif imoex_chg <= -1.5 and direction == "LONG":
            imoex_note    = f"IMOEX {imoex_chg:+.1f}% — медвежий фон против LONG"
            imoex_confirm = False
        elif imoex_chg >= 1.5 and direction == "SHORT":
            imoex_note    = f"IMOEX {imoex_chg:+.1f}% — бычий фон против SHORT"
            imoex_confirm = False

    # 2. Технические уровни IMOEX — точный уровневый анализ (приоритетнее дневного %)
    if imoex_lvls:
        zone      = imoex_lvls.get("zone", "middle")
        imoex_r   = imoex_lvls.get("resistance")
        imoex_s   = imoex_lvls.get("support")
        imoex_rsi = imoex_lvls.get("rsi")
        zone_notes: list[str] = []

        if zone == "near_resistance":
            if direction == "LONG":
                zone_notes.append(f"индекс у сопротивления {imoex_r} — осторожно LONG")
                imoex_confirm = False
            else:
                zone_notes.append(f"индекс у сопротивления {imoex_r} — SHORT усилен")
                imoex_confirm = True
        elif zone == "near_support":
            if direction == "SHORT":
                zone_notes.append(f"индекс у поддержки {imoex_s} — осторожно SHORT")
                imoex_confirm = False
            else:
                zone_notes.append(f"индекс у поддержки {imoex_s} — LONG усилен")
                imoex_confirm = True

        # RSI индекса как дополнительный фильтр
        if imoex_rsi:
            if imoex_rsi > RSI_OVERBOUGHT and direction == "LONG":
                zone_notes.append(f"RSI индекса {imoex_rsi} перекуплен")
                if imoex_confirm is not False:
                    imoex_confirm = False
            elif imoex_rsi < RSI_OVERSOLD and direction == "SHORT":
                zone_notes.append(f"RSI индекса {imoex_rsi} перепродан")
                if imoex_confirm is not False:
                    imoex_confirm = False

        if zone_notes:
            tech_note = "IMOEX: " + "; ".join(zone_notes)
            imoex_note = (imoex_note + "  |  " + tech_note) if imoex_note else tech_note

    # v0.9.8: IMOEX MA5 режим — бычий/медвежий среднесрочный тренд индекса
    imoex_regime         = ctx.get("imoex_regime")
    imoex_regime_confirm = None
    if imoex_regime == "bull":
        imoex_regime_confirm = (direction == "LONG")
    elif imoex_regime == "bear":
        imoex_regime_confirm = (direction == "SHORT")

    # v0.9.8: Bollinger Band squeeze — сигнал выше среднего после периода низкой волатильности
    bb_squeeze = levels.get("bb_squeeze", False)

    # ── VWAP фильтр (v0.9) ────────────────────────────────────────────────────
    vwap         = intraday.get("vwap") if intraday else None
    vwap_note    = None
    vwap_confirm = None   # None=нет данных, True=подтверждает, False=против

    if vwap and price:
        vwap_diff_pct = round((price - vwap) / vwap * 100, 2)
        # v0.9.10: КРИТИЧНО — < и > в тексте Telegram HTML ОБЯЗАНЫ быть &lt;/&gt;.
        # Голый < перед пробелом → Telegram видит пустой тег <> → 400 Bad Request.
        if direction == "LONG":
            if price > vwap:
                vwap_confirm = True
                vwap_note    = f"цена {price} &gt; VWAP {vwap} (+{abs(vwap_diff_pct)}%) — LONG подтверждён"
            else:
                vwap_confirm = False
                vwap_note    = f"цена {price} &lt; VWAP {vwap} ({vwap_diff_pct}%) — LONG ниже VWAP"
        else:  # SHORT
            if price < vwap:
                vwap_confirm = True
                vwap_note    = f"цена {price} &lt; VWAP {vwap} ({vwap_diff_pct}%) — SHORT подтверждён"
            else:
                vwap_confirm = False
                vwap_note    = f"цена {price} &gt; VWAP {vwap} (+{abs(vwap_diff_pct)}%) — SHORT выше VWAP"

    # ── Стакан заявок (v0.9) ──────────────────────────────────────────────────
    orderbook         = None
    orderbook_note    = None
    orderbook_confirm = None   # None=нет данных, True=подтверждает, False=против

    if _tinvest_available():
        ob = _tinvest.get_orderbook(ticker)   # type: ignore[union-attr]
        if ob:
            orderbook     = ob
            imbalance     = ob["imbalance"]   # ∈ [-1, 1]
            IMBALANCE_THR = 0.2               # порог ≥20% перевеса
            if direction == "LONG":
                if imbalance >= IMBALANCE_THR:
                    orderbook_confirm = True
                    orderbook_note    = f"стакан: бид {ob['bid_volume']}л &gt; аск {ob['ask_volume']}л (∆{imbalance:+.2f}) — покупатели давят"
                elif imbalance <= -IMBALANCE_THR:
                    orderbook_confirm = False
                    orderbook_note    = f"стакан: аск {ob['ask_volume']}л &gt; бид {ob['bid_volume']}л (∆{imbalance:+.2f}) — продавцы давят, LONG рискованен"
            else:  # SHORT
                if imbalance <= -IMBALANCE_THR:
                    orderbook_confirm = True
                    orderbook_note    = f"стакан: аск {ob['ask_volume']}л &gt; бид {ob['bid_volume']}л (∆{imbalance:+.2f}) — продавцы давят"
                elif imbalance >= IMBALANCE_THR:
                    orderbook_confirm = False
                    orderbook_note    = f"стакан: бид {ob['bid_volume']}л &gt; аск {ob['ask_volume']}л (∆{imbalance:+.2f}) — покупатели давят, SHORT рискованен"

    # ── Уровни Фибоначчи (в диапазоне 20-дн. support–resistance)
    fib_range  = resistance - support
    fib_levels = {
        "23.6%": round(support + 0.236 * fib_range, 2),
        "38.2%": round(support + 0.382 * fib_range, 2),
        "50.0%": round(support + 0.500 * fib_range, 2),
        "61.8%": round(support + 0.618 * fib_range, 2),
    }
    nearest_fib = min(fib_levels.items(), key=lambda x: abs(x[1] - price))

    # ── Стоп / Тейк (v0.9.5: H1 ATR как основа, fallback на Daily ATR) ────────
    # Принцип: используем ATR того таймфрейма, на котором входим (H1 confirm).
    # H1 ATR ≈ 0.5–1.0% от цены → стоп 2×H1_ATR ≈ 1–1.5%, тейк2 2.5×H1_ATR ≈ 1.5–2.5%.
    # Если H1 ATR недоступен — fallback: 0.8× дневной ATR (тоже консервативно).
    h1_atr_val     = h1_levels.get("h1_atr") if h1_levels else None
    sizing_atr     = h1_atr_val if h1_atr_val else (atr * 0.8)
    sizing_source  = "H1" if h1_atr_val else "D×0.8"

    raw_stop_dist  = H1_STOP_MULT  * sizing_atr
    take1_dist     = H1_TAKE1_MULT * sizing_atr
    take2_dist     = H1_TAKE2_MULT * sizing_atr

    # Защита: стоп не более MAX_STOP_PCT% (2.5%) от цены
    max_stop_dist  = price * MAX_STOP_PCT / 100.0
    stop_dist      = min(raw_stop_dist, max_stop_dist)

    if direction == "LONG":
        atr_stop     = round(price - stop_dist,  2)
        take1        = round(price + take1_dist, 2)
        take2        = round(price + take2_dist, 2)
        trend_target = resistance
    else:
        atr_stop     = round(price + stop_dist,  2)
        take1        = round(price - take1_dist, 2)
        take2        = round(price - take2_dist, 2)
        trend_target = support

    # ── H1 структурный стоп (v0.9.5: используем как тонкая подстройка) ───────
    # H1-уровень ближе к цене → предпочитаем структурный стоп (точнее).
    # H1-уровень дальше      → оставляем ATR-стоп (защита депозита).
    h1_stop = None
    h1_stop_note = None
    h1_support_lvl    = h1_levels.get("h1_support")    if h1_levels else None
    h1_resistance_lvl = h1_levels.get("h1_resistance") if h1_levels else None
    h1_buf = round(0.2 * sizing_atr, 2)   # буфер 0.2×H1_ATR "за" уровень

    if h1_levels:
        if direction == "LONG" and h1_support_lvl:
            h1_stop = round(h1_support_lvl - h1_buf, 2)
            h1_stop_note = f"H1 поддержка {h1_support_lvl} → стоп {h1_stop}"
        elif direction == "SHORT" and h1_resistance_lvl:
            h1_stop = round(h1_resistance_lvl + h1_buf, 2)
            h1_stop_note = f"H1 сопротивление {h1_resistance_lvl} → стоп {h1_stop}"

    if h1_stop:
        # v0.9.9: H1 структурный стоп обязан быть на правильной стороне от цены входа!
        # LONG: стоп НИЖЕ цены (h1_stop < price), SHORT: стоп ВЫШЕ цены (h1_stop > price).
        # Если H1 поддержка/сопротивление находится за точкой входа — это невалидный уровень.
        h1_stop_valid = (
            (direction == "LONG"  and h1_stop < price) or
            (direction == "SHORT" and h1_stop > price)
        )
        if not h1_stop_valid:
            logger.debug(
                "stop_guard: H1 структурный стоп %s на неправильной стороне от цены %s (%s) — отклонён, используем ATR-стоп",
                h1_stop, price, direction,
            )
            stop = atr_stop
            h1_stop_note = (h1_stop_note or "") + f" (ATR-стоп {atr_stop} — H1 уровень {h1_stop} на неверной стороне)"
        else:
            h1_stop_dist = abs(price - h1_stop)
            if h1_stop_dist <= stop_dist * 1.4:   # H1 стоп не хуже 140% от ATR-стопа
                stop      = h1_stop
                stop_dist = h1_stop_dist
            else:
                stop = atr_stop
                h1_stop_note = (h1_stop_note or "") + f" (предпочтён ATR-стоп {atr_stop} — H1 уровень слишком далеко)"
    else:
        stop = atr_stop

    # v0.9.13: минимальная дистанция стопа = MIN_STOP_ATR_MULT × H1_ATR.
    # Защита от случая когда H1 поддержка вплотную к цене входа →
    # структурный стоп 0.06%, R/R=22 → шум ГАРАНТИРОВАННО выбивает стоп.
    min_stop_dist = MIN_STOP_ATR_MULT * sizing_atr
    actual_stop_dist = abs(price - stop)
    if actual_stop_dist < min_stop_dist:
        logger.warning(
            "stop_guard: стоп %s слишком узкий (dist=%.2f < min=%.2f, ATR=%.2f) → "
            "заменяем на ATR-стоп %s",
            stop, actual_stop_dist, min_stop_dist, sizing_atr, atr_stop,
        )
        stop      = atr_stop
        stop_dist = abs(price - atr_stop)
        h1_stop_note = (h1_stop_note or "") + (
            f" (стоп расширен: dist={actual_stop_dist:.2f} < min={min_stop_dist:.2f} → ATR-стоп {atr_stop})"
        )

    # v0.9.9: финальная проверка — стоп обязан быть на правильной стороне от цены входа.
    # Если нет — сигнал невалиден (проблема с данными или ценой), возвращаем None.
    if direction == "LONG"  and stop >= price:
        logger.warning("stop_guard: LONG стоп %s ≥ цена %s — сигнал отклонён", stop, price)
        return None
    if direction == "SHORT" and stop <= price:
        logger.warning("stop_guard: SHORT стоп %s ≤ цена %s — сигнал отклонён", stop, price)
        return None

    # v0.9.14: смещаем стоп от круглых уровней (физики ставят стопы на 650.00, 38.00 и т.д.)
    stop = _avoid_round_number_stop(stop, price, direction)

    # v0.9.14: пересчитываем stop_dist после возможного смещения
    stop_dist = abs(price - stop)

    # v0.9.22: учёт маржи для SHORT-позиций — реальный тариф T-Invest (₽/день по тарифной сетке)
    margin_daily        = None
    margin_break_even_days = None
    if direction == "SHORT":
        _lot_sz = LOT_SIZES.get(ticker, 1)   # лотность тикера (нужна для оценки позиции)
        # Оцениваем размер позиции: risk 1% от 500k сандбокс / stop% = типичная позиция
        _est_position_rub  = price * _lot_sz * max(1, int(
            (RISK_PCT / 100 * 500_000) / (abs(price - stop) * _lot_sz)
        )) if abs(price - stop) > 0 else 500_000
        _daily_total_rub   = tinvest_margin_daily_rub(_est_position_rub)
        _shares_in_pos     = max(1, _est_position_rub / price)
        # margin_daily — стоимость на 1 акцию (для сравнения с profit_per_share)
        margin_daily       = round(_daily_total_rub / _shares_in_pos, 4) if _daily_total_rub > 0 else round(price * MARGIN_RATE_ANNUAL / 365, 4)
        profit_per_share   = price - take2   # потенциальная прибыль на 1 акцию
        if margin_daily > 0 and profit_per_share > 0:
            margin_break_even_days = round(profit_per_share / margin_daily, 1)
            # Блокируем шорт если маржа за SHORT_MARGIN_MAX_DAYS >80% потенциальной прибыли
            margin_cost_max = margin_daily * SHORT_MARGIN_MAX_DAYS
            if margin_cost_max > profit_per_share * 0.8:
                logger.warning(
                    "short_margin_guard: %s маржа ≈%.2f₽/акц/день (позиция ~%.0f₽) × %d дн = %.2f "
                    "> 80%% прибыли %.2f — шорт заблокирован",
                    ticker, margin_daily, _est_position_rub,  # noqa: F821
                    SHORT_MARGIN_MAX_DAYS, margin_cost_max, profit_per_share,
                )
                return None

    rr        = round(take2_dist / stop_dist, 2) if stop_dist > 0 else 0
    stop_pct  = round(stop_dist  / price * 100, 2)
    take1_pct = round(take1_dist / price * 100, 2)
    take2_pct = round(take2_dist / price * 100, 2)

    # ── Калькулятор позиции (v0.9.2 — идея #4) ───────────────────────────────
    lot_size  = LOT_SIZES.get(ticker, 1)
    pos_calc  = calc_position_size(price, stop, lot_size=lot_size)

    return {
        "type":               signal_kind,
        "ticker":             ticker,
        "direction":          direction,
        "entry":              price,
        "stop":               stop,
        "stop_pct":           stop_pct,
        "take1":              take1,
        "take1_pct":          take1_pct,
        "take2":              take2,
        "take2_pct":          take2_pct,
        "trend_target":       round(trend_target, 2),
        "breakeven_stop":     price,   # стоп в БУ после Тейк1
        "rr":                 rr,
        "volume_ratio":       anomaly["ratio"],
        "rsi":                rsi,
        "rsi_confirm":        rsi_confirm,
        # v0.9.4 — тип стратегии
        "signal_type":        signal_type,   # "momentum" | "mean_reversion"
        "ma20":               ma20,
        "ma_trend":           ma_trend,
        # v0.9.2 — MA50 тренд-фильтр
        "ma50":               ma50,
        "ma50_trend":         ma50_trend,
        "ma50_note":          ma50_note,
        "ma50_against":       ma50_against,
        # v0.9.5 — ADX и sizing source
        "adx":                levels.get("adx"),  # сила тренда: <20 флэт, >25 тренд
        "sizing_source":      sizing_source,       # "H1" или "D×0.8"
        "h1_atr":             h1_atr_val,
        # v0.9.2 — H1 уровни
        "h1_support":         h1_support_lvl,
        "h1_resistance":      h1_resistance_lvl,
        "h1_stop_note":       h1_stop_note,
        # v0.9.3 — H1 подтверждение входа
        "h1_confirm":         h1_confirm,
        # v0.9.2 — Калькулятор позиции
        "position_calc":      pos_calc,
        "fib_levels":         fib_levels,
        "nearest_fib":        nearest_fib,
        "usdrub_confirm":     usdrub_confirm,
        "usdrub_note":        usdrub_note,
        # v0.9.29: Brent + Gold
        "brent_confirm":      brent_confirm,
        "brent_note":         brent_note,
        "gold_confirm":       gold_confirm,
        "gold_note":          gold_note,
        "imoex_note":            imoex_note,
        "imoex_confirm":         imoex_confirm,
        # v0.9.8 — IMOEX MA5 режим + BB squeeze
        "imoex_regime":          imoex_regime,
        "imoex_regime_confirm":  imoex_regime_confirm,
        "bb_squeeze":            bb_squeeze,
        # v0.9 — VWAP
        "vwap":               vwap,
        "vwap_note":          vwap_note,
        "vwap_confirm":       vwap_confirm,
        # v0.9 — Стакан
        "orderbook":          orderbook,
        "orderbook_note":     orderbook_note,
        "orderbook_confirm":  orderbook_confirm,
        # v0.9.14 — маржа SHORT и недельный тренд (заполняется в synthesize_signals)
        "margin_daily":            margin_daily,
        "margin_break_even_days":  margin_break_even_days,
        "weekly_trend":            None,   # заполняется в synthesize_signals
        "weekly_change":           None,
        "weekly_aligned":          None,
        # v0.9.29 — OBV накопление/распределение + MA crossover
        "obv_trend":     levels.get("obv_trend"),    # "up" | "down" | "flat"
        "obv_bull_div":  levels.get("obv_bull_div"),  # True = OBV↑ цена↓ → скрытое накопление
        "obv_bear_div":  levels.get("obv_bear_div"),  # True = OBV↓ цена↑ → скрытое распределение
        "ma_crossover":  levels.get("ma_crossover"),  # "golden_cross" | "death_cross" | None
        "decision_reasons": decision_reasons,
        "data_quality_flags": data_quality_flags,
        "news_mode": "none",
    }


# ══════════════════════════════════════════════════════════════════════════════
#  СТАТУС НОВОСТИ: отработана / отрабатывается / свежая / отвергнута
# ══════════════════════════════════════════════════════════════════════════════

NEWS_STATUS_FRESH    = "🆕 Свежая (< 1ч)"
NEWS_STATUS_ACTIVE   = "⏳ Отрабатывается"
NEWS_STATUS_PRICED   = "✅ Отработана"
NEWS_STATUS_REJECTED = "⚠️  Отвергнута рынком"
NEWS_STATUS_PENDING  = "🎯 Ещё не отработана"
NEWS_STATUS_UNKNOWN  = "❓ Нет данных"


def parse_news_age(published: str) -> float | None:
    """
    Возраст новости в часах.
    Использует timezone-aware сравнение — больше никаких ошибок с UTC vs MSK.
    """
    if not published:
        return None
    try:
        dt = parsedate_to_datetime(published)
        if dt.tzinfo is not None:
            now_utc = datetime.now(timezone.utc)
            age = (now_utc - dt).total_seconds() / 3600
        else:
            # Без TZ — предполагаем московское (UTC+3)
            dt_msk  = dt.replace(tzinfo=timezone(timedelta(hours=3)))
            now_utc = datetime.now(timezone.utc)
            age = (now_utc - dt_msk).total_seconds() / 3600
        return round(max(age, 0), 2)
    except Exception:
        pass
    for fmt in ["%Y-%m-%dT%H:%M:%S", "%d %b %Y %H:%M:%S"]:
        try:
            dt  = datetime.strptime(published[:19], fmt)
            age = (now_msk() - dt).total_seconds() / 3600
            return round(max(age, 0), 2)
        except Exception:
            continue
    return None


def assess_news_status(item: "NewsItem", intraday_data: dict) -> str:
    """
    Определяем, отработала ли новость в цене.
    Сравниваем направление новости с фактическим дневным движением тикера.
    """
    if not item.tickers or item.direction == "NEUTRAL":
        return NEWS_STATUS_UNKNOWN

    age_hours = parse_news_age(item.published)
    threshold = NEWS_PRICE_THRESHOLD_PCT

    movements = []
    for ticker in item.tickers[:3]:
        data = intraday_data.get(ticker)
        if not data:
            continue
        chg = data.get("change_pct", 0)
        if item.direction == "LONG":
            movements.append("match"   if chg >= threshold else
                             "reject"  if chg <= -threshold else "neutral")
        else:
            movements.append("match"   if chg <= -threshold else
                             "reject"  if chg >= threshold  else "neutral")

    matches = movements.count("match")
    rejects = movements.count("reject")

    if rejects > matches and rejects > 0:
        return NEWS_STATUS_REJECTED
    if not movements:
        return NEWS_STATUS_FRESH if (age_hours is None or age_hours < 1) else NEWS_STATUS_UNKNOWN
    if matches > 0:
        return NEWS_STATUS_PRICED if (age_hours is not None and age_hours >= 2) else NEWS_STATUS_ACTIVE
    return NEWS_STATUS_FRESH if (age_hours is None or age_hours < 1) else NEWS_STATUS_PENDING


def is_news_event_tradable(item: "NewsItem") -> tuple[bool, str]:
    """Sandbox-only gate for standalone news-event entries."""
    if not NEWS_EVENT_SANDBOX_ORDER:
        return False, "news_event_disabled"
    if item.direction not in ("LONG", "SHORT") or not item.tickers:
        return False, "news_event_no_direction"
    min_strength = (
        NEWS_EVENT_MIN_STRENGTH_AI
        if item.analyzed_by == "ai"
        else NEWS_EVENT_MIN_STRENGTH_KEYWORDS
    )
    if item.strength < min_strength:
        return False, "news_event_low_strength"
    if item.event_type not in NEWS_EVENT_TYPES:
        return False, "news_event_type_not_allowed"
    if item.status in (NEWS_STATUS_REJECTED, NEWS_STATUS_PRICED):
        return False, "news_event_already_resolved"
    return True, "news_event_candidate"


def build_news_event_signals(
    news_signals: list["NewsItem"],
    ctx: dict,
    intraday_data: dict,
    existing_market_tickers: set[str] | None = None,
) -> list[dict]:
    """
    Builds standalone sandbox-tradable signals for strong event news. This is
    intentionally separate from normal news scoring and only runs in sandbox.
    """
    if not NEWS_EVENT_SANDBOX_ORDER:
        return []
    existing_market_tickers = existing_market_tickers or set()
    built: list[dict] = []
    seen: set[tuple[str, str]] = set()

    for n in news_signals:
        tradable, reason = is_news_event_tradable(n)
        if not tradable:
            append_decision_log({
                "action": "skipped",
                "reason": reason,
                "ticker": ",".join(n.tickers[:4]),
                "direction": n.direction,
                "news_mode": n.analyzed_by or "keywords",
                "strength": n.strength,
                "event_type": n.event_type,
            })
            continue
        for ticker in n.tickers[:3]:
            if ticker in existing_market_tickers:
                continue
            key = (ticker, n.direction)
            if key in seen:
                continue
            seen.add(key)
            candles = get_candles(ticker, days=55)
            if not candles:
                append_opportunity_log({
                    "ticker": ticker,
                    "direction": n.direction,
                    "action": "rejected",
                    "reason": "news_event_no_candles",
                    "news_mode": n.analyzed_by or "keywords",
                    "event_type": n.event_type,
                    "strength": n.strength,
                })
                continue
            levels = calc_levels(candles)
            intraday = intraday_data.get(ticker) or get_intraday_price(ticker)
            if intraday:
                intraday_data[ticker] = intraday
                _current_intraday[ticker] = intraday
            pseudo_anomaly = {
                "anomaly": True,
                "ratio": max(1.5, float(n.strength or 0)),
                "last_volume": None,
                "avg_volume": None,
                "absolute_ok": True,
                "reason": "news_event",
            }
            h1_confirm = {
                "type": "news_event",
                "note": f"{n.event_type} {n.direction} strength={n.strength}: {n.reason or n.title[:90]}",
            }
            signal = build_market_signal(
                ticker, levels, pseudo_anomaly, ctx,
                intraday=intraday or None,
                h1_confirm=h1_confirm,
                direction_override=n.direction,
                signal_type_override="momentum",
                signal_kind="NEWS_EVENT",
            )
            if not signal:
                append_opportunity_log({
                    "ticker": ticker,
                    "direction": n.direction,
                    "action": "rejected",
                    "reason": "news_event_signal_invalid",
                    "news_mode": n.analyzed_by or "keywords",
                    "event_type": n.event_type,
                    "strength": n.strength,
                })
                continue
            signal["strategy"] = "news_event"
            signal["news_mode"] = n.analyzed_by or "keywords"
            signal["news_event_type"] = n.event_type
            signal["news_event_strength"] = n.strength
            signal["news_event_title"] = n.title
            signal["news_event_url"] = n.url
            signal["decision_reasons"] = sorted(set(signal.get("decision_reasons", []) + ["news_event_signal"]))
            append_opportunity_log({
                "ticker": ticker,
                "direction": n.direction,
                "action": "watch_only",
                "reason": "news_event_candidate",
                "news_mode": n.analyzed_by or "keywords",
                "event_type": n.event_type,
                "strength": n.strength,
                "price": signal.get("entry"),
                "volume_ratio": signal.get("volume_ratio"),
                "decision_reasons": signal.get("decision_reasons", []),
            })
            built.append(signal)
    return built


