def build_ai_system_prompt(ctx: dict) -> str:
    """Динамический промпт с актуальным контекстом рынка."""
    usdrub_str = (
        f"USDRUB={ctx['usdrub']} ({ctx['usdrub_change_pct']:+.1f}% сегодня)"
        if ctx.get("usdrub") else "USDRUB: нет данных"
    )
    imoex_str = (
        f"IMOEX={ctx['imoex']} ({ctx['imoex_change_pct']:+.1f}% сегодня)"
        if ctx.get("imoex") else "IMOEX: нет данных"
    )
    # Технические уровни IMOEX для AI-контекста
    imoex_lvls = ctx.get("imoex_levels")
    if imoex_lvls:
        zone_map = {
            "near_support":    "у поддержки",
            "near_resistance": "у сопротивления",
            "middle":          "в середине диапазона",
        }
        zone_desc = zone_map.get(imoex_lvls.get("zone", "middle"), "")
        imoex_str += (
            f" | S={imoex_lvls.get('support')} R={imoex_lvls.get('resistance')}"
            f" RSI={imoex_lvls.get('rsi')} — {zone_desc}"
        )

    tickers_list = ", ".join(TICKERS)
    # v0.9.29: добавить Brent и Gold в контекст промпта
    brent_ctx = ""
    if ctx.get("brent") is not None:
        brent_sign = "+" if (ctx.get("brent_change_pct") or 0) >= 0 else ""
        brent_ctx = (
            f"- Нефть Brent: {ctx['brent']}$ ({brent_sign}{ctx.get('brent_change_pct', 0):.1f}% за день)"
            f" {'— рост нефти поддерживает ЛОНГ нефтяников' if (ctx.get('brent_change_pct') or 0) >= 1.5 else '— снижение нефти давит на нефтяников' if (ctx.get('brent_change_pct') or 0) <= -1.5 else '— нейтрально'}\n"
        )
    gold_ctx = ""
    if ctx.get("gold_rub_gram") is not None:
        gold_sign = "+" if (ctx.get("gold_change_pct") or 0) >= 0 else ""
        gold_ctx = (
            f"- Золото (GLDRUB): {ctx['gold_rub_gram']:.0f}₽/г ({gold_sign}{ctx.get('gold_change_pct', 0):.1f}% за день)"
            f" {'— рост золота поддерживает ЛОНГ PLZL' if (ctx.get('gold_change_pct') or 0) >= 1.0 else '— снижение золота давит на PLZL' if (ctx.get('gold_change_pct') or 0) <= -1.0 else '— нейтрально'}\n"
        )
    return f"""Ты — аналитик российского фондового рынка MOEX.

АКТУАЛЬНЫЙ КОНТЕКСТ (учитывай при анализе каждой новости):
- Ключевая ставка ЦБ РФ: {ctx['cbr_rate']}% {'(снижается с 21%, позитивный тренд; SBER VTBR T SMLT PIKK LSRG OZON X5 MGNT — основные бенефициары снижения; закредитованные компании выходят из-под давления)' if ctx['cbr_rate'] < 17 else '(очень высокая → медвежий фон; застройщики, ритейл, закредитованные компании под давлением)'}
- {usdrub_str} (слабый рубль = позитив для экспортёров: нефтяники, металлурги, золото, удобрения)
- {imoex_str} (тренд и уровни индекса определяют общий фон; у сопротивления — осторожно с LONG)
{brent_ctx}{gold_ctx}- Санкции США/ЕС действуют, экспорт ограничен; геополитика = главный риск

ЭКСПОРТЁРЫ (выигрывают от слабого рубля): GAZP LKOH ROSN NVTK TATN SNGS GMKN PLZL ALRS CHMF PHOR NLMK MAGN
СТАВКО-ЧУВСТВИТЕЛЬНЫЕ (бенефициары снижения ставки): SBER VTBR T SMLT PIKK LSRG OZON X5 MGNT AFKS
ТЕХНОЛОГИИ/IT: YDEX POSI HEAD
ВНУТРЕННИЙ РЫНОК: SBER VTBR T MGNT MTSS YDEX AFKS OZON X5 HEAD POSI LSRG

Тебе дают список новостей. Для каждой определи:
1. Затронутые тикеры (только из: {tickers_list})
2. Направление: LONG / SHORT / NEUTRAL
3. Сила: 1 (слабый) / 2 (средний) / 3 (сильный)
4. Тип: OIL / CB_RATE / SANCTIONS / MACRO / EARNINGS / GEOPOLITICS / CURRENCY / CORP / NEWS
   CORP = оферта, M&A, делистинг, buyback, слияние, поглощение
5. Причина (1 предложение на русском, с учётом текущей ставки, курса рубля, нефти, золота)

Отвечай ТОЛЬКО валидным JSON без markdown:
[{{"index":0,"tickers":["GAZP"],"direction":"LONG","strength":2,"event_type":"OIL","reason":"..."}}]
Если новость нерелевантна — tickers:[], direction:"NEUTRAL"."""


def analyze_by_ai(items: list[NewsItem], ctx: dict) -> list[NewsItem]:
    global _ai_last_call, _ai_backoff_until

    if not ANTHROPIC_API_KEY:
        logger.debug("ANTHROPIC_API_KEY не задан — ключевые слова")
        return [analyze_by_keywords(item) for item in items]

    now = datetime.now(timezone.utc)

    # v0.9.10: 403-бэкофф — при auth-ошибке молчим несколько часов, не спамим в лог
    if _ai_backoff_until is not None and now < _ai_backoff_until:
        remain_h = (_ai_backoff_until - now).total_seconds() / 3600
        logger.debug("AI backoff: заблокирован ещё %.1f ч (403) — ключевые слова", remain_h)
        return [analyze_by_keywords(item) for item in items]

    # ── Кулдаун: не вызываем AI чаще чем раз в AI_COOLDOWN_MIN минут ─────────
    if AI_COOLDOWN_MIN > 0 and _ai_last_call is not None:
        elapsed_min = (now - _ai_last_call).total_seconds() / 60
        if elapsed_min < AI_COOLDOWN_MIN:
            wait_min = AI_COOLDOWN_MIN - elapsed_min
            logger.debug("AI cooldown: %.1f мин до следующего вызова", wait_min)
            return [analyze_by_keywords(item) for item in items]
    # ─────────────────────────────────────────────────────────────────────────

    headlines = "\n".join([f"{i}. {item.title}" for i, item in enumerate(items)])
    print(f"  🤖 AI ({AI_MODEL}) анализирует {len(items)} новостей...", end=" ", flush=True)
    try:
        resp = requests.post(
            "https://api.anthropic.com/v1/messages",
            headers={
                "x-api-key":         ANTHROPIC_API_KEY,
                "anthropic-version": "2023-06-01",
                "content-type":      "application/json",
            },
            json={
                "model":      AI_MODEL,
                "max_tokens": 1500,
                "system":     build_ai_system_prompt(ctx),
                "messages":   [{"role": "user", "content": f"Проанализируй:\n\n{headlines}"}],
            },
            timeout=30,
        )
        if not resp.ok:
            logger.error("AI API HTTP %d: %s", resp.status_code, resp.text[:300])
            if resp.status_code == 403:
                # v0.9.10: 403 = неверный ключ или нет доступа — бэкофф 4 часа
                _ai_backoff_until = now + timedelta(hours=4)
                logger.warning(
                    "AI API 403 Forbidden — ключ недействителен или нет доступа. "
                    "AI заблокирован на 4 ч, используем ключевые слова. "
                    "Проверь ANTHROPIC_API_KEY в .env"
                )
                print("  ⚠️  AI API 403 — ключ/доступ. Backoff 4ч, используем ключевые слова.")
            resp.raise_for_status()
        raw_text = re.sub(r"```json|```", "", resp.json()["content"][0]["text"]).strip()
        results  = json.loads(raw_text)

        for r in results:
            idx = r.get("index", -1)
            if 0 <= idx < len(items):
                items[idx].tickers     = r.get("tickers", [])
                items[idx].direction   = r.get("direction", "NEUTRAL")
                items[idx].strength    = r.get("strength", 0)
                items[idx].event_type  = r.get("event_type", "NEWS")
                items[idx].reason      = r.get("reason", "")
                items[idx].analyzed_by = "ai"
        _ai_last_call = datetime.now(timezone.utc)   # обновляем кулдаун только при успехе
        print("✅ готово")

    except json.JSONDecodeError as e:
        print(f"❌ JSON: {e} — ключевые слова")
        logger.error("AI JSON parse error: %s | raw_text начало: %.200s", e, locals().get("raw_text", ""))
        items = [analyze_by_keywords(item) for item in items]
    except Exception as e:
        # v0.9.10: при ошибке обновляем _ai_last_call чтобы не долбить API каждые 5 мин
        _ai_last_call = now
        logger.error("AI API error: %s", e)
        items = [analyze_by_keywords(item) for item in items]

    for item in items:
        if not item.analyzed_by:
            analyze_by_keywords(item)

    return items


