#  МОДУЛЬ 4: СИНТЕЗ СИГНАЛОВ
# ══════════════════════════════════════════════════════════════════════════════

def _score_to_confidence(score: int) -> str:
    """Конвертация числового score в лейбл уверенности (v0.9.5)."""
    if score >= 12:
        return "🔥🔥 ОТЛИЧНАЯ"
    elif score >= 9:
        return "🔥 ВЫСОКАЯ"
    elif score >= 6:
        return "🟡 СРЕДНЯЯ"
    else:
        return "🔴 СЛАБАЯ"


def synthesize_signals(market_signals: list[dict], news_signals: list[NewsItem]) -> list[dict]:
    """
    v0.9.5: Score-based уверенность (0–17 очков) вместо бинарных переключателей.

    Скоринг:
      Объём    (0–4):  ×>5 = 4, ×3–5 = 3, ×2–3 = 2, ×1.5–2 = 1
      H1 conf  (0–3):  breakout = 3, momentum = 2, нет = 0
      VWAP     (0–2):  подтверждает = 2, нет данных = 0, против = -1
      Новости  (0–3):  сильное согласие = 3, согласие = 2, нет = 0, SELL THE NEWS = 2, против = -1
      ADX      (0–2):  >25 momentum / <20 mean-rev = 2, 20–25 = 1, не по стратегии = 0
      MA50     (0–1):  по тренду = 1, против = 0
      RSI      (0–1):  подтверждает = 1, против = 0
      Стакан   (0–1):  подтверждает = 1, против = 0
      Время    (0–1):  прайм-тайм = 1, иначе = 0
      IMOEX    (0–1):  подтверждает = 1, против = 0
      ────────────────────────────────────────────────────
      Максимум ≈ 17, практически: 12–14 для идеального сигнала
      ≥12: 🔥🔥 ОТЛИЧНАЯ | ≥9: 🔥 ВЫСОКАЯ | ≥6: 🟡 СРЕДНЯЯ | <6: 🔴 СЛАБАЯ
    """
    synthesized = []
    session_bonus, session_label = get_session_quality()
    news_memory = load_news_memory()

    for ms in market_signals:
        ticker   = ms["ticker"]
        related  = [n for n in news_signals if ticker in n.tickers and n.direction != "NEUTRAL"]
        agreeing = [n for n in related if n.direction == ms["direction"]]
        opposing = [n for n in related if n.direction != ms["direction"]]
        score    = 0
        score_breakdown = []
        patterns = []
        decision_reasons = list(ms.get("decision_reasons", []))
        data_quality_flags = list(ms.get("data_quality_flags", []))
        news_mode = "none"
        if related:
            news_mode = "ai" if any(n.analyzed_by == "ai" for n in related) else "keywords"

        # ── 1. Объём (0–4) ────────────────────────────────────────────────────
        vol_ratio = ms.get("volume_ratio", 0)
        if   vol_ratio >= 5.0: vol_pts = 4
        elif vol_ratio >= 3.0: vol_pts = 3
        elif vol_ratio >= 2.0: vol_pts = 2
        elif vol_ratio >= 1.5: vol_pts = 1
        else:                  vol_pts = 0
        score += vol_pts
        score_breakdown.append(f"📊Объём×{vol_ratio:.1f}=+{vol_pts}")

        # ── 2. H1 подтверждение (0–3) ─────────────────────────────────────────
        h1c = ms.get("h1_confirm")
        if h1c:
            h1_type = h1c.get("type")
            if h1_type == "breakout":
                h1_pts = 3
                patterns.append("⚡ пробой H1")
            elif h1_type == "momentum":
                h1_pts = 2
                patterns.append("💪 импульс H1")
            elif h1_type == "index_rebound":
                h1_pts = 2
                patterns.append("📈 отбой IMOEX")
            elif h1_type == "news_event":
                h1_pts = 1
                patterns.append("📰 новостной event")
            else:  # "volume" — новый тип (v0.9.7)
                h1_pts = 2
                patterns.append("📊 объём H1")
        else:
            h1_pts = 0
        score += h1_pts
        score_breakdown.append(f"H1=+{h1_pts}")

        # ── 3. VWAP (−1..+2) ──────────────────────────────────────────────────
        vwap_conf = ms.get("vwap_confirm")
        if   vwap_conf is True:  vwap_pts = 2;  patterns.append("📊 VWAP ✅")
        elif vwap_conf is False: vwap_pts = -1; patterns.append("📊 VWAP ⚠️")
        else:                    vwap_pts = 0
        score += vwap_pts
        if vwap_pts != 0:
            score_breakdown.append(f"VWAP={'+' if vwap_pts>0 else ''}{vwap_pts}")

        # ── 4. Новости (−1..+3) ───────────────────────────────────────────────
        if agreeing and not opposing:
            top_strength = max(n.strength for n in agreeing)
            news_pts = 3 if top_strength >= 2 else 2
            patterns.append(f"📰 Новость ✅ ×{len(agreeing)}")
        elif agreeing and opposing:
            news_pts = 1
            patterns.append("📰 Новости конфликт")
        elif opposing and not agreeing and ms["direction"] == "SHORT":
            news_pts = 2
            patterns.append("⚡ SELL THE NEWS")
        elif opposing and not agreeing:
            news_pts = -1
            patterns.append("📰 Против тренда")
        else:
            news_pts = 0
        score += news_pts
        if news_pts != 0:
            score_breakdown.append(f"Новости={'+' if news_pts>0 else ''}{news_pts}")

        # ── 5. ADX — сила тренда (0–2) ────────────────────────────────────────
        adx = ms.get("adx")
        sig_type = ms.get("signal_type", "mean_reversion")
        if adx is not None:
            if sig_type == "momentum":
                # Для momentum: ADX > 25 = хорошо (сильный тренд)
                if   adx >= 30: adx_pts = 2
                elif adx >= 25: adx_pts = 2
                elif adx >= 20: adx_pts = 1
                else:           adx_pts = 0  # флэт — momentum рискован
            else:
                # Для mean-reversion: ADX < 20 = хорошо (флэт/диапазон)
                if   adx < 20:  adx_pts = 2
                elif adx < 25:  adx_pts = 1
                else:           adx_pts = 0  # сильный тренд — mean-rev рискован
            adx_label = f"{'↑тренд' if adx >= 25 else '↔флэт'}"
            score_breakdown.append(f"ADX={adx:.0f}{adx_label}=+{adx_pts}")
        else:
            adx_pts = 0
        score += adx_pts

        # ── 6. MA50 (0–1) ──────────────────────────────────────────────────────
        ma50_pts = 0 if ms.get("ma50_against") else 1
        score += ma50_pts
        if ms.get("ma50_against"):
            patterns.append("📉 против MA50")
        score_breakdown.append(f"MA50=+{ma50_pts}")

        # ── 7. RSI (0–1) ───────────────────────────────────────────────────────
        rsi_pts = 1 if ms.get("rsi_confirm", True) else 0
        score += rsi_pts
        if not ms.get("rsi_confirm", True):
            patterns.append("⚠️ RSI против")
        score_breakdown.append(f"RSI=+{rsi_pts}")

        # ── 7b. Экстремальный RSI (0–2) v0.9.20 ───────────────────────────────
        # RSI < 25 при LONG = жёсткая перепроданность = mean-reversion edge.
        # RSI > 75 при SHORT = жёсткая перекупленность.
        # Пример: ALRS RSI=19 всю сессию при объёме ×2.5 — сильный сигнал отскока.
        rsi_val    = ms.get("rsi")
        direction  = ms["direction"]
        extreme_pts = 0
        if rsi_val is not None:
            if direction == "LONG" and rsi_val < 25:
                extreme_pts = 2
                patterns.append(f"🔥 RSI экстрем {rsi_val:.0f} перепродан")
                score_breakdown.append(f"RSI_extreme=+{extreme_pts}")
            elif direction == "SHORT" and rsi_val > 75:
                extreme_pts = 2
                patterns.append(f"🔥 RSI экстрем {rsi_val:.0f} перекуплен")
                score_breakdown.append(f"RSI_extreme=+{extreme_pts}")
        score += extreme_pts

        # ── 8. Стакан (0–1) ───────────────────────────────────────────────────
        ob_conf = ms.get("orderbook_confirm")
        if   ob_conf is True:  ob_pts = 1; patterns.append("📋 Стакан ✅")
        elif ob_conf is False: ob_pts = 0; patterns.append("📋 Стакан ⚠️")
        else:                  ob_pts = 0
        score += ob_pts

        # ── 9. Время дня (0–1) ────────────────────────────────────────────────
        score += session_bonus
        if session_bonus > 0:
            score_breakdown.append(f"Время=+{session_bonus}")

        # ── 10. IMOEX (0–1) ───────────────────────────────────────────────────
        if   ms.get("imoex_confirm") is True:  imoex_pts = 1
        elif ms.get("imoex_confirm") is False: imoex_pts = 0; patterns.append("📈 IMOEX против")
        else:                                  imoex_pts = 0
        score += imoex_pts

        # ── USDRUB (информационно, без очков) ─────────────────────────────────
        if ms.get("usdrub_confirm") is False:
            patterns.append("💱 ₽ против")

        # ── 11. BB сжатие/прорыв (0–2) v0.9.8 ────────────────────────────────
        if ms.get("bb_squeeze"):
            bb_pts = 2
            patterns.append("🎯 BB сжатие↑")
            score_breakdown.append(f"BB_squeeze=+{bb_pts}")
        else:
            bb_pts = 0
        score += bb_pts

        # ── 11b. Intraday volume surge (0–1) v0.9.19 ─────────────────────────
        # Если текущий часовой объём >> средний → возможный инсайд или разгон.
        # Бонус даётся когда нет явной новостной причины (подозрительная активность).
        # Данные из _current_intraday (загружены в run_once при обнаружении аномалии).
        surge_pts = 0
        intraday_tick = _current_intraday.get(ticker, {}) if _current_intraday else {}
        hourly_vol   = intraday_tick.get("volume", 0) or 0
        avg_hourly   = intraday_tick.get("avg_hourly_volume", 0) or 0
        no_news_reason = not agreeing and not opposing   # нет новостного объяснения
        if avg_hourly > 0 and hourly_vol > 0 and no_news_reason:
            surge_ratio = hourly_vol / avg_hourly
            if surge_ratio >= 2.5:
                surge_pts = 1
                patterns.append(f"🔍 Внутридн.объём ×{surge_ratio:.1f} без новостей")
                score_breakdown.append(f"VolSurge=+{surge_pts}")
        score += surge_pts

        # ── 12. IMOEX MA5 режим (0–1) v0.9.8 ─────────────────────────────────
        regime_conf = ms.get("imoex_regime_confirm")
        if regime_conf is True:
            regime_pts = 1
            lbl = "🐂 MA5бычий" if ms["direction"] == "LONG" else "🐻 MA5медвежий"
            patterns.append(f"📈 IMOEX {lbl}")
            score_breakdown.append(f"IMOEX_MA5=+{regime_pts}")
        elif regime_conf is False:
            regime_pts = 0
            patterns.append("📈 IMOEX MA5 против ⚠️")
        else:
            regime_pts = 0
        score += regime_pts

        # ── 13. Недельный TF (v0.9.14) ─────────────────────────────────────────
        # Торговать ПО старшему тренду — выше вероятность продолжения.
        # Торговать ПРОТИВ — высокий риск, физики уже на другой стороне.
        weekly_pts     = 0
        weekly_aligned = None
        weekly_note    = ""
        if WEEKLY_TREND_FILTER:
            wt = get_weekly_trend(ticker)
            weekly_trend_dir = wt.get("trend", "flat")
            w_change = wt.get("weekly_change", 0.0)
            ms["weekly_trend"]  = weekly_trend_dir
            ms["weekly_change"] = w_change
            if weekly_trend_dir == "bull":
                if ms["direction"] == "LONG":
                    weekly_pts = WEEKLY_ALIGNED_BONUS
                    weekly_aligned = True
                    weekly_note = f"📅 Нед↑ {w_change:+.1f}% — с трендом ✅"
                    patterns.append(f"📅 Нед↑ с трендом")
                else:  # SHORT против бычьей недели
                    weekly_pts = -WEEKLY_AGAINST_PENALTY
                    weekly_aligned = False
                    weekly_note = f"📅 Нед↑ {w_change:+.1f}% — SHORT против тренда ⚠️"
                    patterns.append(f"📅 Нед↑ SHORT против ⚠️")
            elif weekly_trend_dir == "bear":
                if ms["direction"] == "SHORT":
                    weekly_pts = WEEKLY_ALIGNED_BONUS
                    weekly_aligned = True
                    weekly_note = f"📅 Нед↓ {w_change:+.1f}% — с трендом ✅"
                    patterns.append(f"📅 Нед↓ с трендом")
                else:  # LONG против медвежьей недели
                    weekly_pts = -WEEKLY_AGAINST_PENALTY
                    weekly_aligned = False
                    weekly_note = f"📅 Нед↓ {w_change:+.1f}% — LONG против тренда ⚠️"
                    patterns.append(f"📅 Нед↓ LONG против ⚠️")
                    # v0.9.18: жёсткий блок при сильном медвежьем тренде (>3% ниже MA5)
                    # Статистика недели: все NVTK LONG при BEAR -5...-6% → стоп.
                    # Мягкий штраф -3 не спасает если другие факторы дают +6.
                    if abs(w_change) > 3.0:
                        logger.info("weekly_hard_block: %s LONG заблокирован (Нед↓ %+.1f%% < -3%%)",
                                    ticker, w_change)
                        append_score_log({"ticker": ticker, "direction": direction,
                                          "action": "blocked", "reason": "weekly_hard_block",
                                          "weekly_change": w_change, "score": None})
                        append_decision_log({
                            "action": "blocked",
                            "reason": "weekly_hard_block",
                            "ticker": ticker,
                            "direction": direction,
                            "weekly_change": w_change,
                        })
                        continue
            else:  # flat — нейтрально
                weekly_note = f"📅 Нед{w_change:+.1f}% — боковик"
            ms["weekly_aligned"] = weekly_aligned
            ms["weekly_note"]    = weekly_note
            score += weekly_pts
            if weekly_pts != 0:
                score_breakdown.append(f"Нед_TF={'+' if weekly_pts > 0 else ''}{weekly_pts}")

        # ── 14. News memory trend (v0.9.19) ────────────────────────────────────
        # Накопленный новостной сентимент за несколько дней.
        # Улучшение фона → бонус "buy the rumor"; ухудшение → штраф.
        _nm_trend, _nm_days = get_news_trend(ticker, news_memory)
        nm_pts = 0
        if _nm_trend == "improving" and ms["direction"] == "LONG":
            nm_pts = 2
            patterns.append(f"📰 Сент↑ {_nm_days}д ✅")
            score_breakdown.append(f"NewsMemory=+{nm_pts}")
        elif _nm_trend == "worsening" and ms["direction"] == "LONG":
            nm_pts = -2
            patterns.append(f"📰 Сент↓ {_nm_days}д ⚠️")
            score_breakdown.append(f"NewsMemory={nm_pts}")
        elif _nm_trend == "improving" and ms["direction"] == "SHORT":
            nm_pts = -1
            patterns.append(f"📰 Сент↑ SHORT против ⚠️")
            score_breakdown.append(f"NewsMemory={nm_pts}")
        elif _nm_trend == "worsening" and ms["direction"] == "SHORT":
            nm_pts = 2
            patterns.append(f"📰 Сент↓ SHORT ✅")
            score_breakdown.append(f"NewsMemory=+{nm_pts}")
        score += nm_pts
        ms["news_memory_trend"] = _nm_trend
        ms["news_memory_days"]  = _nm_days

        # ── 15. Event Calendar (v0.9.19) ────────────────────────────────────────
        # Ближайшее плановое событие (ЦБ, отчёт, дивидендная отсечка).
        # Если событие ближайшие 48ч и наш сигнал совпадает с bias → +2.
        _evt = get_upcoming_event(ticker, hours_ahead=48)
        evt_pts = 0
        if _evt:
            evt_bias = _evt.get("bias", "neutral")
            evt_name = _evt.get("event", "Событие")
            days_to  = _evt.get("days_to", "?")
            if ((evt_bias == "long" and ms["direction"] == "LONG") or
                    (evt_bias == "short" and ms["direction"] == "SHORT")):
                evt_pts = 2
                patterns.append(f"📅 {evt_name} ({days_to}д) ✅")
                score_breakdown.append(f"Calendar=+{evt_pts}")
            elif evt_bias != "neutral":
                evt_pts = -1
                patterns.append(f"📅 {evt_name} ({days_to}д) против ⚠️")
                score_breakdown.append(f"Calendar={evt_pts}")
            score += evt_pts
            ms["calendar_event"] = evt_name
            ms["calendar_days"]  = days_to

        # ── 16. Brent/Gold подтверждение (v0.9.29) ─────────────────────────────
        # Нефть двигает 9 тикеров, золото — PLZL. Как USDRUB но для сырьевого фактора.
        brent_pts = 0
        brent_conf = ms.get("brent_confirm")
        if brent_conf is True:
            brent_pts = 2
            brent_lbl = ms.get("brent_note", "Brent ✅")
            patterns.append(f"🛢 {brent_lbl}")
            score_breakdown.append(f"Brent=+{brent_pts}")
        elif brent_conf is False:
            brent_pts = -1
            brent_lbl = ms.get("brent_note", "Brent ⚠️")
            patterns.append(f"🛢 Brent против ⚠️")
            score_breakdown.append(f"Brent={brent_pts}")
        score += brent_pts

        gold_pts = 0
        gold_conf = ms.get("gold_confirm")
        if gold_conf is True:
            gold_pts = 2
            gold_lbl = ms.get("gold_note", "Золото ✅")
            patterns.append(f"🥇 {gold_lbl}")
            score_breakdown.append(f"Gold=+{gold_pts}")
        elif gold_conf is False:
            gold_pts = -1
            patterns.append(f"🥇 Золото против ⚠️")
            score_breakdown.append(f"Gold={gold_pts}")
        score += gold_pts

        # ── 17. Rate-trend bias — снижение ставки ЦБ (v0.9.29) ────────────────
        # Если ставка < 17% (снижение с 21%) → бенефициары: банки, застройщики, ритейл.
        # +1 к LONG только при подтверждённом снижении ставки (< 17%).
        # CBR_KEY_RATE — модульная переменная, всегда актуальна (обновляется fetch_cbr_rate).
        rate_pts = 0
        if CBR_KEY_RATE < 17.0 and ticker in RATE_SENSITIVE_TICKERS and direction == "LONG":
            rate_pts = 1
            patterns.append(f"📉 Ставка {CBR_KEY_RATE:.1f}% ↓ — {ticker} LONG ✅")
            score_breakdown.append(f"RateTrend=+{rate_pts}")
        score += rate_pts

        # ── 18. Pre-dividend accumulation (v0.9.29) ─────────────────────────────
        # За 3-7 дней до дивидендной отсечки: рынок накапливает бумагу.
        # Это отдельно от Event Calendar (который смотрит на 48ч около события).
        # Здесь: окно 3-7 дней → bias LONG (накопление) а не SHORT (гэп после отсечки).
        prediv_pts = 0
        _now_date  = now_msk().date()
        for _evt in EVENT_CALENDAR:
            if ticker not in _evt.get("tickers", []):
                continue
            if _evt.get("bias") != "short":   # только дивидендные отсечки
                continue
            try:
                _evt_date = datetime.strptime(_evt["date"], "%Y-%m-%d").date()
            except ValueError:
                continue
            _days_to_div = (_evt_date - _now_date).days
            if 3 <= _days_to_div <= 7 and direction == "LONG":
                prediv_pts = 1
                patterns.append(f"💰 Пред-дивиденд {_days_to_div}д ✅")
                score_breakdown.append(f"PreDiv=+{prediv_pts}")
                break
        score += prediv_pts

        # ── 19. OBV накопление/распределение (v0.9.29) ──────────────────────────
        # On-Balance Volume: аномальное накопление/распределение без движения цены.
        # Дивергенция OBV vs цена — опережающий индикатор институциональных позиций.
        obv_pts = 0
        obv_bull = ms.get("obv_bull_div")
        obv_bear = ms.get("obv_bear_div")
        obv_trnd = ms.get("obv_trend")

        if obv_bull and direction == "LONG":
            obv_pts = 2
            patterns.append("📊 OBV↑ дивергенция (скрытое накопление) ✅")
            score_breakdown.append(f"OBV_div=+{obv_pts}")
        elif obv_bear and direction == "SHORT":
            obv_pts = 2
            patterns.append("📊 OBV↓ дивергенция (скрытое распределение) ✅")
            score_breakdown.append(f"OBV_div=+{obv_pts}")
        elif obv_bull and direction == "SHORT":
            obv_pts = -1
            patterns.append("📊 OBV↑ против SHORT ⚠️")
            score_breakdown.append(f"OBV_div={obv_pts}")
        elif obv_bear and direction == "LONG":
            obv_pts = -1
            patterns.append("📊 OBV↓ против LONG ⚠️")
            score_breakdown.append(f"OBV_div={obv_pts}")
        score += obv_pts

        # OBV тренд без дивергенции: просто подтверждение/противоречие (+1/0)
        obv_trend_pts = 0
        if not obv_bull and not obv_bear:
            if obv_trnd == "up" and direction == "LONG":
                obv_trend_pts = 1
                score_breakdown.append(f"OBV_trend=+{obv_trend_pts}")
            elif obv_trnd == "down" and direction == "SHORT":
                obv_trend_pts = 1
                score_breakdown.append(f"OBV_trend=+{obv_trend_pts}")
        score += obv_trend_pts

        # ── 20. MA crossover — Golden/Death cross (v0.9.29) ─────────────────────
        # MA20 пробивает MA50 — надёжный среднесрочный разворотный сигнал.
        # Golden cross при LONG = подтверждение; Death cross при SHORT = подтверждение.
        cross_pts = 0
        ma_cross = ms.get("ma_crossover")
        if ma_cross == "golden_cross" and direction == "LONG":
            cross_pts = 2
            patterns.append("⚡ Golden Cross MA20/MA50 ✅")
            score_breakdown.append(f"GoldenCross=+{cross_pts}")
        elif ma_cross == "death_cross" and direction == "SHORT":
            cross_pts = 2
            patterns.append("⚡ Death Cross MA20/MA50 ✅")
            score_breakdown.append(f"DeathCross=+{cross_pts}")
        elif ma_cross == "golden_cross" and direction == "SHORT":
            cross_pts = -1
            patterns.append("⚡ Golden Cross против SHORT ⚠️")
            score_breakdown.append(f"GoldenCross={cross_pts}")
        elif ma_cross == "death_cross" and direction == "LONG":
            cross_pts = -1
            patterns.append("⚡ Death Cross против LONG ⚠️")
            score_breakdown.append(f"DeathCross={cross_pts}")
        score += cross_pts

        conflict_penalty = 0
        if ms.get("ma50_against") and ms.get("imoex_confirm") is False:
            conflict_penalty -= 1
            decision_reasons.append("trend_context_conflict")
        if ms.get("vwap_confirm") is False and ms.get("orderbook_confirm") is False:
            conflict_penalty -= 1
            decision_reasons.append("intraday_confirmation_conflict")
        if "stale_intraday" in data_quality_flags:
            conflict_penalty -= 1
            decision_reasons.append("stale_intraday")
        if conflict_penalty:
            score += conflict_penalty
            score_breakdown.append(f"Conflicts={conflict_penalty}")

        if ms.get("strategy") == "index_rebound":
            rebound_pts = 2
            score += rebound_pts
            score_breakdown.append(f"IndexRebound=+{rebound_pts}")
            if "📈 отбой IMOEX" not in patterns:
                patterns.append("📈 отбой IMOEX")
            decision_reasons.append("index_rebound_signal")

        if ms.get("strategy") == "news_event":
            event_pts = 2
            if ms.get("news_event_strength", 0) >= 3:
                event_pts += 1
            score += event_pts
            score_breakdown.append(f"NewsEvent=+{event_pts}")
            if "📰 новостной event" not in patterns:
                patterns.append("📰 новостной event")
            decision_reasons.append("news_event_signal")

        score = max(0, score)  # score не может быть отрицательным
        confidence = _score_to_confidence(score)
        pattern    = patterns[0] if patterns else "📊 Только объём"
        pattern_details = "  ".join(patterns)

        top_news = sorted(related, key=lambda n: n.strength, reverse=True)[:2]
        if not related:
            decision_reasons.append("news_absent")
        elif opposing and not agreeing:
            decision_reasons.append("news_conflict")
        elif agreeing:
            decision_reasons.append("news_agreement")

        synthesized.append({
            **ms,
            "confidence":       confidence,
            "confidence_score": score,
            "score_breakdown":  "  ".join(score_breakdown),
            "session_label":    session_label,
            "pattern":          pattern,
            "pattern_details":  pattern_details,
            "news_agree":       len(agreeing),
            "news_oppose":      len(opposing),
            "top_news":         top_news,
            "signal_version":   SIGNAL_SCHEMA_VERSION,
            "decision_reasons": sorted(set(decision_reasons)),
            "data_quality_flags": sorted(set(data_quality_flags)),
            "news_mode":        news_mode,
        })

    return synthesized


