def print_synthesized_signal(s: dict):
    d = "🟢 LONG" if s["direction"] == "LONG" else "🔴 SHORT"
    pattern_line = f"  ⚡ Паттерн: {s['pattern']}\n" if s["pattern"] else ""

    # Индикаторы
    indicators = []
    if s.get("rsi") is not None:
        indicators.append(rsi_label(s["rsi"]))
    if s.get("ma20") is not None:
        trend_arrow = "↑" if s.get("ma_trend") == "bullish" else "↓"
        indicators.append(f"MA20 {s['ma20']} {trend_arrow}")
    if s.get("ma50") is not None:
        ma50_arrow = "↑" if s.get("ma50_trend") == "bullish" else "↓"
        indicators.append(f"MA50 {s['ma50']:.1f} {ma50_arrow}")
    if s.get("adx") is not None:
        adx_label = "тренд" if s["adx"] >= 25 else ("умер." if s["adx"] >= 20 else "флэт")
        indicators.append(f"ADX {s['adx']:.0f} ({adx_label})")
    ind_line = ("  " + "  |  ".join(indicators) + "\n") if indicators else ""

    # MA50 фильтр-заметка (v0.9.2)
    ma50_line = f"  📉 {s['ma50_note']}\n" if s.get("ma50_note") else ""

    # H1 уровни и подтверждение (v0.9.2/v0.9.3)
    h1_line = ""
    h1c = s.get("h1_confirm")
    if h1c:
        ctype = "⚡ пробой" if h1c.get("type") == "breakout" else "💪 импульс"
        h1_line = f"  ✅ H1 подтверждение ({ctype}): {h1c.get('note', '')}\n"
    elif s.get("h1_resistance") or s.get("h1_support"):
        h1r = s.get("h1_resistance", "—")
        h1s = s.get("h1_support", "—")
        h1_line = f"  🕐 H1: поддержка {h1s}  сопротивление {h1r}\n"
    if s.get("h1_stop_note"):
        h1_line += f"  🎯 {s['h1_stop_note']}\n"

    # Калькулятор позиции (v0.9.2)
    pos_line = ""
    pc = s.get("position_calc")
    if pc:
        pos_line = (
            f"  💼 Позиция: {pc['lots']}л × {pc['lot_size']} акц. = {int(pc['position_rub'])}₽\n"
            f"     Риск {pc['risk_pct']}% = {int(pc['risk_rub'])}₽ → факт. {int(pc['actual_risk_rub'])}₽ ({pc['actual_risk_pct']}%)\n"
        )

    # Фибоначчи
    fib_line = ""
    if s.get("nearest_fib"):
        fib_name, fib_val = s["nearest_fib"]
        fib_line = f"  Фибо {fib_name}  {fib_val}\n"

    # USDRUB заметка
    usd_line = f"  💱 {s['usdrub_note']}\n" if s.get("usdrub_note") else ""

    # Brent / Gold заметка (v0.9.29)
    brent_icon_c = " ✅" if s.get("brent_confirm") is True else (" ⚠️" if s.get("brent_confirm") is False else "")
    brent_line_c = f"  🛢 {s['brent_note']}{brent_icon_c}\n" if s.get("brent_note") else ""
    gold_icon_c  = " ✅" if s.get("gold_confirm") is True else (" ⚠️" if s.get("gold_confirm") is False else "")
    gold_line_c  = f"  🥇 {s['gold_note']}{gold_icon_c}\n" if s.get("gold_note") else ""

    # IMOEX заметка
    imoex_line = f"  📈 {s['imoex_note']}\n" if s.get("imoex_note") else ""

    # VWAP заметка (v0.9)
    vwap_icon = "✅" if s.get("vwap_confirm") else ("⚠️" if s.get("vwap_confirm") is False else "")
    vwap_line = f"  〽️ {s['vwap_note']} {vwap_icon}\n" if s.get("vwap_note") else ""

    # Стакан заметка (v0.9)
    ob_icon = "✅" if s.get("orderbook_confirm") else ("⚠️" if s.get("orderbook_confirm") is False else "")
    ob_line = f"  📋 {s['orderbook_note']} {ob_icon}\n" if s.get("orderbook_note") else ""

    # Новости
    news_summary = ""
    for n in s.get("top_news", []):
        nd = "📈" if n.direction == "LONG" else "📉"
        status_short = n.status.split("(")[0].strip() if n.status else ""
        news_summary += f"  {nd} {status_short}  {n.title[:52]}\n"
    if not news_summary:
        news_summary = "  📭 Новостей по тикеру нет\n"

    sig_type_label = "📈 MOMENTUM" if s.get("signal_type") == "momentum" else "↩️ MEAN-REV"
    score_line     = f"{s.get('confidence_score', '?')}/17 очков"
    sizing_lbl     = s.get("sizing_source", "")
    h1_atr_lbl     = f"  H1 ATR={s['h1_atr']:.2f}" if s.get("h1_atr") else ""

    print(f"""
╔══════════════════════════════════════════════╗
  {d}  —  {s['ticker']}   {sig_type_label}  [×{s['volume_ratio']}]
  Уверенность: {s['confidence']}  [{score_line}]
  ⏱ {s.get('session_label', '')}
╠══════════════════════════════════════════════╣
  Вход    {s['entry']}
  Стоп    {s['stop']}  (-{s.get('stop_pct','?')}%)  [{sizing_lbl}{h1_atr_lbl}]
  Тейк 1  {s['take1']}  (+{s.get('take1_pct','?')}%)  [50% — стоп → БУ]
  Тейк 2  {s['take2']}  (+{s.get('take2_pct','?')}%)  [50%]
  Тренд↗  {s.get('trend_target', '—')}  (ориентир)
  R/R     1:{s['rr']}
╠══════════════════════════════════════════════╣
{ind_line}{ma50_line}{h1_line}{pos_line}{fib_line}{usd_line}{brent_line_c}{gold_line_c}{imoex_line}{vwap_line}{ob_line}{pattern_line}{news_summary}╚══════════════════════════════════════════════╝""")


def print_news_signal(s: NewsItem):
    d          = "🟢 LONG" if s.direction == "LONG" else "🔴 SHORT"
    bar        = "●" * s.strength + "○" * (3 - s.strength)
    ai_mark    = "🤖 AI" if s.analyzed_by == "ai" else "🔑 KW"
    labels     = {
        "CB_RATE":     "🏦 ЦБ",
        "SANCTIONS":   "⚠️  Санкции",
        "OIL":         "🛢️  Нефть",
        "MACRO":       "📊 Макро",
        "EARNINGS":    "💰 Отчёт",
        "GEOPOLITICS": "🌍 Геополитика",
        "CURRENCY":    "💱 Валюта",
        "CORP":        "🏢 M&A/Оферта",   # v0.9.25
        "NEWS":        "📰 Новость",
    }
    event_label = labels.get(s.event_type, "📰")
    reason_line = f"\n  💬 {s.reason}" if s.reason else ""
    status_line = f"\n  {s.status}" if s.status else ""
    age         = parse_news_age(s.published)
    age_str     = f"{age:.1f}ч назад" if age is not None else ""

    print(f"""
┌─────────────────────────────────────────────┐
  {d}  [{bar}]  {event_label}  {ai_mark}
  Тикеры: {', '.join(s.tickers)}
  {s.title[:75]}{reason_line}{status_line}
  {s.source}  {age_str}
└─────────────────────────────────────────────┘""")


