# ══════════════════════════════════════════════════════════════════════════════
#  TELEGRAM — отправка сигналов
# ══════════════════════════════════════════════════════════════════════════════

def _esc(text: str) -> str:
    """Экранирует HTML-спецсимволы (<, >, &) для безопасной вставки в Telegram HTML.
    Применять ко ВСЕМ пользовательским строкам (заголовки новостей, причины, примечания).
    НЕ применять к строкам, которые уже содержат валидные HTML-теги (<b>, <i> и т.д.).
    """
    return _html.escape(str(text), quote=False)


_TG_MAX_LEN = 4000   # чуть меньше Telegram-лимита 4096 для безопасности


def _tg_chunks(s: str, n: int = _TG_MAX_LEN) -> list[str]:
    """Режет длинное сообщение на части по \n, не ломая HTML-теги."""
    if len(s) <= n:
        return [s]
    out, buf, cur = [], [], 0
    for line in s.split("\n"):
        line_len = len(line) + 1
        if cur + line_len > n and buf:
            out.append("\n".join(buf))
            buf, cur = [line], line_len
        else:
            buf.append(line)
            cur += line_len
    if buf:
        out.append("\n".join(buf))
    return out


def tg_send(text: str, parse_mode: str = "HTML") -> bool:
    """Отправляем сообщение в Telegram Bot API. Возвращает True при успехе.

    v0.9.10: если HTML-сообщение получает 400 (parse error) — автоматически
    повторяем отправку в plain text, чтобы уведомление не потерялось.
    v0.9.36: добавлено авто-чанкование сообщений > 4000 символов.
    Полный текст и ответ сервера логируются для диагностики.
    """
    if not TELEGRAM_TOKEN or not TELEGRAM_CHAT_ID:
        return False
    url = f"https://api.telegram.org/bot{TELEGRAM_TOKEN}/sendMessage"

    # v0.9.36: если сообщение длинное — шлём по частям, иначе Telegram ответит 400
    chunks = _tg_chunks(text)
    if len(chunks) > 1:
        logger.info("tg_send: длина %d → %d частей", len(text), len(chunks))
    all_ok = True
    for idx, chunk in enumerate(chunks, 1):
        try:
            logger.debug("tg_send [%s, part %d/%d, %d chars]: %.300s",
                         parse_mode, idx, len(chunks), len(chunk), chunk)
            r = requests.post(url, json={
                "chat_id":    TELEGRAM_CHAT_ID,
                "text":       chunk,
                "parse_mode": parse_mode,
            }, timeout=10)
            if r.status_code == 200:
                continue

            err_body = r.text[:400]
            print(f"  ⚠️  Telegram error {r.status_code}: {err_body}")
            logger.warning("tg_send HTTP %d (part %d/%d): %s",
                           r.status_code, idx, len(chunks), err_body)

            # fallback — если HTML не прошёл (400), шлём без форматирования
            if r.status_code == 400 and parse_mode == "HTML":
                import re as _re
                plain = _re.sub(r"<[^>]+>", "", chunk)   # убираем все HTML-теги
                logger.warning("tg_send fallback plain-text: %.300s", plain)
                r2 = requests.post(url, json={
                    "chat_id": TELEGRAM_CHAT_ID,
                    "text":    plain,
                }, timeout=10)
                if r2.status_code == 200:
                    print("  ✅ Telegram: повторно отправлено (plain text)")
                    logger.info("tg_send fallback OK")
                    continue
                logger.warning("tg_send fallback HTTP %d: %s",
                               r2.status_code, r2.text[:200])
            all_ok = False
        except Exception as e:
            print(f"  ⚠️  Telegram недоступен: {e}")
            logger.warning("tg_send: %s", e)
            all_ok = False
    return all_ok


def tg_selfcheck() -> bool:
    """v0.9.36: при старте бота — убедиться, что токен валиден (getMe)."""
    if not TELEGRAM_TOKEN:
        logger.warning("tg_selfcheck: токен пустой")
        return False
    try:
        r = requests.get(
            f"https://api.telegram.org/bot{TELEGRAM_TOKEN}/getMe", timeout=5
        )
        r.raise_for_status()
        bot_name = r.json().get("result", {}).get("username", "?")
        logger.info("tg_selfcheck OK: @%s", bot_name)
        return True
    except Exception as e:
        logger.error("tg_selfcheck FAIL: %s — проверь TG_TOKEN в .env", e)
        return False


def _pct(current, ref) -> str:
    """Разница в процентах со знаком: +2.1% или -1.3%
    v0.9.10: безопасно обрабатывает None и 0 — возвращает "" вместо исключения.
    """
    try:
        if current is None or ref is None or ref == 0:
            return ""
        d = (float(current) - float(ref)) / float(ref) * 100
        return f"{d:+.1f}%"
    except (TypeError, ValueError, ZeroDivisionError):
        return ""


def tg_format_signal(s: dict, reason: str = "new") -> str:
    """
    Форматирует синтезированный рыночный сигнал для Telegram (HTML).
    reason: "new" | "upgrade" | "repeat" | "stop_hit" | "target1" | "target2"
    """
    d_emoji = "🟢" if s["direction"] == "LONG" else "🔴"
    dir_str = "LONG" if s["direction"] == "LONG" else "SHORT"

    header_emoji = {
        "new":      "🚨",
        "upgrade":  "🔝",
        "repeat":   "↩️",
        "stop_hit": "🛑",
        "target1":  "🎯",
        "target2":  "🎯🎯",
    }.get(reason, "📊")

    header_label = {
        "new":      "НОВЫЙ СИГНАЛ",
        "upgrade":  "УВЕРЕННОСТЬ ВЫРОСЛА",
        "repeat":   "СИГНАЛ АКТУАЛЕН",
        "stop_hit": "СТОП ПРОБИТ",
        "target1":  "ТЕЙК 1 ВЗЯТ",
        "target2":  "ТЕЙК 2 ВЗЯТ",
    }.get(reason, "СИГНАЛ")

    entry         = s.get("entry",  0)
    stop          = s.get("stop",   0)
    take1         = s.get("take1")
    take2         = s.get("take2")
    trend_target  = s.get("trend_target")
    breakeven_stp = s.get("breakeven_stop", entry)
    stop_pct      = s.get("stop_pct")
    take1_pct     = s.get("take1_pct")
    take2_pct     = s.get("take2_pct")
    rr            = s.get("rr", s.get("rr_ratio", "?"))

    pattern_line = f"⚡ <b>{s['pattern']}</b>\n" if s.get("pattern") else ""

    # v0.9.4 — тип стратегии
    sig_type = s.get("signal_type", "mean_reversion")
    if sig_type == "momentum":
        strategy_line = "📈 <b>Стратегия: MOMENTUM</b> — вход по тренду\n"
    else:
        strategy_line = "↩️ <b>Стратегия: MEAN-REVERSION</b> — отскок/откат\n"

    # Индикаторы (v0.9.5: + ADX)
    ind_parts = []
    if s.get("rsi") is not None:
        ind_parts.append(rsi_label(s["rsi"]))
    if s.get("ma20") is not None:
        arrow = "↑" if s.get("ma_trend") == "bullish" else "↓"
        ind_parts.append(f"MA20 {s['ma20']:.1f} {arrow}")
    if s.get("ma50") is not None:
        ma50_arrow = "↑" if s.get("ma50_trend") == "bullish" else "↓"
        ind_parts.append(f"MA50 {s['ma50']:.1f} {ma50_arrow}")
    if s.get("adx") is not None:
        adx_lbl = "тренд" if s["adx"] >= 25 else ("умер." if s["adx"] >= 20 else "флэт")
        ind_parts.append(f"ADX {s['adx']:.0f} ({adx_lbl})")
    ind_line = "📊 " + "  |  ".join(ind_parts) + "\n" if ind_parts else ""

    # MA50 заметка (v0.9.2)
    ma50_icon = " ⚠️" if s.get("ma50_against") else " ✅" if s.get("ma50_trend") else ""
    ma50_line = f"📉 {s['ma50_note']}{ma50_icon}\n" if s.get("ma50_note") else ""

    # H1 уровни и подтверждение (v0.9.2/v0.9.3)
    h1_line = ""
    h1c = s.get("h1_confirm")
    if h1c:
        ctype = "⚡ пробой" if h1c.get("type") == "breakout" else "💪 импульс"
        h1_line = f"✅ <b>H1 подтверждение</b> ({ctype})\n📝 {_esc(h1c.get('note', ''))}\n"
    elif s.get("h1_resistance") or s.get("h1_support"):
        h1r = s.get("h1_resistance", "—")
        h1s = s.get("h1_support", "—")
        h1_line = f"🕐 H1: поддержка {h1s}  /  сопротивление {h1r}\n"
    if s.get("h1_stop_note"):
        h1_line += f"📌 {_esc(s['h1_stop_note'])}\n"

    # Калькулятор позиции (v0.9.2)
    pos_line = ""
    pc = s.get("position_calc")
    if pc:
        pos_line = (
            f"💼 Позиция: {pc['lots']}л = {int(pc['position_rub'])}₽  "
            f"│  риск {pc['risk_pct']}% = {int(pc['actual_risk_rub'])}₽\n"
        )

    # Фибо
    fib_line = ""
    if s.get("nearest_fib"):
        fn, fv = s["nearest_fib"]
        fib_line = f"📐 Фибо {fn}: {fv}\n"

    # USDRUB / IMOEX / Brent / Gold  (v0.9.29)
    usd_line   = f"💱 {s['usdrub_note']}\n"   if s.get("usdrub_note")  else ""
    imoex_against = " ⚠️" if s.get("imoex_confirm") is False else (
                    " ✅" if s.get("imoex_confirm") is True else ""
    )
    imoex_line = f"📈 {s['imoex_note']}{imoex_against}\n" if s.get("imoex_note") else ""
    brent_icon = " ✅" if s.get("brent_confirm") is True else (" ⚠️" if s.get("brent_confirm") is False else "")
    brent_line = f"🛢 {_esc(s['brent_note'])}{brent_icon}\n" if s.get("brent_note") else ""
    gold_icon  = " ✅" if s.get("gold_confirm") is True else (" ⚠️" if s.get("gold_confirm") is False else "")
    gold_line  = f"🥇 {_esc(s['gold_note'])}{gold_icon}\n" if s.get("gold_note") else ""

    # v0.9.14: недельный TF
    weekly_line = ""
    if s.get("weekly_note"):
        weekly_line = f"{_esc(s['weekly_note'])}\n"

    # v0.9.14: маржа для SHORT
    margin_line = ""
    if s.get("direction") == "SHORT" and s.get("margin_daily") is not None:
        md  = s["margin_daily"]
        mbd = s.get("margin_break_even_days")
        lot_sz = 1  # показываем на 1 акцию, трейдер умножит на лоты
        if mbd:
            margin_line = f"📅 Маржа ≈{md:.4f}₽/акц/день · окупается за {mbd:.0f} дн.\n"
        else:
            margin_line = f"📅 Маржа ≈{md:.4f}₽/акц/день\n"

    # VWAP (v0.9)
    vwap_icon  = " ✅" if s.get("vwap_confirm") is True else (" ⚠️" if s.get("vwap_confirm") is False else "")
    vwap_line  = f"〽️ {s['vwap_note']}{vwap_icon}\n" if s.get("vwap_note") else ""

    # Стакан (v0.9)
    ob_icon = " ✅" if s.get("orderbook_confirm") is True else (" ⚠️" if s.get("orderbook_confirm") is False else "")
    ob_line = f"📋 {s['orderbook_note']}{ob_icon}\n" if s.get("orderbook_note") else ""

    # Топ-новость
    news_lines = ""
    for n in s.get("top_news", [])[:2]:
        nd = "📈" if n.direction == "LONG" else "📉"
        st = n.status.split("(")[0].strip() if n.status else ""
        # v0.9.10: escape news titles — RSS-заголовки могут содержать < > & → Telegram 400
        news_lines += f"{nd} {_esc(st)}  {_esc(n.title[:55])}\n"
    if not news_lines:
        news_lines = "📭 Новостей нет\n"

    now_str = now_msk().strftime("%H:%M МСК")

    text = (
        f"{header_emoji} <b>{header_label}</b>   {now_str}\n"
        f"{d_emoji} <b>{dir_str} — {s['ticker']}</b>  [объём ×{s.get('volume_ratio','?')}]\n"
        f"Уверенность: {s['confidence']}  [{s.get('confidence_score','?')}/17 очков]\n"
        f"⏱ {s.get('session_label', '')}\n"
        f"{strategy_line}"
        f"{pattern_line}"
        f"─────────────────────────\n"
        f"💰 <b>Вход:    {entry}</b>\n"
        f"🛑 Стоп:    {stop}  ({_pct(stop, entry)})  [{s.get('sizing_source','')}]\n"
        f"🎯 Тейк 1:  {take1}  ({_pct(take1, entry)})  [50% → стоп в БУ]\n"
        f"🎯 Тейк 2:  {take2}  ({_pct(take2, entry)})  [50%]\n"
        + (f"🔭 Тренд↗: {trend_target}  (ориентир)\n" if trend_target else "")
        + f"📐 R/R: 1:{rr}\n"
        + (pos_line)
        + f"─────────────────────────\n"
        f"{ind_line}"
        f"{ma50_line}"
        f"{h1_line}"
        f"{fib_line}"
        f"{usd_line}"
        f"{brent_line}"
        f"{gold_line}"
        f"{imoex_line}"
        f"{weekly_line}"
        f"{margin_line}"
        f"{vwap_line}"
        f"{ob_line}"
        f"─────────────────────────\n"
        f"{news_lines}"
    )
    return text.strip()


def tg_format_news_only(n: NewsItem) -> str:
    """Форматирует новостной сигнал (без рыночного подтверждения) для Telegram."""
    d_emoji = "🟢" if n.direction == "LONG" else "🔴"
    dir_str = "LONG" if n.direction == "LONG" else "SHORT"
    bar = "●" * n.strength + "○" * (3 - n.strength)
    labels = {
        "CB_RATE": "🏦 ЦБ",     "SANCTIONS":   "⚠️ Санкции",
        "OIL":     "🛢 Нефть",  "MACRO":       "📊 Макро",
        "EARNINGS":"💰 Отчёт",  "GEOPOLITICS": "🌍 Геополитика",
        "CURRENCY":"💱 Валюта", "NEWS":        "📰",
        "CORP":    "🏢 M&A/Оферта",            # v0.9.25
    }
    evt   = labels.get(n.event_type, "📰")
    age   = parse_news_age(n.published)
    age_s = f"{age:.1f}ч назад" if age is not None else ""
    tickers_s = ", ".join(n.tickers)
    st    = f"\n{n.status}" if n.status else ""

    text = (
        f"📰 <b>НОВОСТНОЙ СИГНАЛ</b>\n"
        f"{d_emoji} <b>{dir_str} — {tickers_s}</b>  [{bar}]  {evt}\n"
        f"{_esc(n.title)}\n"
        f"{_esc(n.reason)}\n"
        f"{_esc(st)}\n"
        f"🕐 {age_s}  {_esc(n.source)}"
    )
    return text.strip()


def tg_format_watch_alert(ticker: str, direction: str, levels: dict,
                           anomaly: dict, expires_hours: float) -> str:
    """
    Telegram-сообщение когда тикер добавлен в H1 watch-лист (v0.9.3).
    Это НЕ торговый сигнал — только уведомление о зоне интереса.
    """
    d_emoji = "🟢" if direction == "LONG" else "🔴"
    dir_str = "LONG" if direction == "LONG" else "SHORT"
    ratio   = anomaly.get("ratio", "?")
    price   = levels.get("last_close", "?")
    ma50    = levels.get("ma50")
    atr     = levels.get("atr")

    ma50_line = f"📐 MA50: {ma50:.1f}\n" if ma50 else ""
    atr_line  = f"📏 ATR: {atr:.2f}\n" if atr else ""

    text = (
        f"👀 <b>ЗОНА ИНТЕРЕСА — ЖДУ H1</b>\n"
        f"{d_emoji} <b>{dir_str} — {ticker}</b>  [объём ×{ratio}]\n"
        f"─────────────────────────\n"
        f"💰 Цена: {price}\n"
        f"{ma50_line}"
        f"{atr_line}"
        f"─────────────────────────\n"
        f"⏳ Дневная аномалия объёма подтверждена.\n"
        f"Жду H1-подтверждение входа ({expires_hours:.0f}ч).\n"
        f"Сигнал придёт отдельно при подтверждении."
    )
    return text.strip()


