def tg_portfolio_summary(state: dict, equity: float = 0.0) -> str:
    """
    Краткий снимок открытых sandbox-позиций для вставки в ВХОД/ЗАКРЫТИЕ.
    Формат: "📊 Equity: 1 001 234₽  |  SBER🟢×5  GAZP🔴×2"
    """
    open_pos = []
    for sk, sv in state.items():
        if not sk.startswith("sb_"):
            continue
        if sv.get("closed_at"):
            continue
        base_key = sk[3:]
        if state.get(base_key, {}).get("hit") in ("target2", "stop_hit"):
            continue
        ticker    = sv.get("ticker", "?")
        direction = sv.get("direction", "LONG")
        lots      = sv.get("lots", "?")
        emoji     = "🟢" if direction == "LONG" else "🔴"
        open_pos.append(f"{ticker}{emoji}×{lots}")
    eq_str = f"{equity:,.0f}₽" if equity > 0 else "—"
    pos_str = "  ".join(open_pos) if open_pos else "нет открытых"
    return f"📊 Equity: {eq_str}  |  {pos_str}"


def tg_format_open(s: dict, lots: int, equity: float, risk_rub, state: dict) -> str:
    """
    v0.9.19: Slim-формат уведомления об ОТКРЫТИИ sandbox-позиции.
    Содержит только ключевые параметры сделки + текущий портфель.
    """
    direction = s.get("direction", "LONG")
    ticker    = s.get("ticker", "")
    entry     = s.get("entry", 0)
    stop      = s.get("stop", 0)
    take2     = s.get("take2", 0)
    rr        = s.get("rr", s.get("rr_ratio", "?"))
    conf      = s.get("confidence", "")
    d_emoji   = "🟢" if direction == "LONG" else "🔴"
    stop_pct  = _pct(stop, entry)
    take_pct  = _pct(take2, entry)
    risk_str  = f"{int(risk_rub)}₽" if risk_rub else "—"
    now_str   = now_msk().strftime("%H:%M МСК")

    text = (
        f"🚨 <b>ВХОД</b>  {now_str}\n"
        f"{d_emoji} <b>{direction} — {ticker}</b>  [{conf}]\n"
        f"─────────────────────────\n"
        f"💰 Цена входа:  <b>{entry}</b>\n"
        f"📦 Лотов: {lots}  │  ⚠️ Риск: {risk_str}\n"
        f"🛑 Стоп:  {stop}  ({stop_pct})\n"
        f"🎯 Тейк:  {take2}  ({take_pct})\n"
        f"📐 R/R: 1:{rr}\n"
        f"─────────────────────────\n"
        f"{tg_portfolio_summary(state, equity)}"
    )
    return text.strip()


def tg_format_close(s: dict, reason: str, equity: float, state: dict) -> str:
    """
    v0.9.19: Slim-формат уведомления о ЗАКРЫТИИ позиции (стоп или тейк).
    Показывает направление, причину, P&L% и текущий портфель.
    """
    direction = s.get("direction", "LONG")
    ticker    = s.get("ticker", "")
    entry     = s.get("entry", 0) or 0
    current   = s.get("current_price") or 0
    d_emoji   = "🟢" if direction == "LONG" else "🔴"

    icon  = {"stop_hit": "🛑", "target1": "🎯", "target2": "🎯🎯"}.get(reason, "📋")
    label = {"stop_hit": "СТОП", "target1": "ТЕЙК 1", "target2": "ТЕЙК 2"}.get(reason, reason.upper())

    pnl_str = ""
    if entry and current:
        pnl_pct = (current - entry) / entry * 100
        if direction == "SHORT":
            pnl_pct = -pnl_pct
        sign = "+" if pnl_pct >= 0 else ""
        pnl_str = f"\n💸 P&L: {sign}{pnl_pct:.2f}%"

    now_str = now_msk().strftime("%H:%M МСК")
    text = (
        f"{icon} <b>{label}</b>  {now_str}\n"
        f"{d_emoji} <b>{direction} — {ticker}</b>\n"
        f"💰 Вход: {entry}  →  Цена: {current or '—'}"
        f"{pnl_str}\n"
        f"─────────────────────────\n"
        f"{tg_portfolio_summary(state, equity)}"
    )
    return text.strip()


