def load_trade_log() -> list:
    """Загружает trade_log.json. Возвращает [] если файл не существует."""
    data = load_json_file(TRADE_LOG_FILE, [], "load_trade_log")
    return data if isinstance(data, list) else []


def save_trade_log(log: list) -> None:
    """Сохраняет trade_log.json."""
    save_json_file_atomic(TRADE_LOG_FILE, log, "save_trade_log")


def _backup_runtime_json(path: str, migration_id: str) -> str | None:
    if not os.path.exists(path):
        return None
    try:
        backup_dir = os.path.join(os.path.dirname(path), "state_backups")
        os.makedirs(backup_dir, exist_ok=True)
        stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
        backup = os.path.join(
            backup_dir,
            f"{os.path.basename(path)}.{migration_id}.{stamp}.bak",
        )
        shutil.copy2(path, backup)
        return backup
    except Exception as e:
        logger.warning("state_migration backup failed for %s: %s", path, e)
        return None


def _state_has_open_sb_for_base(state: dict, base_key: str, base_val: dict) -> bool:
    exact = state.get(f"sb_{base_key}")
    if isinstance(exact, dict) and not exact.get("closed_at") and exact.get("order_id"):
        return True
    ticker = base_val.get("ticker")
    direction = base_val.get("direction")
    for key, val in state.items():
        if not str(key).startswith("sb_") or not isinstance(val, dict):
            continue
        if val.get("closed_at") or not val.get("order_id"):
            continue
        if val.get("base_signal_key") == base_key:
            return True
        if ticker and direction and val.get("ticker") == ticker and val.get("direction") == direction:
            return True
    return False


def _repair_anomalous_close_price(row: dict, state: dict) -> bool:
    """Repair sandbox rows where broker returned order value instead of unit price."""
    try:
        entry = float(row.get("entry") or 0)
        exit_price = float(row.get("exit_price") or 0)
        if entry <= 0 or exit_price <= 0 or exit_price / entry < 20:
            return False
        signal_id = str(row.get("signal_id") or "")
        sb_entry = state.get(f"sb_{signal_id}") if isinstance(state, dict) else None
        lots = float((sb_entry or {}).get("lots") or row.get("lots") or 0)
        if lots <= 0:
            return False
        ticker = row.get("ticker") or (sb_entry or {}).get("ticker") or ""
        lot_size = float(LOT_SIZES.get(str(ticker), 1) or 1)
        candidates = [exit_price / lots]
        if lot_size > 1:
            candidates.append(exit_price / (lots * lot_size))
        plausible = [c for c in candidates if c > 0 and 0.2 <= c / entry <= 5.0]
        if not plausible:
            return False
        candidate = min(plausible, key=lambda c: abs(c - entry))
        row["exit_price_raw"] = exit_price
        row["exit_price"] = round(candidate, 4)
        mult = 1 if row.get("direction") == "LONG" else -1
        row["pnl_pct"] = round(mult * (row["exit_price"] - entry) / entry * 100, 2)
        divisor = lots if candidate == candidates[0] else lots * lot_size
        note = f"[PRICE_REPAIRED: raw_exit_price={exit_price} / divisor={int(divisor) if divisor.is_integer() else divisor}]"
        if note not in (row.get("notes") or ""):
            row["notes"] = ((row.get("notes") or "") + " " + note).strip()
        if isinstance(sb_entry, dict):
            sb_entry["close_price_raw"] = exit_price
            sb_entry["close_price"] = row["exit_price"]
        return True
    except Exception:
        return False


def run_state_migrations(force: bool = False) -> dict:
    """One-shot cleanup for pre execution-contract runtime JSON files.

    Keeps broker/sandbox position records, archives everything before changing it,
    and removes ambiguous legacy signal/trade rows from active files.
    """
    if os.environ.get("DISABLE_STATE_MIGRATIONS", "").lower() == "true":
        return {"skipped": "disabled"}

    migrations = load_json_file(STATE_MIGRATIONS_FILE, {}, "load_state_migrations")
    if not isinstance(migrations, dict):
        migrations = {}
    if migrations.get(STATE_MIGRATION_VERSION) and not force:
        return {"skipped": "already_applied"}

    summary: dict[str, object] = {
        "version": STATE_MIGRATION_VERSION,
        "state_removed": 0,
        "state_marked": 0,
        "ntg_removed": 0,
        "trade_removed": 0,
        "price_repaired": 0,
        "backups": {},
    }

    state = load_signals_state()
    if state:
        summary["backups"]["signals_state"] = _backup_runtime_json(SIGNALS_STATE_FILE, STATE_MIGRATION_VERSION)
        migrated: dict = {}
        state_changed = False
        now = datetime.now(timezone.utc)
        for key, val in state.items():
            if not isinstance(val, dict):
                migrated[key] = val
                continue
            key_str = str(key)
            if key_str.startswith("ntg_"):
                sent = val.get("sent")
                try:
                    sent_dt = datetime.fromisoformat(str(sent).replace("Z", "+00:00"))
                    if sent_dt.tzinfo is None:
                        sent_dt = sent_dt.replace(tzinfo=timezone.utc)
                    if (now - sent_dt).total_seconds() > 86400:
                        summary["ntg_removed"] = int(summary["ntg_removed"]) + 1
                        state_changed = True
                        continue
                except Exception:
                    summary["ntg_removed"] = int(summary["ntg_removed"]) + 1
                    state_changed = True
                    continue
                migrated[key] = val
                continue
            if key_str.startswith("sb_"):
                if not val.get("execution_status"):
                    val["execution_status"] = "closed" if val.get("closed_at") else ("filled" if val.get("order_id") else "orphan")
                    summary["state_marked"] = int(summary["state_marked"]) + 1
                    state_changed = True
                base_key = key_str[3:]
                if not val.get("base_signal_key") and base_key in state:
                    val["base_signal_key"] = base_key
                    summary["state_marked"] = int(summary["state_marked"]) + 1
                    state_changed = True
                migrated[key] = val
                continue
            if not val.get("execution_status") and not _state_has_open_sb_for_base(state, key_str, val):
                summary["state_removed"] = int(summary["state_removed"]) + 1
                state_changed = True
                continue
            if not val.get("execution_status"):
                val["execution_status"] = "filled"
                summary["state_marked"] = int(summary["state_marked"]) + 1
                state_changed = True
            migrated[key] = val
        if state_changed:
            save_signals_state(migrated)
            state = migrated

    trade_log = load_trade_log()
    if trade_log:
        summary["backups"]["trade_log"] = _backup_runtime_json(TRADE_LOG_FILE, STATE_MIGRATION_VERSION)
        kept = []
        trade_changed = False
        for row in trade_log:
            if not isinstance(row, dict):
                trade_changed = True
                continue
            if not row.get("execution_status"):
                summary["trade_removed"] = int(summary["trade_removed"]) + 1
                trade_changed = True
                continue
            if _repair_anomalous_close_price(row, state):
                summary["price_repaired"] = int(summary["price_repaired"]) + 1
                trade_changed = True
            kept.append(row)
        if trade_changed:
            save_trade_log(kept)
            save_signals_state(state)

    migrations[STATE_MIGRATION_VERSION] = {
        "applied_at": datetime.now(timezone.utc).isoformat(),
        **summary,
    }
    save_json_file_atomic(STATE_MIGRATIONS_FILE, migrations, "save_state_migrations")
    logger.warning("state_migration applied: %s", summary)
    append_decision_log({
        "action": "migrated",
        "reason": "legacy_state_cleanup",
        "signal_version": SIGNAL_SCHEMA_VERSION,
        **{k: v for k, v in summary.items() if k != "backups"},
    })
    return summary


def append_score_log(entry: dict) -> None:
    """
    v0.9.23: Дописывает одну строку в signals_score_log.jsonl.
    JSONL формат — одна запись в строку, файл можно tail -f и grep.
    Пишем: торгуемые, отклонённые (weekly_hard_block, cutoff, дубль, heat, выходной).
    Так я могу анализировать что блокируется и почему, без потери данных.
    """
    try:
        entry.setdefault("ts", now_msk().strftime("%Y-%m-%d %H:%M"))
        entry.setdefault("signal_version", SIGNAL_SCHEMA_VERSION)
        with open(SCORE_LOG_FILE, "a", encoding="utf-8") as f:
            f.write(json.dumps(entry, ensure_ascii=False) + "\n")
        append_decision_log({
            "action": entry.get("action"),
            "reason": entry.get("reason"),
            "ticker": entry.get("ticker"),
            "direction": entry.get("direction"),
            "score": entry.get("score"),
            "confidence": entry.get("confidence"),
            "signal_id": entry.get("signal_id"),
            "signal_version": entry.get("signal_version"),
        })
    except Exception as e:
        logger.warning("append_score_log: %s", e)


def append_opportunity_log(entry: dict) -> None:
    """
    Append-only journal for replay/analysis. It records strong candidates even
    when they are not executable because of tier/capability/risk.
    """
    try:
        entry.setdefault("ts", now_msk().strftime("%Y-%m-%d %H:%M"))
        entry.setdefault("signal_version", SIGNAL_SCHEMA_VERSION)
        ticker = entry.get("ticker")
        entry.setdefault("ticker_tier", ticker_tier(ticker))
        with open(OPPORTUNITY_LOG_FILE, "a", encoding="utf-8") as f:
            f.write(json.dumps(entry, ensure_ascii=False) + "\n")
    except Exception as e:
        logger.warning("append_opportunity_log: %s", e)


def daily_change_pct(candles: list[dict]) -> float | None:
    """Change of the latest daily candle versus the previous close."""
    closes = [c.get("close") for c in candles if c.get("close")]
    if len(closes) < 2 or not closes[-2]:
        return None
    return round((closes[-1] - closes[-2]) / closes[-2] * 100, 2)


def _radar_direction(change_pct: float | None, levels: dict) -> str:
    if change_pct is not None and change_pct > 0:
        return "LONG"
    if change_pct is not None and change_pct < 0:
        return "SHORT"
    price = levels.get("last_close") or 0
    ma50 = levels.get("ma50") or price
    return "LONG" if price >= ma50 else "SHORT"


def append_market_radar_opportunity(
    ticker: str,
    reason: str,
    *,
    direction: str | None = None,
    levels: dict | None = None,
    anomaly: dict | None = None,
    change_pct: float | None = None,
    extra: dict | None = None,
) -> bool:
    """
    Deduplicated watch-only journal entry for candidates that are visible to the
    market scanner but have not become executable signals.
    """
    today = now_msk().strftime("%Y-%m-%d")
    key = (today, ticker, reason)
    if key in _MARKET_RADAR_SEEN:
        return False
    _MARKET_RADAR_SEEN.add(key)
    levels = levels or {}
    anomaly = anomaly or {}
    entry = {
        "ticker": ticker,
        "direction": direction or _radar_direction(change_pct, levels),
        "action": "watch_only",
        "reason": reason,
        "price": levels.get("last_close"),
        "daily_change_pct": change_pct,
        "volume_ratio": anomaly.get("ratio"),
        "last_volume": anomaly.get("last_volume"),
        "avg_volume": anomaly.get("avg_volume"),
        "absolute_ok": anomaly.get("absolute_ok"),
        "data_quality_flags": [],
        "decision_reasons": [reason],
    }
    if extra:
        entry.update(extra)
    append_opportunity_log(entry)
    return True


def maybe_log_price_momentum_radar(ticker: str, candles: list[dict], levels: dict, anomaly: dict) -> bool:
    """
    Logs large directional daily moves that missed the stricter volume-anomaly
    gate. This is diagnostics/radar only, never an auto-order trigger.
    """
    change_pct = daily_change_pct(candles)
    ratio = anomaly.get("ratio") or 0
    if change_pct is None:
        return False
    if abs(change_pct) < PRICE_RADAR_MIN_ABS_CHANGE_PCT:
        return False
    if ratio < PRICE_RADAR_MIN_VOLUME_RATIO and not anomaly.get("absolute_ok"):
        return False
    return append_market_radar_opportunity(
        ticker,
        "price_momentum_radar",
        levels=levels,
        anomaly=anomaly,
        change_pct=change_pct,
        extra={"threshold_abs_change_pct": PRICE_RADAR_MIN_ABS_CHANGE_PCT},
    )


def maybe_log_index_rebound_radar(
    ticker: str,
    intraday: dict,
    index_intraday: dict,
    levels: dict,
    anomaly: dict,
    change_pct: float | None,
) -> bool:
    """
    Broad-market bounce radar. It marks beta/liquid tickers that rebound together
    with IMOEX even when daily volume is not anomalous enough for auto-trading.
    """
    ok, _reason = is_index_rebound_candidate(ticker, intraday, index_intraday)
    if not ok:
        return False
    idx_rebound = index_intraday.get("rebound_from_low_pct") or 0
    ticker_rebound = intraday.get("rebound_from_low_pct") or 0
    ticker_high_rebound = intraday.get("rebound_high_from_low_pct") or 0
    return append_market_radar_opportunity(
        ticker,
        "index_rebound_radar",
        direction="LONG",
        levels=levels,
        anomaly=anomaly,
        change_pct=change_pct,
        extra={
            "intraday_change_pct": intraday.get("change_pct"),
            "rebound_from_low_pct": ticker_rebound,
            "rebound_high_from_low_pct": ticker_high_rebound,
            "intraday_low_time": intraday.get("intraday_low_time"),
            "vwap": intraday.get("vwap"),
            "imoex_change_pct": index_intraday.get("change_pct"),
            "imoex_rebound_from_low_pct": idx_rebound,
            "imoex_low_time": index_intraday.get("intraday_low_time"),
        },
    )


def is_index_rebound_candidate(ticker: str, intraday: dict, index_intraday: dict) -> tuple[bool, str]:
    if not INDEX_REBOUND_RADAR_ENABLED:
        return False, "index_rebound_disabled"
    if ticker not in INDEX_REBOUND_TICKERS:
        return False, "index_rebound_ticker_not_allowed"
    if not intraday or not index_intraday:
        return False, "index_rebound_missing_intraday"
    idx_rebound = index_intraday.get("rebound_from_low_pct") or 0
    ticker_rebound = intraday.get("rebound_from_low_pct") or 0
    ticker_high_rebound = intraday.get("rebound_high_from_low_pct") or 0
    if idx_rebound < INDEX_REBOUND_MIN_INDEX_PCT:
        return False, "index_rebound_imoex_too_weak"
    if ticker_rebound < INDEX_REBOUND_MIN_TICKER_PCT:
        return False, "index_rebound_ticker_too_weak"
    if ticker_high_rebound < INDEX_REBOUND_MIN_TICKER_HIGH_PCT:
        return False, "index_rebound_high_too_weak"
    if intraday.get("vwap") and intraday.get("last") and intraday["last"] < intraday["vwap"]:
        return False, "index_rebound_below_vwap"
    return True, "index_rebound_candidate"


def build_index_rebound_signal(
    ticker: str,
    levels: dict,
    ctx: dict,
    intraday: dict,
    index_intraday: dict,
    anomaly: dict,
) -> dict | None:
    """Builds a sandbox-tradable LONG signal from a broad IMOEX rebound."""
    if not INDEX_REBOUND_SANDBOX_ORDER:
        return None
    ok, reject_reason = is_index_rebound_candidate(ticker, intraday, index_intraday)
    if not ok:
        append_opportunity_log({
            "ticker": ticker,
            "direction": "LONG",
            "action": "rejected",
            "reason": reject_reason,
            "decision_reasons": ["index_rebound_signal"],
        })
        return None
    rebound = intraday.get("rebound_from_low_pct") or 0
    idx_rebound = index_intraday.get("rebound_from_low_pct") or 0
    pseudo_anomaly = {
        **(anomaly or {}),
        "anomaly": True,
        "ratio": max(float((anomaly or {}).get("ratio") or 0), 1.5),
        "reason": "index_rebound",
    }
    h1_confirm = {
        "type": "index_rebound",
        "note": (
            f"IMOEX rebound {idx_rebound:.2f}% от лоя "
            f"{index_intraday.get('intraday_low_time', '?')}; "
            f"{ticker} rebound {rebound:.2f}% выше VWAP"
        ),
    }
    signal = build_market_signal(
        ticker, levels, pseudo_anomaly, ctx,
        intraday=intraday,
        h1_confirm=h1_confirm,
        direction_override="LONG",
        signal_type_override="momentum",
        signal_kind="INDEX_REBOUND",
    )
    if not signal:
        return None
    signal["strategy"] = "index_rebound"
    signal["volume_ratio"] = pseudo_anomaly["ratio"]
    signal["decision_reasons"] = sorted(set(signal.get("decision_reasons", []) + ["index_rebound_signal"]))
    signal["data_quality_flags"] = sorted(set(signal.get("data_quality_flags", [])))
    signal["index_rebound"] = {
        "ticker_rebound_from_low_pct": rebound,
        "ticker_rebound_high_from_low_pct": intraday.get("rebound_high_from_low_pct"),
        "ticker_low_time": intraday.get("intraday_low_time"),
        "imoex_rebound_from_low_pct": idx_rebound,
        "imoex_change_pct": index_intraday.get("change_pct"),
        "imoex_low_time": index_intraday.get("intraday_low_time"),
    }
    return signal


def log_new_signal(s: dict, signal_id: str) -> None:
    """
    Добавляет новый сигнал в trade_log.json.
    В auto-order режиме вызывается только после подтверждённого sandbox fill.
    Если сигнал с таким signal_id уже существует — не добавляет.
    """
    log = load_trade_log()
    # Дедупликация: проверяем, нет ли уже этого id
    if any(r["signal_id"] == signal_id for r in log):
        return
    record = {
        "signal_id":       signal_id,
        "signal_version":  s.get("signal_version", SIGNAL_SCHEMA_VERSION),
        "ticker":          s.get("ticker"),
        "direction":       s.get("direction"),
        "confidence":      s.get("confidence"),
        "score":           s.get("confidence_score"),       # v0.9.23: числовой скор
        "score_breakdown": s.get("score_breakdown", ""),    # v0.9.23: разбивка по модулям
        "entry":           s.get("entry"),
        "stop":            s.get("stop"),
        "stop_pct":        s.get("stop_pct"),
        "take1":           s.get("take1"),
        "take1_pct":       s.get("take1_pct"),
        "take2":           s.get("take2"),
        "take2_pct":       s.get("take2_pct"),
        "rr":              s.get("rr"),
        "volume_ratio":    s.get("volume_ratio"),
        "rsi":             s.get("rsi"),
        "adx":             s.get("adx"),
        "vwap_confirm":    s.get("vwap_confirm"),
        "ob_confirm":      s.get("orderbook_confirm"),
        "weekly_trend":    s.get("weekly_trend"),
        "weekly_change":   s.get("weekly_change"),
        "h1_type":         s.get("h1_confirm", {}).get("type") if s.get("h1_confirm") else None,
        "pattern":         s.get("pattern", ""),
        "date":            now_msk().strftime("%Y-%m-%d"),
        "time":            now_msk().strftime("%H:%M"),
        "decision_reasons": s.get("decision_reasons", []),
        "data_quality_flags": s.get("data_quality_flags", []),
        "news_mode":       s.get("news_mode", "none"),
        "execution_status": "signaled",
        "result":          None,   # "win_t1","win_t2","loss","be" — заполнится позже
        "exit_price":      None,
        "exit_time":       None,
        "pnl_pct":         None,
        "notes":           "",
    }
    log.append(record)
    save_trade_log(log)


def build_signal_state_record(s: dict, now_iso: str | None = None) -> dict:
    """Base signal state. Auto-order writes it only after confirmed execution."""
    now_iso = now_iso or datetime.now(timezone.utc).isoformat()
    return {
        "ticker":     s["ticker"],
        "direction":  s["direction"],
        "entry":          s["entry"],
        "stop":           s["stop"],
        "take1":          s.get("take1"),
        "take2":          s.get("take2"),
        "trend_target":   s.get("trend_target"),
        "breakeven_stop": s.get("breakeven_stop"),
        "h1_atr":         s.get("h1_atr"),
        "volume_ratio":   s.get("volume_ratio"),
        "confidence":     s.get("confidence"),
        "confidence_score": s.get("confidence_score"),
        "sizing_source":  s.get("sizing_source"),
        "session_label":  s.get("session_label"),
        "rr":             s.get("rr"),
        "first_seen":     now_iso,
        "last_sent":      now_iso,
        "sent_count":     1,
        **_signal_meta(s),
    }


def update_trade_execution_status(
    signal_id: str,
    execution_status: str,
    *,
    state: dict | None = None,
    sb_order_id: str | None = None,
    note: str = "",
) -> None:
    """Канонический execution-truth marker для trade_log."""
    log = load_trade_log()
    updated = False
    for r in log:
        if r.get("signal_id") != signal_id:
            continue
        r["execution_status"] = execution_status
        if sb_order_id:
            r["sb_order_id"] = sb_order_id
        if note:
            prev = r.get("notes") or ""
            if note not in prev:
                r["notes"] = (prev + " " + note).strip()
        updated = True
        break
    if updated:
        save_trade_log(log)


def update_trade_result(signal_id: str, result: str, exit_price: float | None = None,
                        state: dict | None = None) -> None:
    """
    Обновляет результат сделки в trade_log.json.
    result: "win_t1" | "win_t2" | "loss" | "be" | "open"

    v0.9.36: добавлено поле `executed` (True/False) — отличает реально
    размещённые sandbox-ордера от «виртуальных» сигналов (risk-block, 50002,
    нет equity и т.д.). Агрегирующие отчёты должны фильтровать по executed=True
    для честной статистики. Legacy-записи без поля считаются executed=True.
    """
    log = load_trade_log()

    # Определяем, был ли реально размещён sb_-ордер. Состояние либо передано
    # из вызывающего кода (быстрее), либо читаем файл (fallback).
    if state is None:
        try:
            state = load_signals_state()
        except Exception:
            state = {}
    sb_entry = state.get(f"sb_{signal_id}") if isinstance(state, dict) else None
    # Фолбэк для _v2/_v3 — sb_-ордер может быть на базовом ключе без суффикса.
    if not sb_entry:
        import re as _re
        base_key = _re.sub(r"_v\d+$", "", signal_id)
        if base_key != signal_id:
            sb_entry = state.get(f"sb_{base_key}") if isinstance(state, dict) else None
    close_reason = (sb_entry.get("close_reason") or "") if isinstance(sb_entry, dict) else ""
    executed = bool(
        isinstance(sb_entry, dict)
        and sb_entry.get("order_id")
        and not close_reason.startswith("reconcile")
    )

    updated = False
    for r in log:
        if r["signal_id"] == signal_id:
            r["result"]     = result
            r["exit_price"] = exit_price
            r["exit_time"]  = now_msk().strftime("%Y-%m-%d %H:%M")
            r["executed"]   = executed  # v0.9.36
            if executed:
                r["execution_status"] = "closed"
            if isinstance(sb_entry, dict) and sb_entry.get("order_id"):
                r["sb_order_id"] = sb_entry.get("order_id")
            if exit_price and r.get("entry"):
                entry = r["entry"]
                mult  = 1 if r.get("direction") == "LONG" else -1
                r["pnl_pct"] = round(mult * (exit_price - entry) / entry * 100, 2)
            if executed and _repair_anomalous_close_price(r, state if isinstance(state, dict) else {}):
                logger.warning(
                    "[trade_log] repaired anomalous close price for %s: raw=%s fixed=%s",
                    signal_id, r.get("exit_price_raw"), r.get("exit_price"),
                )
                if isinstance(state, dict):
                    save_signals_state(state)
            if not executed:
                prev_notes = r.get("notes") or ""
                marker = "[NOT_EXECUTED: risk-block/50002/no-order]"
                if marker not in prev_notes:
                    r["notes"] = (prev_notes + " " + marker).strip()
                r["execution_status"] = "virtual"
                logger.info(
                    "[trade_log] %s %s %s pnl=%s%% — VIRTUAL (no sb_ order)",
                    r.get("ticker"), r.get("direction"), result,
                    f"{r.get('pnl_pct'):+.2f}" if r.get("pnl_pct") is not None else "?",
                )
            updated = True
            break
    if updated:
        save_trade_log(log)


def export_trade_csv(path: str | None = None) -> str:
    """
    Экспортирует trade_log.json в CSV.
    Возвращает путь к файлу.
    """
    import csv
    log = load_trade_log()
    if not log:
        return ""
    if path is None:
        path = TRADE_LOG_FILE.replace(".json", ".csv")
    fields = [
        "signal_id", "date", "time", "ticker", "direction", "confidence",
        "entry", "stop", "stop_pct", "take1", "take1_pct", "take2", "take2_pct",
        "trend_target", "rr", "volume_ratio", "rsi", "vwap_confirm", "ob_confirm",
        "result", "exit_price", "exit_time", "pnl_pct", "notes",
    ]
    with open(path, "w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=fields, extrasaction="ignore")
        w.writeheader()
        w.writerows(log)
    return path


def print_trade_log_summary() -> None:
    """
    v0.9.7: расширенный отчёт --report / --trade-log.
    Показывает: общую статистику, разбивку по тикерам,
    profit factor и упрощённый Sharpe (avg/std P&L).
    """
    import math

    log     = load_trade_log()
    total   = len(log)
    if total == 0:
        print("📋 Трейд-лог пуст. Сигналы появятся после первого --watch скана.")
        return

    closed  = [r for r in log if r.get("result") and r["result"] != "open"]
    wins    = [r for r in closed if r["result"] in ("win_t1", "win_t2")]
    win_t1  = [r for r in closed if r["result"] == "win_t1"]
    win_t2  = [r for r in closed if r["result"] == "win_t2"]
    losses  = [r for r in closed if r["result"] == "loss"]
    bes     = [r for r in closed if r["result"] == "be"]
    opens   = [r for r in log if not r.get("result") or r["result"] == "open"]

    wr        = round(len(wins) / len(closed) * 100, 1) if closed else 0
    pnl_lst   = [r["pnl_pct"] for r in closed if r.get("pnl_pct") is not None]
    avg_pnl   = round(sum(pnl_lst) / len(pnl_lst), 2) if pnl_lst else 0
    total_pnl = round(sum(pnl_lst), 2) if pnl_lst else 0

    # Profit Factor = сумма выигрышей / |сумма проигрышей|
    gross_win  = sum(p for p in pnl_lst if p > 0)
    gross_loss = abs(sum(p for p in pnl_lst if p < 0))
    pf = round(gross_win / gross_loss, 2) if gross_loss > 0 else float("inf")

    # Упрощённый Sharpe: avg(P&L) / std(P&L)
    sharpe = 0.0
    if len(pnl_lst) >= 2:
        mean_p = sum(pnl_lst) / len(pnl_lst)
        std_p  = math.sqrt(sum((x - mean_p) ** 2 for x in pnl_lst) / len(pnl_lst))
        sharpe = round(mean_p / std_p, 2) if std_p > 0 else 0.0

    # Лучшая и худшая сделка
    best_trade  = max(pnl_lst) if pnl_lst else 0
    worst_trade = min(pnl_lst) if pnl_lst else 0

    # Серия побед/поражений
    max_wins_streak = max_loss_streak = cur_w = cur_l = 0
    for r in closed:
        if r.get("result") in ("win_t1", "win_t2"):
            cur_w += 1; cur_l = 0
        elif r.get("result") == "loss":
            cur_l += 1; cur_w = 0
        max_wins_streak = max(max_wins_streak, cur_w)
        max_loss_streak = max(max_loss_streak, cur_l)

    sep = "═" * 48
    print(f"\n╔{sep}╗")
    print(f"  📊 ОТЧЁТ ПО СИГНАЛАМ  ({total} всего)")
    print(f"╠{sep}╣")
    print(f"  Закрытых сделок : {len(closed)}"
          f"  (открытых: {len(opens)})")
    print(f"  ✅ Тейк 1        : {len(win_t1)}")
    print(f"  ✅ Тейк 2        : {len(win_t2)}")
    print(f"  ❌ Стоп          : {len(losses)}")
    print(f"  ↩️  Безубыток     : {len(bes)}")
    print(f"╠{sep}╣")
    print(f"  Винрейт          : {wr}%")
    print(f"  Средний P/L      : {avg_pnl:+.2f}%")
    print(f"  Итого P/L        : {total_pnl:+.2f}%")
    print(f"  Profit Factor    : {pf}")
    print(f"  Sharpe (упрощ.)  : {sharpe}")
    print(f"  Лучшая сделка   : {best_trade:+.2f}%")
    print(f"  Худшая сделка   : {worst_trade:+.2f}%")
    print(f"  Макс. серия ✅   : {max_wins_streak}")
    print(f"  Макс. серия ❌   : {max_loss_streak}")

    # ── По тикерам ────────────────────────────────────────────────────────────
    if closed:
        from collections import defaultdict
        ticker_stats: dict = defaultdict(lambda: {"wins": 0, "losses": 0, "bes": 0, "pnl": []})
        for r in closed:
            t = r.get("ticker", "?")
            if r["result"] in ("win_t1", "win_t2"):
                ticker_stats[t]["wins"] += 1
            elif r["result"] == "loss":
                ticker_stats[t]["losses"] += 1
            else:
                ticker_stats[t]["bes"] += 1
            if r.get("pnl_pct") is not None:
                ticker_stats[t]["pnl"].append(r["pnl_pct"])

        print(f"╠{sep}╣")
        print(f"  ПО ТИКЕРАМ:")
        print(f"  {'Тикер':<7} {'Сделок':>7} {'WR%':>6} {'P/L%':>7}")
        print(f"  {'─'*7} {'─'*7} {'─'*6} {'─'*7}")
        for t, st in sorted(ticker_stats.items(),
                             key=lambda x: sum(x[1]["pnl"]), reverse=True):
            n   = st["wins"] + st["losses"] + st["bes"]
            wr_t = round(st["wins"] / n * 100) if n else 0
            p   = round(sum(st["pnl"]), 2) if st["pnl"] else 0
            bar = "✅" * st["wins"] + "❌" * st["losses"]
            print(f"  {t:<7} {n:>7}  {wr_t:>5}%  {p:>+7.2f}%  {bar}")

    print(f"╚{sep}╝\n")


# ══════════════════════════════════════════════════════════════════════════════
#  H1 WATCH-ЛИСТ (v0.9.3) — двухфазный вход
#  Фаза 1: дневная аномалия объёма → зона интереса → тикер в watch-лист
#  Фаза 2: при следующем скане проверяем H1 → если подтверждение есть → сигнал
# ══════════════════════════════════════════════════════════════════════════════

def load_h1_watch() -> dict:
    """Загружает watch-лист тикеров, ожидающих H1-подтверждения."""
    data = load_json_file(H1_WATCH_FILE, {}, "load_h1_watch")
    return data if isinstance(data, dict) else {}


def save_h1_watch(watch: dict) -> None:
    save_json_file_atomic(H1_WATCH_FILE, watch, "save_h1_watch")


def add_to_h1_watch(watch: dict, ticker: str, direction: str,
                    levels: dict, anomaly: dict,
                    state: dict | None = None) -> None:
    """Добавляет тикер в watch-лист для последующей проверки H1-подтверждения.

    v0.9.36: guard — если по (ticker, direction) уже открыта sb_-позиция,
    запись не создаётся (AFKS 16.04 добавлялся 11 раз подряд после открытия).
    """
    key = f"{ticker}_{direction}"

    # v0.9.36: не добавляем, если уже есть активная sb_-позиция
    if isinstance(state, dict):
        for sk, sv in state.items():
            if not (isinstance(sv, dict) and sk.startswith("sb_")):
                continue
            if (sv.get("ticker") == ticker
                    and sv.get("direction") == direction
                    and not sv.get("closed_at")):
                logger.debug(
                    "h1_watch skip: %s %s — уже есть открытая sb_-позиция (%s)",
                    ticker, direction, sk,
                )
                # Дополнительно: если запись в watch была — удалим (гигиена)
                if key in watch:
                    del watch[key]
                return

    # v0.9.36: не добавляем повторно, если запись уже есть и ещё не протухла
    if key in watch:
        try:
            exp = datetime.fromisoformat(watch[key].get("expires_at", ""))
            if datetime.now(timezone.utc) < exp:
                logger.debug("h1_watch skip: %s %s — уже в watch-листе", ticker, direction)
                return
        except (ValueError, TypeError):
            pass

    now_utc = datetime.now(timezone.utc)
    watch[key] = {
        "ticker":    ticker,
        "direction": direction,
        "added_at":  now_utc.isoformat(),
        "expires_at": (now_utc + timedelta(hours=H1_WATCH_HOURS)).isoformat(),
        "volume_ratio": anomaly.get("ratio"),
        "levels_snapshot": {
            "last_close": levels.get("last_close"),
            "support":    levels.get("support"),
            "resistance": levels.get("resistance"),
            "atr":        levels.get("atr"),
            "ma50":       levels.get("ma50"),
        },
    }


def expire_h1_watch(watch: dict) -> list[str]:
    """Удаляет просроченные записи. Возвращает список удалённых ключей."""
    now = datetime.now(timezone.utc)
    expired = []
    for key, entry in list(watch.items()):
        try:
            exp = datetime.fromisoformat(entry["expires_at"])
            if now > exp:
                expired.append(key)
        except (KeyError, ValueError):
            expired.append(key)
    for key in expired:
        del watch[key]
    return expired


def check_h1_confirmation(direction: str, d1_levels: dict,
                           h1_candles: list[dict]) -> dict | None:
    """
    Проверяет наличие H1-подтверждения для входа в позицию.

    Три типа подтверждения (v0.9.7):
    1. "breakout"  — H1-свеча закрылась за дневным уровнем (пробой структуры)
    2. "momentum"  — направленная H1-свеча:
                     тело ≥ 40% диапазона (было 50%), закрытие в верхней/нижней половине
    3. "volume"    — объём последней H1-свечи значительно выше среднего H1-объёма (×1.5)
                     при правильном направлении цены (бычья/медвежья)

    Снижение порога тела 50%→40% позволяет захватывать реальные импульсы
    в условиях нормальной волатильности MOEX.

    Возвращает dict {"type": str, "h1_close": float, "note": str}
    или None если подтверждения нет.
    """
    if not h1_candles or len(h1_candles) < 2:
        logger.debug("check_h1_confirmation: недостаточно свечей (%d)", len(h1_candles) if h1_candles else 0)
        return None

    last     = h1_candles[-1]
    h1_close = last.get("close")
    h1_open  = last.get("open")
    h1_high  = last.get("high")
    h1_low   = last.get("low")
    h1_vol   = last.get("value") or 0.0

    if not all([h1_close, h1_open, h1_high, h1_low]):
        logger.debug("check_h1_confirmation: нет OHLC данных в последней свече")
        return None

    h1_range = h1_high - h1_low
    h1_body  = abs(h1_close - h1_open)
    body_pct = h1_body / h1_range if h1_range > 0 else 0
    mid_h1   = (h1_high + h1_low) / 2

    support    = d1_levels.get("support")
    resistance = d1_levels.get("resistance")

    # Средний объём H1 (для объёмного подтверждения)
    h1_vols = [c.get("value") or 0.0 for c in h1_candles[:-1] if c.get("value")]
    avg_h1_vol = sum(h1_vols) / len(h1_vols) if h1_vols else 0.0

    if direction == "LONG":
        # 1. Пробой: H1 закрылась выше дневного сопротивления
        if resistance and h1_close > resistance:
            return {
                "type":     "breakout",
                "h1_close": h1_close,
                "note":     f"H1 пробой D1-сопр. {resistance} → close {h1_close}",
            }
        # 2. Импульс: бычья H1, тело ≥ 55%, закрытие выше середины
        # v0.9.18: было 40% — слишком низкий порог, контр-трендовые отскоки 40-54% проходили.
        # Настоящий импульс имеет тело 55%+. NVTK 52% 25/03 и 49% 26/03 больше не пройдут.
        if h1_close > h1_open and body_pct >= 0.55 and h1_close > mid_h1:
            return {
                "type":     "momentum",
                "h1_close": h1_close,
                "note":     f"H1 бычий импульс: тело {body_pct:.0%}, close {h1_close}",
            }
        # 3. Объёмный: бычья свеча + объём ×1.5 от среднего H1
        if (h1_close > h1_open and avg_h1_vol > 0
                and h1_vol >= avg_h1_vol * 1.5):
            vol_ratio = round(h1_vol / avg_h1_vol, 1)
            return {
                "type":     "volume",
                "h1_close": h1_close,
                "note":     f"H1 объёмный импульс ×{vol_ratio} avg, бычья свеча",
            }
        logger.debug("check_h1_confirmation LONG нет: body=%.0f%% (нужно≥40%%) bull=%s vol_ratio=%.1f",
                     body_pct * 100, h1_close > h1_open,
                     h1_vol / avg_h1_vol if avg_h1_vol > 0 else 0)
    else:  # SHORT
        # 1. Пробой: H1 закрылась ниже дневной поддержки
        if support and h1_close < support:
            return {
                "type":     "breakout",
                "h1_close": h1_close,
                "note":     f"H1 пробой D1-подд. {support} → close {h1_close}",
            }
        # 2. Импульс: медвежья H1, тело ≥ 55%, закрытие ниже середины
        # v0.9.18: порог поднят с 40% до 55% (симметрично с LONG)
        if h1_close < h1_open and body_pct >= 0.55 and h1_close < mid_h1:
            return {
                "type":     "momentum",
                "h1_close": h1_close,
                "note":     f"H1 медвежий импульс: тело {body_pct:.0%}, close {h1_close}",
            }
        # 3. Объёмный: медвежья свеча + объём ×1.5 от среднего H1
        if (h1_close < h1_open and avg_h1_vol > 0
                and h1_vol >= avg_h1_vol * 1.5):
            vol_ratio = round(h1_vol / avg_h1_vol, 1)
            return {
                "type":     "volume",
                "h1_close": h1_close,
                "note":     f"H1 объёмный импульс ×{vol_ratio} avg, медвежья свеча",
            }
        logger.debug("check_h1_confirmation SHORT нет: body=%.0f%% (нужно≥40%%) bear=%s vol_ratio=%.1f",
                     body_pct * 100, h1_close < h1_open,
                     h1_vol / avg_h1_vol if avg_h1_vol > 0 else 0)

    return None


# ─── Состояние сигналов (чтобы не спамить) ────────────────────────────────

# ══════════════════════════════════════════════════════════════════════════════
#  NEWS MEMORY (v0.9.19) — накопитель новостного сентимента
#  "Buy the rumor": отслеживаем тренд новостного фона, заходим до движения.
# ══════════════════════════════════════════════════════════════════════════════

NEWS_MEMORY_FILE = os.path.join(
    os.path.dirname(os.path.abspath(__file__)), "news_memory.json"
)
NEWS_MEMORY_DAYS = 7   # сколько дней храним историю
NEWS_TREND_MIN_DAYS = 2  # сколько дней подряд нужно для признания тренда


def load_news_memory() -> dict:
    """Загружает news_memory.json. Формат: {ticker: {date: {score, count}}}"""
    data = load_json_file(NEWS_MEMORY_FILE, {}, "load_news_memory")
    return data if isinstance(data, dict) else {}


def save_news_memory(memory: dict) -> None:
    save_json_file_atomic(NEWS_MEMORY_FILE, memory, "save_news_memory")


def update_news_memory(news_signals: list, memory: dict) -> dict:
    """
    Обновляет memory на основе свежих новостных сигналов.
    Каждый день усредняем все score по тикеру.
    Удаляем записи старше NEWS_MEMORY_DAYS.
    """
    today = now_msk().strftime("%Y-%m-%d")
    cutoff = (now_msk() - timedelta(days=NEWS_MEMORY_DAYS)).strftime("%Y-%m-%d")

    for n in news_signals:
        # score: +1 для LONG, -1 для SHORT, умножаем на strength
        raw_score = n.strength if n.direction == "LONG" else -n.strength
        for ticker in n.tickers:
            if ticker not in memory:
                memory[ticker] = {}
            day_rec = memory[ticker].get(today, {"score": 0.0, "count": 0})
            # скользящее среднее за день
            n_prev = day_rec["count"]
            day_rec["score"] = (day_rec["score"] * n_prev + raw_score) / (n_prev + 1)
            day_rec["count"] = n_prev + 1
            memory[ticker][today] = day_rec

    # Удаляем устаревшее
    for ticker in list(memory.keys()):
        memory[ticker] = {
            d: v for d, v in memory[ticker].items() if d >= cutoff
        }
        if not memory[ticker]:
            del memory[ticker]

    return memory


def get_news_trend(ticker: str, memory: dict) -> tuple[str, int]:
    """
    Возвращает (тренд, дней_подряд).
    тренд: "improving" (score растёт), "worsening" (score падает), "neutral".
    дней_подряд: сколько последовательных дней тренд держится.

    Алгоритм: смотрим последние NEWS_MEMORY_DAYS дат в хронологическом порядке.
    Если каждый следующий день score выше предыдущего — "improving".
    Если каждый следующий день score ниже — "worsening".
    """
    ticker_data = memory.get(ticker)
    if not ticker_data or len(ticker_data) < 2:
        return "neutral", 0

    # Сортируем по дате, берём последние 7 дней
    sorted_dates = sorted(ticker_data.keys())[-NEWS_MEMORY_DAYS:]
    scores = [ticker_data[d]["score"] for d in sorted_dates]

    improving_streak = 0
    worsening_streak = 0
    for i in range(len(scores) - 1, 0, -1):
        if scores[i] > scores[i - 1]:
            if worsening_streak > 0:
                break
            improving_streak += 1
        elif scores[i] < scores[i - 1]:
            if improving_streak > 0:
                break
            worsening_streak += 1
        else:
            break

    if improving_streak >= NEWS_TREND_MIN_DAYS:
        return "improving", improving_streak
    if worsening_streak >= NEWS_TREND_MIN_DAYS:
        return "worsening", worsening_streak
    return "neutral", 0


# ══════════════════════════════════════════════════════════════════════════════
#  EVENT CALENDAR — конфигурационный слой, загружается из event_calendar.json
# ══════════════════════════════════════════════════════════════════════════════

EVENT_CALENDAR: list[dict] = _load_event_calendar()


def get_upcoming_event(ticker: str, hours_ahead: int = 48) -> dict | None:
    """
    Возвращает ближайшее событие для тикера в горизонте hours_ahead часов.
    None если событий нет.
    """
    now = now_msk()
    deadline = now + timedelta(hours=hours_ahead)
    for evt in EVENT_CALENDAR:
        try:
            evt_dt = datetime.strptime(evt["date"], "%Y-%m-%d")
        except ValueError:
            continue
        if now.date() <= evt_dt.date() <= deadline.date():
            if ticker in evt.get("tickers", []):
                days_to = (evt_dt.date() - now.date()).days
                return {**evt, "days_to": days_to}
    return None


def load_signals_state() -> dict:
    data = load_json_file(SIGNALS_STATE_FILE, {}, "load_signals_state")
    return data if isinstance(data, dict) else {}


def save_signals_state(state: dict):
    save_json_file_atomic(SIGNALS_STATE_FILE, state, "save_signals_state")


def signal_key(s: dict) -> str:
    """
    Уникальный ключ сигнала: тикер + направление + торговый день.

    ВАЖНО: Цена намеренно исключена.
    При скане каждые 5 мин цена меняется на несколько пунктов →
    ключи 'PHOR_SHORT_7193', 'PHOR_SHORT_7202', 'PHOR_SHORT_7218' получались
    разными → бот посылал 3 "новых" сигнала и размещал 3 sandbox-ордера вместо 1.

    Политика: один сигнал на тикер+направление в торговый день.
    При повышении уверенности СРЕДНЯЯ→ВЫСОКАЯ — отправляем upgrade (но не новый ордер).
    """
    today = now_msk().strftime("%Y-%m-%d")
    return f"{s['ticker']}_{s['direction']}_{today}"


def should_send_tg(s: dict, state: dict) -> tuple[bool, str]:
    """
    Решаем, отправлять ли сигнал в Telegram.
    Возвращает (отправить: bool, причина: str).
    Причины: "new", "upgrade", "repeat", "" (не отправлять).

    v0.9.10: если базовый ключ занят ЗАКРЫТОЙ позицией (hit != None) —
    генерируем уникальный ключ _v2, _v3, … и сохраняем в s["_state_key"].
    Это предотвращает перезапись данных закрытой сделки новым сигналом.
    """
    base_key = signal_key(s)
    now = datetime.now(timezone.utc)

    # v0.9.28: SHORT_ENTRY_CUTOFF_HOUR=0 (отключён по умолчанию).
    # Экономическую фильтрацию SHORT выполняет short_margin_guard в build_signal():
    # блокирует позицию если margin_cost_max > profit_per_share * 0.8.
    # Временно́й cutoff срабатывает только если явно задан через .env (например, =18).
    msk_hour  = (now + timedelta(hours=3)).hour
    direction = s.get("direction", "LONG")
    _cutoff   = SHORT_ENTRY_CUTOFF_HOUR if direction == "SHORT" else LONG_ENTRY_CUTOFF_HOUR
    if _cutoff > 0 and base_key not in state:
        if msk_hour >= _cutoff:
            logger.debug(
                "entry_cutoff: %s %s заблокирован (%d МСК ≥ %d)",
                s.get("ticker"), direction, msk_hour, _cutoff,
            )
            return False, "session_cutoff"

    # v0.9.10: если базовый ключ занят закрытым сигналом — ищем свободный суффикс
    key = base_key
    if key in state and state[key].get("hit") is not None:
        suffix = 2
        while True:
            candidate = f"{base_key}_v{suffix}"
            if candidate not in state:
                key = candidate
                break
            # Если кандидат занят и тоже закрыт — продолжаем
            if state[candidate].get("hit") is not None:
                suffix += 1
            else:
                # Кандидат занят открытой позицией — дубль, пропускаем
                # v0.9.38.3: явный reason для score_log (было "")
                logger.info(
                    "duplicate_guard: %s %s уже открыт (%s) — пропускаем",
                    s.get("ticker"), s.get("direction"), candidate,
                )
                return False, "duplicate_signal"
        s["_state_key"] = key   # сохраняем уникальный ключ в сигнал

    if key not in state:
        # v0.9.8: guard против дублей — не открываем новую позицию если уже есть
        # активный сигнал по этому тикеру+направлению с предыдущего дня
        ticker    = s.get("ticker")
        direction = s.get("direction")
        for skey, sval in state.items():
            if skey.startswith(("news_", "sb_")):
                continue
            # v0.9.9: позиция "открыта" когда hit=None.
            # После take1: hit сбрасывается в None (фаза trailing).
            # После take2/stop: hit="target2"|"stop_hit" → позиция закрыта.
            if (sval.get("ticker") == ticker
                    and sval.get("direction") == direction
                    and sval.get("hit") is None):
                # v0.9.38.3: явный reason для score_log
                logger.info(
                    "duplicate_guard: %s %s уже открыт (%s) — пропускаем",
                    ticker, direction, skey,
                )
                return False, "duplicate_signal"
        return True, "new"

    # v0.9.19: убрали repeat/upgrade — в Telegram шлём только ВХОД и ЗАКРЫТИЕ.
    # Повторные сигналы засоряли чат и не несли новой информации.
    # v0.9.38.3: явный reason "repeat_after_exit" (позиция по этому ключу закрыта,
    # повторный сигнал — не открываем заново)
    return False, "repeat_after_exit"


def check_stop_target_hits(synthesized: list[dict], state: dict, intraday: dict) -> list[tuple[dict, str]]:
    """
    Проверяем стоп/тейк по активным сигналам.

    v0.9.7: трейлинг-стоп после взятия Тейк1.
      После hit=target1 состояние переходит в фазу "trailing":
        — стоп переносится в безубыток (entry)
        — при каждом скане трейлинг поднимается за ценой: trail = price − 0.5×h1_atr
        — если цена откатилась ниже trail (LONG) / выше trail (SHORT) — фиксируем target2 early
      Если h1_atr недоступен — трейлинг = безубыток (стандартное поведение).
    """
    alerts = []
    now    = datetime.now(timezone.utc)

    for key, prev in list(state.items()):
        # Пропускаем служебные записи: новости и sandbox-ордера (нет take1/take2)
        if key.startswith(("news_", "sb_")):
            continue

        ticker    = prev.get("ticker")
        direction = prev.get("direction")
        entry     = prev.get("entry")
        stop      = prev.get("stop")
        take1     = prev.get("take1")
        take2     = prev.get("take2")
        h1_atr    = prev.get("h1_atr")   # может быть None

        if not all([ticker, direction, entry, stop]):
            continue

        # v0.9.10: проверяем hit ДО обработки trailing-фазы.
        # Без этого закрытая позиция (hit="target2") повторно срабатывала каждый скан,
        # пока цена оставалась выше take2 (порождало дублирующий Telegram-сигнал с 400 ошибкой).
        if prev.get("hit"):
            continue

        data = intraday.get(ticker)
        if not data:
            continue
        price = data.get("last")
        if not price:
            continue

        # Восстанавливаем сигнал-словарь из state
        s = {k: prev[k] for k in prev if k in (
            "ticker", "direction", "entry", "stop",
            "take1", "take2", "trend_target", "rr_ratio",
            "volume_ratio", "rsi", "ma20", "confidence", "h1_atr",
            "confidence_score", "sizing_source", "session_label", "rr",
        )}
        s.setdefault("rr", s.pop("rr_ratio", "?"))
        s["_state_key"] = key   # v0.9.9: сохраняем оригинальный ключ state для update_trade_result

        # ── Фаза трейлинга (после взятия тейк1) ──────────────────────────────
        if prev.get("phase") == "trailing":
            trail_stop = float(prev.get("trail_stop", entry))
            hit = None

            if direction == "LONG":
                # Обновляем трейл вверх
                # v0.9.9: fallback если h1_atr=None — используем 0.5% от цены
                trail_atr = h1_atr if h1_atr else round(price * 0.005, 2)
                new_trail = round(price - 0.5 * trail_atr, 2)
                if new_trail > trail_stop:
                    trail_stop = new_trail
                    state[key]["trail_stop"] = trail_stop
                    logger.info("trailing: %s %s — trail_stop=%.2f (atr=%s%s)",
                                ticker, direction, trail_stop, trail_atr,
                                "" if h1_atr else " fallback0.5%")
                # Проверяем тейк2 и трейлинг-стоп
                if take2 and price >= float(take2):
                    hit = "target2"
                elif price <= trail_stop:
                    hit = "target2"   # трейлинг сработал — частичная прибыль
            else:  # SHORT
                # v0.9.9: fallback если h1_atr=None — используем 0.5% от цены
                trail_atr = h1_atr if h1_atr else round(price * 0.005, 2)
                new_trail = round(price + 0.5 * trail_atr, 2)
                if new_trail < trail_stop:
                    trail_stop = new_trail
                    state[key]["trail_stop"] = trail_stop
                if take2 and price <= float(take2):
                    hit = "target2"
                elif price >= trail_stop:
                    hit = "target2"

            if hit:
                s["current_price"] = price
                s["stop"] = trail_stop   # показываем актуальный стоп в Telegram
                alerts.append((s, hit))
                state[key]["hit"]    = hit
                state[key]["hit_at"] = now.isoformat()
            continue   # в trailing-фазе не проверяем обычные уровни

        hit = None
        if direction == "LONG":
            if price <= float(stop):
                hit = "stop_hit"
            elif take2 and price >= float(take2):
                hit = "target2"
            elif take1 and price >= float(take1):
                hit = "target1"
        else:  # SHORT
            if price >= float(stop):
                hit = "stop_hit"
            elif take2 and price <= float(take2):
                hit = "target2"
            elif take1 and price <= float(take1):
                hit = "target1"

        if hit:
            s["current_price"] = price
            alerts.append((s, hit))
            state[key]["hit"]    = hit
            state[key]["hit_at"] = now.isoformat()

            # v0.9.7: после тейк1 переходим в trailing-фазу
            if hit == "target1":
                be_stop = float(entry)   # безубыток
                # Если есть h1_atr — ставим трейл уже с первой позиции
                if h1_atr:
                    be_stop = max(be_stop, round(price - 0.5 * h1_atr, 2)) \
                              if direction == "LONG" \
                              else min(be_stop, round(price + 0.5 * h1_atr, 2))
                state[key]["phase"]      = "trailing"
                state[key]["trail_stop"] = be_stop
                state[key]["hit"]        = None   # сбрасываем — позиция ещё открыта
                logger.info("trailing: %s %s — trail_stop=%.2f", ticker, direction, be_stop)

    return alerts


# ─── v0.9.34: Portfolio reconciliation ──────────────────────────────────────

# Тикеры денежных позиций (кэш) — их исключаем из сравнения с sb_-ключами
_CASH_TICKERS = {"RUB000UTSTOM", "RUB000", "USD000UTSTOM", "EUR000UTSTOM"}


def _find_open_signal_candidates(state: dict, ticker: str, direction: str) -> list[str]:
    """Открытые базовые сигналы того же тикера/направления без финального закрытия."""
    result: list[str] = []
    for key, val in state.items():
        if not isinstance(val, dict):
            continue
        if key.startswith(("sb_", "news_", "ntg_")):
            continue
        if val.get("ticker") != ticker or val.get("direction") != direction:
            continue
        if val.get("hit") in ("target2", "stop_hit"):
            continue
        result.append(key)
    return sorted(result)

def reconcile_sandbox_state(state: dict) -> None:
    """
    v0.9.34: Синхронизирует signals_state.json с реальным портфелем T-Invest.

    Два класса несоответствий:
      Ghost  — sb_KEY в state без closed_at, но позиции этого тикера НЕТ в портфеле.
               → Помечаем как закрытую (reason='reconcile_ghost'), текущую цену берём
                 из last-price API. Бот не будет держать «мёртвую» позицию в риск-лимите.

      Orphan — позиция ЕСТЬ в портфеле, но нет соответствующего sb_KEY в state.
               → Создаём минимальную запись-заглушку (reason='reconcile_orphan'),
                 чтобы бот видел позицию и мог управлять ею (трейлинг, закрытие).

    Вызывается из run_once() перед sandbox_execute_signals().
    """
    if not SANDBOX_AUTO_ORDER or not _tinvest_available():
        return

    try:
        portfolio = _tinvest.get_sandbox_portfolio()   # type: ignore[union-attr]
    except Exception as _e:
        logger.warning("reconcile: не удалось получить портфель: %s", _e)
        return
    if not portfolio:
        return

    def _close_unlinked_orphan(orphan_key: str, orphan_val: dict) -> bool:
        if SANDBOX_ORPHAN_POLICY != "close":
            return False
        if orphan_val.get("base_signal_key") or orphan_val.get("closed_at"):
            return False
        if str(orphan_val.get("execution_status") or "") not in {"orphan", "linked_orphan", ""}:
            return False
        ticker = orphan_val.get("ticker")
        if not ticker:
            return False
        try:
            close_result = _tinvest.sandbox_close_position(ticker)  # type: ignore[union-attr]
        except Exception as exc:
            logger.warning("reconcile_orphan auto-close %s: %s", ticker, exc)
            append_decision_log({
                "action": "rejected",
                "reason": "reconcile_orphan_close_failed",
                "ticker": ticker,
                "state_key": orphan_key,
                "error": str(exc),
            })
            return False
        if not close_result:
            logger.warning("reconcile_orphan auto-close %s вернул None", ticker)
            append_decision_log({
                "action": "rejected",
                "reason": "reconcile_orphan_close_rejected",
                "ticker": ticker,
                "state_key": orphan_key,
            })
            return False
        orphan_val["closed_at"] = datetime.now(timezone.utc).isoformat()
        orphan_val["close_reason"] = "reconcile_orphan_auto_close"
        orphan_val["close_price"] = close_result.get("price")
        orphan_val["execution_status"] = "orphan_closed"
        orphan_val["close_order_id"] = close_result.get("order_id")
        append_decision_log({
            "action": "closed",
            "reason": "reconcile_orphan_auto_close",
            "ticker": ticker,
            "direction": orphan_val.get("direction"),
            "state_key": orphan_key,
            "order_id": close_result.get("order_id"),
        })
        logger.warning("reconcile_orphan auto-closed %s (%s)", ticker, orphan_key)
        return True

    # Словарь {ticker: position_dict} для реальных позиций (без кэша)
    real_positions: dict[str, dict] = {}
    for pos in portfolio.get("positions", []):
        t   = pos.get("ticker", "")
        qty = pos.get("quantity", 0)
        if t and t not in _CASH_TICKERS and qty != 0:
            real_positions[t] = pos

    real_tickers = set(real_positions.keys())

    # ── 1. Ghost-позиции: в state есть, в портфеле нет ──────────────────────
    changed = False
    for key, val in list(state.items()):
        if not key.startswith("sb_"):
            continue
        if val.get("closed_at"):
            continue  # уже закрыта
        ticker = val.get("ticker", "")
        if ticker and ticker not in real_tickers:
            # Попытаемся взять текущую цену
            try:
                price_data = _tinvest.get_last_price(ticker)   # type: ignore[union-attr]
                ghost_price = price_data.get("price") if price_data else None
            except Exception:
                ghost_price = None

            state[key]["closed_at"]    = datetime.now(timezone.utc).isoformat()
            state[key]["close_reason"] = "reconcile_ghost"
            state[key]["execution_status"] = "ghost_closed"
            if ghost_price:
                state[key]["close_price"] = ghost_price
            changed = True
            base_signal_key = val.get("base_signal_key") or (key[3:] if key.startswith("sb_") else None)
            if base_signal_key:
                update_trade_execution_status(
                    base_signal_key,
                    "ghost_closed",
                    note="[RECONCILE_GHOST]",
                )
            msg = (f"🔄 [reconcile] Ghost-позиция {key} ({ticker}) — "
                   f"нет в портфеле → закрываем в state (ghost)")
            print(msg)
            logger.info(msg)
            if TELEGRAM_TOKEN and TELEGRAM_CHAT_ID:
                tg_send(f"⚠️ *Reconcile*: позиция `{ticker}` не найдена в портфеле — "
                        f"помечена как закрытая (ghost). Проверьте вручную.")

    # ── 2. Orphan-позиции: в портфеле есть, в state нет ────────────────────
    # Собираем тикеры из state (открытые)
    tracked_tickers: set[str] = set()
    for key, val in state.items():
        if key.startswith("sb_") and not val.get("closed_at"):
            tracked_tickers.add(val.get("ticker", ""))

    for ticker, pos in real_positions.items():
        if ticker in tracked_tickers:
            for key, val in state.items():
                if (
                    key.startswith("sb_")
                    and not val.get("closed_at")
                    and val.get("ticker") == ticker
                    and not val.get("order_id")
                ):
                    qty = pos.get("quantity", 0)
                    val["direction"] = "LONG" if qty > 0 else "SHORT"
                    val["lots"] = int(abs(qty))
                    val["entry"] = pos.get("avg_price", val.get("entry", 0))
                    val["price"] = pos.get("curr_price", val.get("price", 0))
                    val["execution_status"] = val.get("reconcile_status", "orphan")
                    val["reconcile_seen_at"] = datetime.now(timezone.utc).isoformat()
                    _close_unlinked_orphan(key, val)
                    changed = True
            continue
        qty = pos.get("quantity", 0)
        direction = "LONG" if qty > 0 else "SHORT"
        candidates = _find_open_signal_candidates(state, ticker, direction)
        linked_signal_key = candidates[0] if len(candidates) == 1 else None
        orphan_key = f"sb_{linked_signal_key}" if linked_signal_key else f"sb_{ticker}_orphan"
        if orphan_key not in state:
            state[orphan_key] = {
                "ticker":     ticker,
                "direction":  direction,
                "entry":      pos.get("avg_price", 0),
                "stop":       0,
                "price":      pos.get("curr_price", 0),
                "lots":       int(abs(qty)),
                "opened_at":  datetime.now(timezone.utc).isoformat(),
                "note":       (
                    f"reconcile_orphan — связана с {linked_signal_key}"
                    if linked_signal_key else
                    "reconcile_orphan — позиция без записи в state"
                ),
                "reconcile_status": "linked_orphan" if linked_signal_key else "orphan",
                "execution_status": "linked_orphan" if linked_signal_key else "orphan",
                "base_signal_key": linked_signal_key,
                "reconcile_seen_at": datetime.now(timezone.utc).isoformat(),
            }
            changed = True
            if linked_signal_key:
                update_trade_execution_status(
                    linked_signal_key,
                    "linked_orphan",
                    note="[RECONCILE_LINKED_ORPHAN]",
                )
            msg = (
                f"🔄 [reconcile] Orphan-позиция {ticker} ({direction} ×{abs(qty):.0f}) — "
                f"{'связана с ' + linked_signal_key if linked_signal_key else 'нет в state → создана запись-заглушка'}"
            )
            print(msg)
            logger.info(msg)
            append_decision_log({
                "action": "reconciled",
                "reason": "reconcile_orphan",
                "ticker": ticker,
                "direction": direction,
                "state_key": orphan_key,
                "base_signal_key": linked_signal_key,
            })
            if TELEGRAM_TOKEN and TELEGRAM_CHAT_ID:
                tg_send(f"⚠️ *Reconcile*: найдена неизвестная позиция `{ticker}` "
                        f"({direction} ×{abs(qty):.0f}) — добавлена в state как orphan.")
            if not linked_signal_key:
                _close_unlinked_orphan(orphan_key, state[orphan_key])

    if changed:
        save_signals_state(state)


# ─── v0.9.36: helpers для risk-block dedup, cooldown, daily loss brake ──────

def _should_log_risk_block(ticker: str, reason_code: str) -> bool:
    """
    Возвращает True, если WARNING по (ticker, reason) не логировался
    последние _RISK_BLOCK_DEDUP_MIN минут. Параллельно считает подавленные.
    """
    key = (ticker, reason_code)
    now = datetime.now(timezone.utc)
    prev = _RISK_BLOCK_SEEN.get(key)
    if prev and (now - prev[0]) < timedelta(minutes=_RISK_BLOCK_DEDUP_MIN):
        _RISK_BLOCK_SEEN[key] = (prev[0], prev[1] + 1)
        return False
    _RISK_BLOCK_SEEN[key] = (now, 0)
    return True


def risk_block_summary() -> str:
    """Короткий текст для EOD: сколько дубликатов подавили за день."""
    lines = []
    for (ticker, reason), (_, supp) in _RISK_BLOCK_SEEN.items():
        if supp > 0:
            lines.append(f"  {ticker} {reason}: +{supp} suppressed")
    return "\n".join(lines) if lines else ""


def _is_in_cooldown(state: dict, ticker: str, direction: str,
                    now_utc: datetime | None = None) -> tuple[bool, str]:
    """
    Кулдаун после target2/stop_hit того же тикера в том же направлении.
    Возвращает (in_cooldown: bool, reason: str).
    """
    if now_utc is None:
        now_utc = datetime.now(timezone.utc)
    for k, v in state.items():
        if not isinstance(v, dict) or k.startswith("sb_"):
            continue
        if v.get("ticker") != ticker or v.get("direction") != direction:
            continue
        hit = v.get("hit")
        if hit not in ("target2", "stop_hit"):
            continue
        hit_at_str = v.get("hit_at") or v.get("closed_at") or ""
        if not hit_at_str:
            continue
        try:
            hit_at = datetime.fromisoformat(str(hit_at_str).replace("Z", "+00:00"))
            if hit_at.tzinfo is None:
                hit_at = hit_at.replace(tzinfo=timezone.utc)
        except (ValueError, TypeError):
            continue
        delta_min = (now_utc - hit_at).total_seconds() / 60
        threshold = (COOLDOWN_AFTER_T2_MIN if hit == "target2"
                     else COOLDOWN_AFTER_STOP_MIN)
        if 0 <= delta_min < threshold:
            remaining = int(threshold - delta_min)
            return True, f"{ticker} {direction} в кулдауне ({remaining}мин) после {hit}"
    return False, ""


def check_daily_loss_brake(sod_equity: float | None, current_equity: float) -> bool:
    """
    True — если нужно блокировать новые входы до конца дня.
    sod_equity=None (не зафиксирован) или <=0 → не блокируем.
    """
    if not sod_equity or sod_equity <= 0:
        return False
    drawdown_pct = (sod_equity - current_equity) / sod_equity * 100
    return drawdown_pct >= MAX_DAILY_LOSS_PCT


def sandbox_strategy_reject_reason(
    signal: dict,
    quality_flags: set[str] | None = None,
    decision_reasons: set[str] | None = None,
) -> str | None:
    """Extra sandbox quality gates for non-core experimental strategies."""
    strategy = signal.get("strategy")
    quality_flags = quality_flags or set(signal.get("data_quality_flags", []))
    decision_reasons = decision_reasons or set(signal.get("decision_reasons", []))
    score = signal.get("confidence_score") or 0

    if strategy == "index_rebound":
        if score < 9:
            return "index_rebound_min_score"
        if "stale_intraday" in quality_flags:
            return "stale_intraday"
        if signal.get("vwap_confirm") is not True:
            return "index_rebound_vwap_required"
        if "ma50_against" in decision_reasons:
            return "index_rebound_trend_conflict"
    elif strategy == "news_event":
        if "stale_intraday" in quality_flags:
            return "stale_intraday"
        if signal.get("vwap_confirm") is False and score < 12:
            return "news_event_vwap_conflict"
    return None


# ═══════════════════════════════════════════════════════════════════════════════
#  v0.9.37 — reconcile trade_log ↔ sandbox.portfolio
# ═══════════════════════════════════════════════════════════════════════════════
_RECONCILE_LAST: dict[str, datetime] = {}        # "_run": last_check_utc
RECONCILE_INTERVAL_MIN = int(os.environ.get("RECONCILE_INTERVAL_MIN", "30"))
_RECONCILE_MISMATCH_SEEN: dict[str, datetime] = {}


def reconcile_trade_log_with_sandbox(
    state: dict,
    portfolio: dict | None,
    force: bool = False,
) -> list[str]:
    """
    Сверяет trade_log.json (closed_today) с фактическим sandbox-портфелем.

    Кейс 17.04.2026: SBER_LONG_2026-04-16 помечен `result=win_t1, executed=True`
    в trade_log, но реально в sandbox позиция ещё открыта (31 лот). Бот
    виртуально зафиксировал take1 без реального sell-ордера.

    Функция только ЛОГИРУЕТ расхождения (не «чинит» автоматически, чтобы
    не закрывать реальные позиции случайно). Возвращает список сообщений
    для EOD-отчёта / ручного анализа. Дальнейший шаг (auto-sell или
    result=None) — в v0.9.38 после сбора данных.

    Rate-limited: выполняется не чаще RECONCILE_INTERVAL_MIN (default 30 мин).
    """
    now = datetime.now(timezone.utc)
    last = _RECONCILE_LAST.get("_run")
    if not force and last and (now - last).total_seconds() < RECONCILE_INTERVAL_MIN * 60:
        return []

    if not portfolio:
        return []

    open_tickers: set[str] = set()
    for pos in (portfolio.get("positions") or []):
        t = pos.get("ticker")
        q = pos.get("quantity", 0) or 0
        if t and q and t not in _CASH_TICKERS:
            open_tickers.add(t)

    # Грузим trade_log
    try:
        if not os.path.exists(TRADE_LOG_FILE):
            _RECONCILE_LAST["_run"] = now
            return []
        with open(TRADE_LOG_FILE, "r", encoding="utf-8") as _f:
            all_trades = __import__("json").load(_f)
    except Exception as e:
        logger.warning("reconcile: не удалось прочитать trade_log: %s", e)
        return []

    today = now.astimezone(timezone(timedelta(hours=3))).strftime("%Y-%m-%d")
    mismatches: list[str] = []

    for t in all_trades:
        if not isinstance(t, dict):
            continue
        if not t.get("executed", True):
            continue
        if not t.get("result"):
            continue
        # exit_time / close_time "YYYY-MM-DD ..."
        et = str(t.get("exit_time") or t.get("close_time") or "")
        if not et.startswith(today):
            continue
        ticker = t.get("ticker")
        if ticker and ticker in open_tickers:
            sid = t.get("signal_id", "?")
            mismatches.append(
                f"{sid}: trade_log={t.get('result')} @ {t.get('exit_price')}, "
                f"но в sandbox позиция открыта"
            )

    if mismatches:
        for m in mismatches:
            prev = _RECONCILE_MISMATCH_SEEN.get(m)
            if not prev or (now - prev).total_seconds() >= RECONCILE_INTERVAL_MIN * 60:
                logger.warning("[RECONCILE] %s", m)
                _RECONCILE_MISMATCH_SEEN[m] = now
        print(f"  ⚠️ RECONCILE: найдено {len(mismatches)} расхождений trade_log ↔ sandbox")

    _RECONCILE_LAST["_run"] = now
    return mismatches


def sandbox_execute_signals(synthesized: list[dict], state: dict) -> int:
    """
    Размещает бумажные ордера в T-Invest Sandbox для ВЫСОКОЙ и СРЕДНЕЙ уверенности.

    v0.9.10 — Equity-based sizing: размер позиции рассчитывается по РЕАЛЬНОМУ
    балансу sandbox-счёта, а не по статическому DEPOSIT_RUB.

    Формула:
        риск_руб = equity × RISK_PCT / 100
        лоты     = риск_руб / (|entry − stop| × лотность)

    Пример: equity=800 000 ₽, риск 1%, стоп PHOR 25 руб, лотность=1
        → риск = 8 000 ₽ → лоты = 8 000 / 25 = 320 лотов

    SANDBOX_ORDER_LOTS используется как fallback если equity недоступен.
    СРЕДНЯЯ уверенность → риск ограничен 0.5% (вдвое меньше).

    Пропускаем сигналы, по которым уже открыта позиция.
    Возвращает количество исполненных ордеров.
    """
    if not SANDBOX_AUTO_ORDER:
        return 0
    if not _tinvest_available():
        return 0

    # v0.9.13: новые sandbox-ордера только в торговые дни (Пн–Пт).
    # Мониторинг стопов/тейков продолжается круглосуточно, но входить в позицию
    # по рыночным ценам выходного дня бессмысленно (MOEX закрыт).
    _now_msk = datetime.now(timezone.utc) + timedelta(hours=3)
    if _now_msk.weekday() >= 5:  # 5=Сб, 6=Вс
        logger.info("sandbox_execute_signals: выходной день (%s) — новые ордера пропущены", _now_msk.strftime("%A"))
        print(f"  📅 Выходной ({_now_msk.strftime('%A %d.%m')}) — sandbox-ордера не размещаем")
        return 0

    # ── Получаем реальный баланс портфеля (equity) ────────────────────────────
    equity: float = 0.0
    _portfolio_snapshot: dict | None = None
    try:
        _portfolio_snapshot = _tinvest.get_sandbox_portfolio()  # type: ignore[union-attr]
        if _portfolio_snapshot and _portfolio_snapshot.get("total_amount_rub", 0) > 0:
            equity = _portfolio_snapshot["total_amount_rub"]
            logger.debug("sandbox equity: %.0f ₽", equity)
    except Exception as _e:
        logger.warning("sandbox equity fetch failed: %s", _e)

    # ── v0.9.37: reconcile trade_log ↔ sandbox.portfolio (rate-limited) ──────
    try:
        reconcile_trade_log_with_sandbox(state, _portfolio_snapshot)
    except Exception as _re_exc:
        logger.warning("reconcile: %s", _re_exc)

    # ── v0.9.36: Daily loss brake (circuit breaker на день) ──────────────────
    # Если внутри дня -MAX_DAILY_LOSS_PCT к SOD equity — блокируем новые входы.
    try:
        _sod = float(_equity_day_start) if _equity_day_start else None
    except (NameError, TypeError, ValueError):
        _sod = None
    if check_daily_loss_brake(_sod, equity):
        if _should_log_risk_block("ALL", "DAILY_LOSS_BRAKE"):
            dd = (_sod - equity) / _sod * 100 if _sod else 0
            msg = (f"🛑 Daily loss brake активен: drawdown {dd:.2f}% "
                   f"≥ {MAX_DAILY_LOSS_PCT}% — новые входы заблокированы")
            print(f"  {msg}")
            logger.warning("daily_loss_brake: %s", msg)
        return 0

    # v0.9.20: в понедельник риск вдвое — статистика 2 недель: 31% vs 53% winrate
    _is_monday = (datetime.now(timezone.utc) + timedelta(hours=3)).weekday() == 0  # МСК, не UTC
    _day_risk_mult = MONDAY_RISK_MULT if _is_monday else 1.0
    if _is_monday and MONDAY_RISK_MULT < 1.0:
        logger.info("monday_risk: риск снижен до %.0f%% (MONDAY_RISK_MULT=%.1f)",
                    RISK_PCT * _day_risk_mult, MONDAY_RISK_MULT)

    # v0.9.31: таблица размера позиции по уверенности.
    # risk_mult — масштаб риск-рубля (RISK_PCT × mult).
    # pos_pct   — лимит одной позиции (% equity), НЕЗАВИСИМО от SANDBOX_MAX_POS_PCT.
    # Итог: ОТЛИЧНАЯ торгуется в 1.5× по сравнению с ВЫСОКАЯ, СРЕДНЯЯ — в 0.5×.
    # До v0.9.31: ОТЛИЧНАЯ падала в else→continue (баг), сейчас исправлено.
    _CONF_PARAMS: dict[str, dict] = {
        "ОТЛИЧНАЯ": {"risk_mult": 1.5, "pos_pct": 15.0},  # score≥12 → 15% equity
        "ВЫСОКАЯ":  {"risk_mult": 1.0, "pos_pct": 10.0},  # score≥9  → 10% equity
        "СРЕДНЯЯ":  {"risk_mult": 0.5, "pos_pct":  5.0},  # score≥6  → 5% equity
    }

    placed = 0
    for s in synthesized:
        confidence = s.get("confidence", "")
        # Определяем параметры по ключевому слову в строке уверенности
        _cp = None
        for _key, _params in _CONF_PARAMS.items():
            if _key in confidence:
                _cp = _params
                break
        if _cp is None:
            continue  # 🔴 СЛАБАЯ — пропускаем

        risk_multiplier = _cp["risk_mult"] * _day_risk_mult
        _conf_pos_pct   = _cp["pos_pct"]  # лимит позиции для этого уровня уверенности

        key = signal_key(s)
        sb_key = f"sb_{key}"
        if sb_key in state:
            continue

        ticker    = s["ticker"]
        direction = s["direction"]
        entry     = float(s.get("entry") or 0)
        stop      = float(s.get("stop")  or 0)
        quality_flags = set(s.get("data_quality_flags", []))
        decision_reasons = set(s.get("decision_reasons", []))
        tier = s.get("ticker_tier") or ticker_tier(ticker)
        s["ticker_tier"] = tier
        opportunity_base = {
            "ticker": ticker,
            "direction": direction,
            "score": s.get("confidence_score"),
            "confidence": confidence,
            "signal_id": key,
            "ticker_tier": tier,
            "news_mode": s.get("news_mode"),
            "decision_reasons": list(decision_reasons),
            "data_quality_flags": list(quality_flags),
        }

        if tier == "tier_3":
            reason = "tier3_watch_only"
            append_score_log({**opportunity_base, "action": "watch_only", "reason": reason})
            append_opportunity_log({**opportunity_base, "action": "watch_only", "reason": reason})
            continue
        if tier == "tier_2":
            if (s.get("confidence_score") or 0) < TIER2_MIN_SCORE:
                reason = "tier2_min_score"
                append_score_log({**opportunity_base, "action": "rejected", "reason": reason})
                append_opportunity_log({**opportunity_base, "action": "rejected", "reason": reason})
                continue
            if "stale_intraday" in quality_flags or "intraday_confirmation_conflict" in decision_reasons:
                reason = "tier2_data_quality"
                append_score_log({**opportunity_base, "action": "rejected", "reason": reason})
                append_opportunity_log({**opportunity_base, "action": "rejected", "reason": reason})
                continue
            risk_multiplier *= 0.75

        strategy_reject_reason = sandbox_strategy_reject_reason(s, quality_flags, decision_reasons)
        if strategy_reject_reason:
            append_score_log({**opportunity_base, "action": "skipped", "reason": strategy_reject_reason})
            append_opportunity_log({**opportunity_base, "action": "rejected", "reason": strategy_reject_reason})
            continue

        if "invalid_price" in quality_flags:
            append_score_log({**opportunity_base, "action": "skipped", "reason": "invalid_price"})
            append_opportunity_log({**opportunity_base, "action": "rejected", "reason": "invalid_price"})
            continue
        if "stale_intraday" in quality_flags and (s.get("confidence_score") or 0) < 10:
            append_score_log({**opportunity_base, "action": "skipped", "reason": "stale_intraday"})
            append_opportunity_log({**opportunity_base, "action": "rejected", "reason": "stale_intraday"})
            continue
        if "intraday_confirmation_conflict" in decision_reasons and (s.get("confidence_score") or 0) < 9:
            append_score_log({**opportunity_base, "action": "skipped", "reason": "quality_gate_conflict"})
            append_opportunity_log({**opportunity_base, "action": "rejected", "reason": "quality_gate_conflict"})
            continue

        # v0.9.36: Sandbox runtime-blacklist (50002 в прошлом запросе).
        try:
            from tinvest_data import is_sandbox_available as _sb_avail  # type: ignore
        except Exception:
            _sb_avail = None
        if _sb_avail and not _sb_avail(ticker):
            append_score_log({**opportunity_base, "action": "skipped", "reason": "sandbox_unavailable"})
            append_opportunity_log({**opportunity_base, "action": "rejected", "reason": "sandbox_unavailable"})
            if _should_log_risk_block(ticker, "SANDBOX_UNAVAILABLE"):
                logger.info("sandbox-blacklist skip: %s (ещё в 24ч blacklist)", ticker)
            continue

        # v0.9.36: Cooldown после target2/stop_hit того же направления.
        # Кейс 16.04: CBOM target2 → 27 мин → вход по той же цене → stop_hit.
        in_cd, cd_reason = _is_in_cooldown(state, ticker, direction)
        if in_cd:
            if _should_log_risk_block(ticker, f"COOLDOWN_{direction}"):
                print(f"  ⏸ Cooldown: {cd_reason}")
                logger.info("cooldown-skip: %s", cd_reason)
            continue

        # v0.9.14: Фильтр позднего входа — физики уже разогнали цену, соотношение изменилось.
        # Сравниваем цену сигнала (entry) с текущей рыночной ценой из _current_intraday.
        # Актуально для repeat-сигналов: был сгенерирован час назад, цена ушла.
        if LATE_ENTRY_MAX_PCT > 0 and entry > 0:
            curr_px = _current_intraday.get(ticker, {}).get("last")
            if curr_px and abs(curr_px - entry) / entry * 100 > LATE_ENTRY_MAX_PCT:
                drift_pct = (curr_px - entry) / entry * 100
                msg = (f"⏭ Поздний вход [{ticker}]: цена {curr_px} ушла от сигнала {entry} "
                       f"на {drift_pct:+.1f}% > лимит {LATE_ENTRY_MAX_PCT:.1f}% — ордер пропущен")
                print(f"  {msg}")
                logger.info("late_entry_filter: %s", msg)
                continue

        # ── Рассчитываем лоты по equity ───────────────────────────────────────
        from tinvest_data import LOT_SIZE, get_lot_size  # type: ignore[import]
        lot_size  = get_lot_size(ticker)
        stop_dist = abs(entry - stop)

        if equity > 0 and stop_dist > 0 and entry > 0:
            risk_rub = equity * RISK_PCT / 100 * risk_multiplier
            lots_by_risk = max(1, int(risk_rub / (stop_dist * lot_size)))

            # v0.9.31: лимит позиции масштабируется по уверенности (_conf_pos_pct),
            # а не по фиксированному SANDBOX_MAX_POS_PCT.
            # ОТЛИЧНАЯ=15%, ВЫСОКАЯ=10%, СРЕДНЯЯ=5% — итоговый cap выше для лучших сигналов.
            # SANDBOX_MAX_POS_PCT из .env теперь служит только глобальным «потолком» (safety).
            conf_pos_pct     = min(_conf_pos_pct, SANDBOX_MAX_POS_PCT * 2)  # не больше 2×глобального
            max_position_rub = equity * conf_pos_pct / 100
            lots_by_pos  = max(1, int(max_position_rub / (entry * lot_size)))
            lots = min(lots_by_risk, lots_by_pos)

            sizing_note = (
                f"equity={equity:,.0f}₽ × {RISK_PCT * risk_multiplier:.1f}% "
                f"÷ стоп{stop_dist:.2f}×{lot_size}л = {lots_by_risk}л "
                f"→ лимит позиции {conf_pos_pct:.0f}% ({confidence.split()[-1]}) = {lots_by_pos}л "
                f"→ итого {lots}л"
            )
            logger.info("sandbox sizing %s: %s", ticker, sizing_note)
        else:
            # Fallback: фиксированное число лотов, масштабируется по уверенности
            lots = max(1, int(SANDBOX_ORDER_LOTS * _cp["risk_mult"]))
            sizing_note = f"fallback {lots}л (equity или stop_dist недоступны)"
            logger.info("sandbox sizing %s: %s", ticker, sizing_note)

        # ── v0.9.11: три независимых риск-проверки ────────────────────────────
        # Проверка 1: суммарная концентрация в тикере (все открытые sb_ по тикеру)
        if equity > 0:
            ticker_deployed = 0.0
            for sk, sv in state.items():
                if not sk.startswith("sb_"):
                    continue
                if sv.get("ticker") != ticker:
                    continue
                # Считаем только позиции у которых нет hit в основном сигнале
                # v0.9.12: также проверяем флаг closed_at (прямое подтверждение закрытия)
                if sv.get("closed_at"):
                    continue  # позиция закрыта (подтверждено через closed_at)
                base_key = sk[3:]  # убираем "sb_"
                base_hit = state.get(base_key, {}).get("hit")
                if base_hit in ("target2", "stop_hit"):
                    continue  # позиция закрыта (сигнал достиг стопа/тейка)
                sb_lots  = sv.get("lots", 1)
                sb_entry = float(sv.get("entry") or sv.get("price") or 0)
                sb_lot_size = get_lot_size(sv.get("ticker", ticker))
                ticker_deployed += sb_lots * sb_lot_size * sb_entry

            new_ticker_total = ticker_deployed + lots * lot_size * entry
            ticker_pct = new_ticker_total / equity * 100
            if ticker_pct > SANDBOX_MAX_TICKER_PCT:
                msg = (
                    f"⛔ Риск-блок [{ticker}]: концентрация {ticker_pct:.1f}% "
                    f"> лимит {SANDBOX_MAX_TICKER_PCT:.0f}% от equity. "
                    f"Уже открыто: {ticker_deployed:,.0f}₽"
                )
                # v0.9.36: dedup — один WARNING на пару (ticker, reason) в 30 мин.
                if _should_log_risk_block(ticker, "TICKER_PCT"):
                    print(f"  {msg}")
                    logger.warning("sandbox risk-block TICKER_PCT: %s", msg)
                continue  # v0.9.19: блок риска — не засоряем Telegram

            # Проверка 2: суммарный развёрнутый капитал (все открытые позиции)
            total_deployed = 0.0
            for sk, sv in state.items():
                if not sk.startswith("sb_"):
                    continue
                # v0.9.12: closed_at = прямое подтверждение закрытия
                if sv.get("closed_at"):
                    continue
                base_key = sk[3:]
                base_hit = state.get(base_key, {}).get("hit")
                if base_hit in ("target2", "stop_hit"):
                    continue
                sb_lots     = sv.get("lots", 1)
                sb_entry    = float(sv.get("entry") or sv.get("price") or 0)
                sb_lot_size = get_lot_size(sv.get("ticker", ""))
                total_deployed += sb_lots * sb_lot_size * sb_entry

            new_total = total_deployed + lots * lot_size * entry
            total_pct = new_total / equity * 100
            if total_pct > SANDBOX_MAX_TOTAL_PCT:
                msg = (
                    f"⛔ Риск-блок [{ticker}]: суммарный капитал {total_pct:.1f}% "
                    f"> лимит {SANDBOX_MAX_TOTAL_PCT:.0f}% от equity. "
                    f"Уже открыто: {total_deployed:,.0f}₽"
                )
                # v0.9.36: dedup — один WARNING на пару (ticker, reason) в 30 мин.
                if _should_log_risk_block(ticker, "TOTAL_PCT"):
                    print(f"  {msg}")
                    logger.warning("sandbox risk-block TOTAL_PCT: %s", msg)
                continue  # v0.9.19: блок риска — не засоряем Telegram

        result = _tinvest.sandbox_place_order(  # type: ignore[union-attr]
            ticker=ticker,
            direction=direction,
            quantity=lots,
        )
        if result:
            # v0.9.12: T-Invest sandbox executed_order_price ненадёжен для рыночных ордеров
            # (может вернуть абсурдные значения, напр. TATN 3215₽ вместо 654₽).
            # Используем entry из сигнала как каноническую цену входа.
            base_key = s.get("_state_key") or key
            api_price  = result.get("price")
            safe_price = (
                api_price
                if api_price and entry > 0 and 0.5 < api_price / entry < 2.0
                else entry   # fallback — цена из сигнала
            )
            now_iso = datetime.now(timezone.utc).isoformat()
            if not isinstance(state.get(base_key), dict):
                state[base_key] = build_signal_state_record(s, now_iso)
            state[base_key]["execution_status"] = "filled"
            state[base_key]["sb_order_id"] = result.get("order_id")
            log_new_signal(s, base_key)
            state[sb_key] = {
                "ticker":       ticker,
                "direction":    direction,
                "entry":        s.get("entry"),
                "stop":         s.get("stop"),
                "take2":        s.get("take2"),
                "order_id":     result.get("order_id"),
                "price":        round(safe_price, 4) if safe_price else entry,
                "lots":         result.get("lots"),
                "equity_at_open": round(equity, 0) if equity else None,
                "opened_at":    now_iso,
                "base_signal_key": base_key,
                "execution_status": "filled",
                **_signal_meta(s),
            }
            update_trade_execution_status(
                base_key,
                "filled",
                sb_order_id=result.get("order_id"),
            )
            append_opportunity_log({
                **opportunity_base,
                "action": "executed",
                "reason": "sandbox_order_filled",
                "signal_id": base_key,
                "order_id": result.get("order_id"),
                "lots": result.get("lots"),
            })
            dir_emoji  = "🟢" if direction == "LONG" else "🔴"
            exec_price = safe_price or entry
            exec_lots  = result.get("lots", lots)
            risk_show  = round(equity * RISK_PCT / 100 * risk_multiplier, 0) if equity else "—"
            print(
                f"  📋 Sandbox [{dir_emoji}{direction}] {ticker} ×{exec_lots}л  "
                f"риск={risk_show}₽  → order_id={result.get('order_id')}"
            )
            if TELEGRAM_TOKEN and TELEGRAM_CHAT_ID:
                # v0.9.19: slim-формат ВХОД + текущий портфель
                tg_send(tg_format_open(s, exec_lots, equity, risk_show, state))
            placed += 1
        else:
            base_key = s.get("_state_key") or key
            if isinstance(state.get(base_key), dict):
                state[base_key]["execution_status"] = "rejected"
                state[base_key]["order_reject_reason"] = "sandbox_place_order_failed"
                state[base_key]["last_order_attempt_at"] = datetime.now(timezone.utc).isoformat()
            update_trade_execution_status(
                base_key,
                "rejected",
                note="sandbox_place_order_failed",
            )
            append_score_log({
                **opportunity_base,
                "action": "skipped",
                "reason": "sandbox_order_rejected",
                "signal_id": base_key,
            })
            append_opportunity_log({
                **opportunity_base,
                "action": "rejected",
                "reason": "sandbox_order_rejected",
                "signal_id": base_key,
            })

    return placed


def tg_notify_run(
    synthesized: list[dict],
    news_orphan: list[NewsItem],
    intraday_data: dict,
    ctx: dict,
):
    """
    Главная точка входа для Telegram-уведомлений.
    Вызывается из run_once() если установлены TELEGRAM_TOKEN и TELEGRAM_CHAT_ID.
    """
    if not TELEGRAM_TOKEN or not TELEGRAM_CHAT_ID:
        return

    state = load_signals_state()
    sent  = 0

    # 1. Проверяем стоп/тейк по ранее отправленным сигналам
    hits = check_stop_target_hits(synthesized, state, intraday_data)
    for s, reason in hits:
        text = tg_format_signal(s, reason=reason)
        if tg_send(text):
            print(f"  📲 Telegram [{reason.upper()}]: {s['ticker']}")
            # v0.9.1: обновляем результат в трейд-логе
            result_map = {
                "stop_hit": "loss",
                "target1":  "win_t1",
                "target2":  "win_t2",
            }
            if reason in result_map:
                # v0.9.9: используем оригинальный ключ state (_state_key), а не сегодняшний.
                # signal_key(s) генерирует СЕГОДНЯШНЮЮ дату, но сигнал мог быть от 3 дней назад.
                trade_key = s.get("_state_key") or signal_key(s)
                # v0.9.10: закрываем sandbox-позицию при стопе или тейке
                # Только финальные события: stop_hit и target2 (target1 → trailing, ещё открыта)
                # v0.9.12: после закрытия помечаем state[sb_key]["closed_at"] — чтобы
                # риск-гард не считал позицию открытой при следующем запуске бота.
                if reason in ("stop_hit", "target2") and SANDBOX_AUTO_ORDER and _tinvest_available():
                    sb_key = f"sb_{trade_key}"
                    # v0.9.16: _v2/_v3 сигналы не имеют своего sb_ ключа —
                    # sandbox позиция открыта под оригинальным ключом (без суффикса).
                    # Ищем: сначала точный ключ, затем без _v2/_v3/_v4.
                    if sb_key not in state:
                        import re as _re
                        base_key = _re.sub(r"_v\d+$", "", trade_key)
                        candidate = f"sb_{base_key}"
                        if candidate in state and not state[candidate].get("closed_at"):
                            sb_key = candidate
                    if sb_key in state and not state[sb_key].get("closed_at"):
                        ticker_close = s.get("ticker")
                        try:
                            close_result = _tinvest.sandbox_close_position(ticker_close)  # type: ignore[union-attr]
                            if close_result:
                                # Помечаем позицию как закрытую — предотвращаем двойное закрытие
                                state[sb_key]["closed_at"] = datetime.now(timezone.utc).isoformat()
                                state[sb_key]["close_reason"] = reason
                                state[sb_key]["close_price"] = close_result.get("price")
                                state[sb_key]["execution_status"] = "closed"
                                if close_result.get("price"):
                                    s["current_price"] = close_result["price"]
                                update_trade_result(
                                    trade_key,
                                    result_map[reason],
                                    s.get("current_price"),
                                    state,
                                )
                                save_signals_state(state)
                                print(f"  📋 Sandbox закрыта [{reason}]: {ticker_close}")
                                logger.info("sandbox closed %s (%s)", ticker_close, reason)
                                # v0.9.19: slim ЗАКРЫТИЕ + портфель (equity неизвестен здесь → 0)
                                tg_send(tg_format_close(s, reason, 0.0, state))
                            else:
                                if isinstance(state.get(trade_key), dict):
                                    state[trade_key]["hit"] = None
                                    state[trade_key]["close_pending_reason"] = reason
                                    state[trade_key]["last_close_attempt_at"] = datetime.now(timezone.utc).isoformat()
                                    save_signals_state(state)
                                append_score_log({
                                    "ticker": s.get("ticker"),
                                    "direction": s.get("direction"),
                                    "score": s.get("confidence_score"),
                                    "confidence": s.get("confidence"),
                                    "action": "rejected",
                                    "reason": "sandbox_close_rejected",
                                    "signal_id": trade_key,
                                })
                                logger.warning("sandbox_close_position(%s) вернул None", ticker_close)
                        except Exception as _e:
                            if isinstance(state.get(trade_key), dict):
                                state[trade_key]["hit"] = None
                                state[trade_key]["close_pending_reason"] = reason
                                state[trade_key]["last_close_attempt_at"] = datetime.now(timezone.utc).isoformat()
                                save_signals_state(state)
                            append_score_log({
                                "ticker": s.get("ticker"),
                                "direction": s.get("direction"),
                                "score": s.get("confidence_score"),
                                "confidence": s.get("confidence"),
                                "action": "rejected",
                                "reason": "sandbox_close_failed",
                                "signal_id": trade_key,
                            })
                            logger.warning("sandbox close %s: %s", ticker_close, _e)
                elif reason in ("stop_hit", "target2"):
                    update_trade_result(
                        trade_key,
                        result_map[reason],
                        s.get("current_price"),
                        state,
                    )
                else:
                    append_score_log({
                        "ticker": s.get("ticker"),
                        "direction": s.get("direction"),
                        "score": s.get("confidence_score"),
                        "confidence": s.get("confidence"),
                        "action": "observed",
                        "reason": "target1_observed",
                        "signal_id": trade_key,
                    })
            sent += 1

    # v0.9.8: Portfolio heat guard — считаем суммарный % риска открытых позиций
    open_risk_pct = 0.0
    heat_breakdown: list[str] = []
    for skey, sval in state.items():
        if skey.startswith(("news_", "sb_")):
            continue
        # v0.9.9: позиция закрыта когда hit="target2"|"stop_hit"
        if sval.get("hit") not in (None,):   # None = открыта (или take1 hit и trailing)
            continue
        entry = float(sval.get("entry") or 0)
        # v0.9.32: trail_stop может быть 0.0 (breakeven) — нельзя использовать `or`,
        # иначе 0.0 считается falsy и берётся старый стоп.
        _ts = sval.get("trail_stop")
        stop = float(_ts if _ts is not None else (sval.get("stop") or 0))
        if entry > 0 and stop > 0:
            risk = abs(entry - stop) / entry * 100
            open_risk_pct += risk
            heat_breakdown.append(f"{sval.get('ticker','?')}:{risk:.1f}%")
    too_hot = open_risk_pct >= PORTFOLIO_HEAT_MAX
    breakdown_str = "  ".join(heat_breakdown) if heat_breakdown else "—"
    if too_hot:
        logger.warning(
            "portfolio_heat: %.1f%% ≥ %.1f%% — новые сигналы заморожены [%s]",
            open_risk_pct, PORTFOLIO_HEAT_MAX, breakdown_str,
        )
        print(f"  🌡️  Portfolio heat {open_risk_pct:.1f}% ≥ {PORTFOLIO_HEAT_MAX:.0f}% — новые сигналы не отправляем")
        print(f"       ({breakdown_str})")
    else:
        logger.debug("portfolio_heat: %.1f%% < %.1f%% [%s]", open_risk_pct, PORTFOLIO_HEAT_MAX, breakdown_str)

    # 2. Новые и повторные сигналы
    # v0.9.13: в выходные не рассылаем новые входы (MOEX закрыт, исполнение невозможно).
    # Стоп/тейк-хиты (блок 1 выше) продолжают работать для мониторинга позиций.
    _now_msk_tg = datetime.now(timezone.utc) + timedelta(hours=3)
    _is_weekend = _now_msk_tg.weekday() >= 5
    if _is_weekend:
        print(f"  📅 Выходной ({_now_msk_tg.strftime('%A %d.%m')}) — новые Telegram-сигналы не отправляем")
        logger.info("tg_notify: выходной день — новые сигналы пропущены")

    for s in synthesized:
        # v0.9.23: логируем все сигналы — и торгуемые, и отклонённые
        _score_base = {
            "ticker":          s.get("ticker"),
            "direction":       s.get("direction"),
            "score":           s.get("confidence_score"),
            "confidence":      s.get("confidence"),
            "score_breakdown": s.get("score_breakdown", ""),
            "entry":           s.get("entry"),
            "rr":              s.get("rr"),
            "rsi":             s.get("rsi"),
            "volume_ratio":    s.get("volume_ratio"),
            "weekly_trend":    s.get("weekly_trend"),
            "weekly_change":   s.get("weekly_change"),
        }
        if too_hot or _is_weekend:
            _reason = "portfolio_heat" if too_hot else "session_closed"
            append_score_log({**_score_base, "action": "skipped", "reason": _reason})
            continue  # не открываем новые позиции при перегреве или в выходные
        if SANDBOX_AUTO_ORDER:
            # Auto mode: entry records are created by sandbox_execute_signals()
            # only after a confirmed broker response. Failed orders must not
            # become state/trade_log records or they turn into phantom trades.
            append_score_log({**_score_base, "action": "skipped", "reason": "auto_order_controls_entry"})
            continue
        do_send, reason = should_send_tg(s, state)
        if do_send:
            text = tg_format_signal(s, reason=reason)
            if tg_send(text):
                # v0.9.10: используем уникальный ключ, если should_send_tg его установил
                # (случай нескольких сигналов по одному тикеру+направлению за день)
                key = s.get("_state_key") or signal_key(s)
                append_score_log({**_score_base, "action": "traded",
                                  "reason": reason, "signal_id": key})
                now = datetime.now(timezone.utc).isoformat()
                prev_state = state.get(key, {}) if isinstance(state.get(key), dict) else {}
                state[key] = build_signal_state_record(s, now)
                state[key]["first_seen"] = prev_state.get("first_seen", now)
                state[key]["sent_count"] = prev_state.get("sent_count", 0) + 1
                label = {"new": "НОВЫЙ", "upgrade": "РОСТ УВЕРЕН.", "repeat": "ПОВТОР"}.get(reason, reason)
                print(f"  📲 Telegram [{label}]: {s['ticker']} {s['direction']}")
                # v0.9.1: логируем только новые сигналы (не upgrade/repeat)
                if reason == "new":
                    log_new_signal(s, key)
                sent += 1
        else:
            # v0.9.27: логируем реальную причину вместо общего "should_send_tg_false".
            # v0.9.38.3: теперь should_send_tg всегда возвращает явный reason
            # (duplicate_signal / repeat_after_exit / session_cutoff / "").
            # Пустая строка означает "скан одинаковой причины, не логируем" (оставляем ""
            # → превратим в unknown_empty чтобы было видно что это необычный случай).
            _skip_reason = reason if reason else "unknown_empty_reason"
            append_score_log({**_score_base, "action": "skipped", "reason": _skip_reason})
            # v0.9.27: TG-уведомление при сильном сигнале, заблокированном по времени (≥8 очков)
            if _skip_reason == "session_cutoff" and (_score_base.get("score") or 0) >= 8:
                _d_emoji = "🟢" if s.get("direction") == "LONG" else "🔴"
                _vol_str = f"×{s.get('volume_ratio', '?')}" if s.get("volume_ratio") else ""
                _blocked_tg = (
                    f"⏰ <b>СИЛЬНЫЙ СИГНАЛ — ВХОД ЗАБЛОКИРОВАН</b>\n"
                    f"{_d_emoji} <b>{s.get('ticker')} {s.get('direction')}</b>"
                    f"  score=<b>{_score_base.get('score', '?')}</b>  {_vol_str}\n"
                    f"⚠️ SHORT после {SHORT_ENTRY_CUTOFF_HOUR}:00 МСК не открываем (маржа overnight)\n"
                    f"📋 {s.get('score_breakdown', '')}"
                )
                tg_send(_blocked_tg)
                logger.info(
                    "entry_cutoff_tg_alert: %s %s score=%s — уведомление отправлено",
                    s.get("ticker"), s.get("direction"), _score_base.get("score"),
                )

    # 3. Новостные сигналы без рыночного подтверждения — v0.9.25: отправляем важные.
    # Критерии: strength >= 2 (уверенный сигнал), не выходной, не дубль (dedup по title-hash).
    # Дедупликация хранится в state под ключом "ntg_<hash>" с TTL 24 часа.
    if not _is_weekend and news_orphan:
        # Чистим старые ntg_* ключи (> 24 ч)
        _now_utc = datetime.now(timezone.utc)
        _stale_ntg = [
            k for k, v in state.items()
            if k.startswith("ntg_")
            and (
                _now_utc - datetime.fromisoformat(v["sent"]).replace(tzinfo=timezone.utc)
            ).total_seconds() > 86400
        ]
        for _sk in _stale_ntg:
            del state[_sk]

        for n in news_orphan:
            if n.direction == "NEUTRAL" or not n.tickers:
                continue
            # Порог: AI-сигналы от strength 2+, keyword — от 3 (AI точнее)
            _min_str = 2 if n.analyzed_by == "ai" else 3
            if n.strength < _min_str:
                append_decision_log({
                    "action": "skipped",
                    "reason": "news_only_low_confidence",
                    "ticker": ",".join(n.tickers[:4]),
                    "direction": n.direction,
                    "news_mode": n.analyzed_by or "keywords",
                    "strength": n.strength,
                })
                continue
            # Дедупликация
            _nk = "ntg_" + hashlib.md5(n.title.encode()).hexdigest()[:12]
            if _nk in state:
                continue
            text = tg_format_news_only(n)
            if tg_send(text):
                state[_nk] = {
                    "sent":      _now_utc.isoformat(),
                    "title":     n.title[:80],
                    "tickers":   n.tickers,
                    "direction": n.direction,
                    "signal_version": SIGNAL_SCHEMA_VERSION,
                    "news_mode": n.analyzed_by or "keywords",
                }
                sent += 1
                logger.info(
                    "tg_news_orphan: %s %s str=%d [%s]",
                    n.tickers, n.direction, n.strength, n.title[:50],
                )
                print(f"  📰 Telegram [НОВОСТЬ]: {', '.join(n.tickers[:4])} {n.direction} str={n.strength}")

    save_signals_state(state)
    if sent:
        print(f"  ✉️  Отправлено в Telegram: {sent} сообщений")
    else:
        print("  💬 Telegram: нечего нового отправлять")


# ══════════════════════════════════════════════════════════════════════════════

def run_once(news_only: bool = False):
    now = now_msk().strftime("%d.%m.%Y %H:%M:%S")
    logger.info("─── скан начат (%s) ───", now)
    print(f"\n{'═'*54}")
    print(f"  🤖 MOEX Signal Bot {BOT_VERSION}  |  {now}")
    ai_status = "✅ AI включён" if ANTHROPIC_API_KEY else "⚠️  AI выключен (нет ключа)"
    print(f"  {ai_status}")
    if _tinvest_available():
        sb_mode = "авто" if SANDBOX_AUTO_ORDER else "ручной"
        print(f"  📋 Sandbox: ✅ активен ({sb_mode}-режим, {SANDBOX_ORDER_LOTS} лот/сигнал)")
    elif _TINVEST_OK:
        print(f"  📋 Sandbox: ⏳ токен не задан (задай TINVEST_TOKEN в .env)")

    # Предупреждение если биржа закрыта
    if not is_moex_open():
        print("  ⚠️  Биржа сейчас закрыта — данные за последнюю сессию")

    # Рыночный контекст
    print("\n  Загружаем рыночный контекст...", end=" ", flush=True)
    ctx = get_market_context()
    print("✅")
    print_market_context(ctx)
    print(f"{'═'*54}")

    market_signals = []
    intraday_data  = {}   # заполняется по мере обнаружения аномалий (v0.9)
    global _current_intraday

    # ── Модуль 1 ─────────────────────────────────────────────────────────────
    if not news_only:
        # v0.9.3: загружаем watch-лист перед сканированием
        h1_watch = load_h1_watch()
        # v0.9.38.1 hotfix: state нужен для add_to_h1_watch guard (v0.9.36)
        # — ранее брался из scope sandbox_execute_signals и падал NameError в run_once.
        state = load_signals_state()
        expired_keys = expire_h1_watch(h1_watch)
        if expired_keys:
            print(f"  ⏰ Watch-лист: убрано {len(expired_keys)} истёкших записей")
            for _ek in expired_keys:
                logger.info("h1_watch: %s истёк — H1 так и не подтвердилось, убран", _ek)

        print(f"\n📊 СКАНИРОВАНИЕ РЫНКА ({len(TICKERS)} тикеров)\n")
        index_intraday = get_index_intraday_context()
        if index_intraday.get("rebound_from_low_pct", 0) >= INDEX_REBOUND_MIN_INDEX_PCT:
            logger.info(
                "IMOEX rebound radar active: rebound=%.2f%% change=%+.2f%% low_time=%s",
                index_intraday.get("rebound_from_low_pct", 0),
                index_intraday.get("change_pct", 0),
                index_intraday.get("intraday_low_time", "?"),
            )
        for ticker in TICKERS:
            print(f"  → {ticker}", end=" ", flush=True)
            # v0.9.2: 55 дней для MA50 (было 21, хватало только для MA20)
            candles = get_candles(ticker, days=55)
            if not candles:
                print("— нет данных")
                continue
            anomaly = detect_volume_anomaly(candles, ticker=ticker)
            levels  = calc_levels(candles)
            if anomaly.get("anomaly"):
                rsi_info = f"  RSI={levels.get('rsi', '?')}" if levels.get("rsi") else ""
                print(f"⚡ ×{anomaly['ratio']}{rsi_info}")
                vol_mln = round(anomaly.get("last_volume", 0) / 1_000_000, 1)
                logger.info("%s: объёмная аномалия ×%.1f  RSI=%s  vol=%.1fM₽",
                            ticker, anomaly.get("ratio", 0),
                            levels.get("rsi", "?"), vol_mln)
                # v0.9: получаем intraday сразу — для VWAP и уточнения entry-цены
                intraday = get_intraday_price(ticker)
                if intraday:
                    intraday_data[ticker] = intraday
                    _current_intraday[ticker] = intraday  # v0.9.14: для late_entry_filter
                    vwap_str = f"  VWAP={intraday['vwap']}" if intraday.get("vwap") else ""
                    print(f"       intraday: last={intraday.get('last')}  "
                          f"chg={intraday.get('change_pct'):+.1f}%{vwap_str}")

                # ── v0.9.4: направление через determine_direction() ──────────
                _price_chk  = (intraday.get("last") if intraday else None) or levels.get("last_close", 0)
                _levels_chk = {**levels, "last_close": _price_chk}
                _dir_chk, _sig_type = determine_direction(_price_chk, _levels_chk)
                _ma50_chk   = levels.get("ma50")
                # MA50_HARD_FILTER блокирует только mean_reversion-сигналы против тренда.
                # Momentum-сигналы уже идут ПО тренду — фильтр для них не нужен.
                if MA50_HARD_FILTER and _ma50_chk and _sig_type == "mean_reversion":
                    if _dir_chk == "LONG" and _price_chk < _ma50_chk:
                        print(f"       ❌ MA50 фильтр: mean-rev LONG заблокирован (цена {_price_chk} < MA50 {_ma50_chk:.1f})")
                        logger.info("%s: mean-rev LONG заблокирован MA50 (цена=%.2f < MA50=%.2f)", ticker, _price_chk, _ma50_chk)
                        append_market_radar_opportunity(
                            ticker, "ma50_mean_reversion_blocked",
                            direction=_dir_chk, levels=levels, anomaly=anomaly,
                            change_pct=daily_change_pct(candles),
                            extra={"signal_type": _sig_type},
                        )
                        continue
                    if _dir_chk == "SHORT" and _price_chk > _ma50_chk:
                        print(f"       ❌ MA50 фильтр: mean-rev SHORT заблокирован (цена {_price_chk} > MA50 {_ma50_chk:.1f})")
                        logger.info("%s: mean-rev SHORT заблокирован MA50 (цена=%.2f > MA50=%.2f)", ticker, _price_chk, _ma50_chk)
                        append_market_radar_opportunity(
                            ticker, "ma50_mean_reversion_blocked",
                            direction=_dir_chk, levels=levels, anomaly=anomaly,
                            change_pct=daily_change_pct(candles),
                            extra={"signal_type": _sig_type},
                        )
                        continue
                type_label = "📈 momentum" if _sig_type == "momentum" else "↩️ mean-rev"
                print(f"       {type_label} → {_dir_chk}")

                # ── v0.9.3: H1 подтверждение входа ──────────────────────────
                h1_raw  = None
                h1_lvls = None
                h1_conf = None
                if _tinvest_available():
                    h1_raw = _tinvest.get_h1_candles(ticker, days=5)
                    # v0.9.7: fallback на MOEX ISS если T-Invest не вернул данных
                    # (нет FIGI, инструмент не найден — FLOT и др.)
                    if not h1_raw:
                        h1_raw = get_h1_candles_moex(ticker, days=5)
                        if h1_raw:
                            logger.info("%s: H1 через MOEX ISS fallback (%d свечей)", ticker, len(h1_raw))
                    h1_lvls = calc_h1_levels(h1_raw) if h1_raw else None
                    if h1_lvls:
                        print(f"       H1 уровни: поддержка={h1_lvls.get('h1_support')}  "
                              f"сопротивление={h1_lvls.get('h1_resistance')}")
                    if h1_raw:
                        h1_conf = check_h1_confirmation(_dir_chk, levels, h1_raw)

                if h1_conf:
                    # ✅ H1 подтверждение есть → сразу строим сигнал
                    ctype = "пробой" if h1_conf["type"] == "breakout" else "импульс"
                    print(f"       ✅ H1 {ctype}: {h1_conf['note']}")
                    logger.info("%s: H1 подтверждение (%s) — строим сигнал %s. %s",
                                ticker, ctype, _dir_chk, h1_conf.get("note", ""))
                    # Удаляем из watch-листа если там был (уже подтверждён)
                    watch_key = f"{ticker}_{_dir_chk}"
                    if watch_key in h1_watch:
                        del h1_watch[watch_key]
                        print(f"       📋 Watch-лист: {watch_key} подтверждён, удалён")
                    sig = build_market_signal(ticker, levels, anomaly, ctx,
                                              intraday=intraday or None,
                                              h1_levels=h1_lvls,
                                              h1_confirm=h1_conf)
                    if sig:
                        market_signals.append(sig)
                elif _tinvest_available():
                    # ⏳ T-Invest доступен, но H1 не подтвердил — добавляем в watch
                    watch_key = f"{ticker}_{_dir_chk}"
                    if watch_key not in h1_watch:
                        add_to_h1_watch(h1_watch, ticker, _dir_chk, levels, anomaly, state)  # v0.9.36: state для guard
                        print(f"       👀 H1 нет подтверждения — {watch_key} добавлен в watch ({H1_WATCH_HOURS:.0f}ч)")
                        logger.info("%s: ДОБАВЛЕН в h1_watch, направление=%s, ×%.1f, ждём %gч",
                                    ticker, _dir_chk, anomaly.get("ratio", 0), H1_WATCH_HOURS)
                        append_market_radar_opportunity(
                            ticker, "h1_watch_pending",
                            direction=_dir_chk, levels=levels, anomaly=anomaly,
                            change_pct=daily_change_pct(candles),
                            extra={"signal_type": _sig_type, "watch_key": watch_key},
                        )
                        # v0.9.19: watch-алерты убраны из Telegram (только вход/закрытие)
                        logger.info("%s: watch-alert подавлен (v0.9.19)", ticker)
                    else:
                        print(f"       👀 H1 ожидание... {watch_key} уже в watch-листе")
                        logger.debug("%s: уже в h1_watch, H1 снова не подтвердил", watch_key)
                else:
                    # T-Invest недоступен — строим сигнал без H1-фильтра (как раньше)
                    sig = build_market_signal(ticker, levels, anomaly, ctx,
                                              intraday=intraday or None,
                                              h1_levels=h1_lvls)
                    if sig:
                        market_signals.append(sig)
            else:
                reason = "объём мал" if not anomaly.get("absolute_ok", True) else f"×{anomaly.get('ratio', 0)}"
                print(f"— норма ({reason})")
                maybe_log_price_momentum_radar(ticker, candles, levels, anomaly)
                if ticker in INDEX_REBOUND_TICKERS and index_intraday:
                    rebound_intraday = get_intraday_price(ticker)
                    if rebound_intraday:
                        intraday_data[ticker] = rebound_intraday
                        _current_intraday[ticker] = rebound_intraday
                        maybe_log_index_rebound_radar(
                            ticker, rebound_intraday, index_intraday,
                            levels, anomaly, daily_change_pct(candles),
                        )
                        rebound_signal = build_index_rebound_signal(
                            ticker, levels, ctx, rebound_intraday, index_intraday, anomaly
                        )
                        if rebound_signal:
                            market_signals.append(rebound_signal)

        # ── v0.9.3: обрабатываем watch-лист (тикеры из прошлых сканов) ──────
        watch_tickers = [v for v in h1_watch.values() if v["ticker"] not in {s["ticker"] for s in market_signals}]
        if watch_tickers:
            print(f"\n  ⏳ Watch-лист: проверяем {len(watch_tickers)} тикеров на H1-подтверждение")
        for entry in watch_tickers:
            w_ticker = entry["ticker"]
            w_dir    = entry["direction"]
            w_key    = f"{w_ticker}_{w_dir}"
            print(f"  → {w_ticker} ({w_dir}) [watch]", end=" ", flush=True)
            if not _tinvest_available():
                print("— T-Invest недоступен, пропускаем")
                continue
            # Свежие данные для watch-тикера
            w_candles = get_candles(w_ticker, days=55)
            if not w_candles:
                print("— нет данных")
                continue
            w_levels  = calc_levels(w_candles)
            w_anomaly = detect_volume_anomaly(w_candles, ticker=w_ticker)
            # Тезис отработан — объём нормализовался, входить уже незачем
            if not w_anomaly.get("anomaly"):
                print(f"— объём нормализовался, убираем из watch")
                logger.info("%s: УДАЛЁН из h1_watch — объём нормализовался", w_key)
                del h1_watch[w_key]
                continue
            # v0.9.4: пересчитываем направление — цена могла измениться за время watch
            _wp = w_levels.get("last_close", 0)
            _wma50 = w_levels.get("ma50")
            w_dir, w_sig_type = determine_direction(_wp, w_levels)
            new_key = f"{w_ticker}_{w_dir}"
            if new_key != w_key:
                # направление изменилось — обновляем ключ в watch
                logger.info("%s → направление изменилось на %s, обновляем watch-ключ", w_key, new_key)
                del h1_watch[w_key]
                w_key = new_key
                add_to_h1_watch(h1_watch, w_ticker, w_dir, w_levels, w_anomaly, state)  # v0.9.36
            # MA50_HARD_FILTER — только для mean_reversion против тренда
            if MA50_HARD_FILTER and _wma50 and w_sig_type == "mean_reversion":
                if w_dir == "LONG" and _wp < _wma50:
                    print(f"❌ MA50 фильтр (mean-rev) — убираем из watch")
                    logger.info("%s: УДАЛЁН из h1_watch — MA50 фильтр mean-rev (цена=%.2f < MA50=%.2f)", w_key, _wp, _wma50)
                    del h1_watch[w_key]
                    continue
                if w_dir == "SHORT" and _wp > _wma50:
                    print(f"❌ MA50 фильтр (mean-rev) — убираем из watch")
                    logger.info("%s: УДАЛЁН из h1_watch — MA50 фильтр mean-rev (цена=%.2f > MA50=%.2f)", w_key, _wp, _wma50)
                    del h1_watch[w_key]
                    continue
            h1_raw_w = _tinvest.get_h1_candles(w_ticker, days=5)
            # v0.9.7: fallback на MOEX ISS если FIGI не найден
            if not h1_raw_w:
                h1_raw_w = get_h1_candles_moex(w_ticker, days=5)
                if h1_raw_w:
                    logger.info("%s [watch]: H1 через MOEX ISS fallback (%d свечей)", w_key, len(h1_raw_w))
            h1_lvls_w = calc_h1_levels(h1_raw_w) if h1_raw_w else None
            h1_conf_w = check_h1_confirmation(w_dir, w_levels, h1_raw_w) if h1_raw_w else None
            if h1_conf_w:
                ctype = "пробой" if h1_conf_w["type"] == "breakout" else "импульс"
                print(f"✅ H1 {ctype}! Строим сигнал...")
                logger.info("%s [watch]: H1 подтверждение (%s)! Строим сигнал %s. %s",
                            w_key, ctype, w_dir, h1_conf_w.get("note", ""))
                w_intraday = get_intraday_price(w_ticker)
                if w_intraday:
                    intraday_data[w_ticker] = w_intraday
                sig = build_market_signal(w_ticker, w_levels, w_anomaly, ctx,
                                          intraday=w_intraday or None,
                                          h1_levels=h1_lvls_w,
                                          h1_confirm=h1_conf_w)
                if sig:
                    market_signals.append(sig)
                del h1_watch[w_key]
            else:
                remaining = ""
                mins_left = None
                try:
                    exp = datetime.fromisoformat(entry["expires_at"])
                    mins_left = int((exp - datetime.now(timezone.utc)).total_seconds() / 60)
                    remaining = f", осталось {mins_left} мин"
                except (KeyError, ValueError):
                    pass
                print(f"⏳ H1 пока нет{remaining}")
                logger.debug("%s [watch]: H1 не подтвердил, осталось %s мин",
                             w_key, mins_left if mins_left is not None else "?")

        # Сохраняем обновлённый watch-лист
        save_h1_watch(h1_watch)
        if h1_watch:
            print(f"\n  📋 Watch-лист сохранён: {len(h1_watch)} тикер(ов) ждут H1-подтверждения")
            logger.info("h1_watch: %d тикер(ов) в наблюдении: %s",
                        len(h1_watch), ", ".join(h1_watch.keys()))

    # ── Модули 2+3 ───────────────────────────────────────────────────────────
    print(f"\n\n📰 СКАНИРОВАНИЕ НОВОСТЕЙ\n")
    cache     = clean_cache(load_cache())
    new_news  = fetch_news(cache)
    relevant  = [n for n in new_news if is_relevant(n)]
    print(f"\n  Новых: {len(new_news)} | Релевантных для AI: {len(relevant)} | "
          f"Отфильтровано: {len(new_news) - len(relevant)}")
    logger.info("новости: новых=%d  релевантных=%d", len(new_news), len(relevant))

    news_signals  = []

    if relevant:
        analyzed = []
        for i in range(0, len(relevant), AI_MAX_NEWS):
            analyzed.extend(analyze_by_ai(relevant[i:i + AI_MAX_NEWS], ctx))

        news_signals = [
            n for n in analyzed
            if n.tickers and n.direction != "NEUTRAL" and n.strength >= NEWS_STRENGTH_MIN
        ]
        news_signals.sort(key=lambda x: x.strength, reverse=True)

    elif new_news:
        print("  ℹ️  Нет новых релевантных новостей — все уже обработаны")

    save_cache(cache)

    # v0.9.19: обновляем news_memory на основе свежих новостей
    if new_news:
        _nm_data = load_news_memory()
        _nm_data = update_news_memory(new_news, _nm_data)
        save_news_memory(_nm_data)
        logger.info("news_memory: обновлено по %d новостям", len(new_news))

    # Intraday-цены для новостных тикеров (не загруженных при скане рыночных аномалий).
    # Рыночные тикеры с аномалией уже загружены выше в цикле сканирования (v0.9).
    news_only_tickers: set[str] = set()
    for n in news_signals:
        for t in n.tickers:
            if t not in intraday_data:
                news_only_tickers.add(t)
    if news_only_tickers:
        print(f"\n  📈 Intraday новостных тикеров ({len(news_only_tickers)})...", end=" ", flush=True)
        with ThreadPoolExecutor(max_workers=min(6, len(news_only_tickers))) as pool:
            future_map = {
                pool.submit(get_intraday_price, ticker): ticker
                for ticker in sorted(news_only_tickers)
            }
            for future in as_completed(future_map):
                ticker = future_map[future]
                try:
                    intraday_data[ticker] = future.result()
                except Exception as e:
                    logger.warning("news intraday fetch %s: %s", ticker, e)
                    intraday_data[ticker] = {}
        print("✅")
    for n in news_signals:
        n.status = assess_news_status(n, intraday_data)

    news_event_market_signals: list[dict] = []
    if news_signals and not news_only:
        existing_market_tickers = {s["ticker"] for s in market_signals}
        news_event_market_signals = build_news_event_signals(
            news_signals, ctx, intraday_data, existing_market_tickers
        )
        if news_event_market_signals:
            market_signals.extend(news_event_market_signals)
            print(f"  📰 News-event sandbox candidates: {len(news_event_market_signals)}")

    # ── Модуль 4 ─────────────────────────────────────────────────────────────
    synthesized = []
    if market_signals:
        synthesized = synthesize_signals(market_signals, news_signals)
        print(f"\n\n🎯 ИТОГОВЫЕ СИГНАЛЫ: {len(synthesized)}\n")
        for s in sorted(synthesized, key=lambda x: x["volume_ratio"], reverse=True):
            print_synthesized_signal(s)
    elif not news_only:
        print("\n\n😴 Рыночных аномалий нет")

    orphan = []
    if news_signals:
        tickers_with_market = {s["ticker"] for s in market_signals}
        orphan = [
            n for n in news_signals
            if not any(t in tickers_with_market for t in n.tickers)
        ]
        if orphan:
            print(f"\n📰 НОВОСТНЫЕ СИГНАЛЫ (без рыночного подтверждения): {len(orphan)}\n")
            for s in orphan[:8]:
                print_news_signal(s)

    # ── Sandbox (бумажная торговля) ───────────────────────────────────────────
    if _tinvest_available() and SANDBOX_AUTO_ORDER:
        # v0.9.34: reconcile всегда (даже без новых сигналов) — чистит ghost/orphan
        _sb_state_rec = load_signals_state()
        reconcile_sandbox_state(_sb_state_rec)

    if _tinvest_available() and SANDBOX_AUTO_ORDER and synthesized:
        print(f"\n📋 Sandbox-ордера...")
        sb_state = load_signals_state()
        n_placed = sandbox_execute_signals(synthesized, sb_state)
        save_signals_state(sb_state)
        if n_placed:
            print(f"  ✅ Размещено sandbox-ордеров: {n_placed}")
        else:
            print("  💬 Sandbox: нечего нового (нет новых ВЫСОКИХ сигналов)")

    # ── Telegram ─────────────────────────────────────────────────────────────
    if TELEGRAM_TOKEN and TELEGRAM_CHAT_ID:
        print(f"\n📲 Telegram-уведомления...")
        tg_notify_run(
            synthesized    = synthesized if market_signals else [],
            news_orphan    = orphan,
            intraday_data  = intraday_data,
            ctx            = ctx,
        )

    print(f"\n{'═'*54}")
    print(f"  ✅ Готово. {len(market_signals)} рыночных + {len(news_signals)} новостных")
    print(f"  🔖 {BOT_VERSION}")
    print(f"{'═'*54}\n")
    logger.info("─── скан завершён: %d рыночных + %d новостных сигналов ───",
                len(market_signals), len(news_signals))
    if market_signals:
        for _ms in market_signals:
            logger.info("СИГНАЛ %s %s: вход≈%s  стоп=%s  цель=%s  сила=%s",
                        _ms.get("direction", "?"), _ms.get("ticker", "?"),
                        _ms.get("entry", "?"), _ms.get("stop", "?"),
                        _ms.get("take2", "?"), _ms.get("confidence", "?"))
    return market_signals, news_signals


def clear_bot_log() -> None:
    """
    v0.9.7: --clear-log
    Архивирует logs/bot.log в logs/bot_YYYY-MM-DD.log и очищает текущий файл.
    Используется после анализа сессии чтобы следующий анализ содержал только свежие данные.
    v0.9.10: лог-файлы теперь в подпапке logs/.
    """
    os.makedirs(_LOG_DIR, exist_ok=True)
    date_str = now_msk().strftime("%Y-%m-%d")
    archive  = os.path.join(_LOG_DIR, f"bot_{date_str}.log")

    if not os.path.exists(_LOG_FILE) or os.path.getsize(_LOG_FILE) == 0:
        print("📋 bot.log уже пуст — нечего архивировать.")
        return

    # Если архив за сегодня уже есть — дописываем (несколько очисток за день)
    import shutil
    if os.path.exists(archive):
        with open(archive, "a", encoding="utf-8") as dst, \
             open(_LOG_FILE,  "r", encoding="utf-8", errors="replace") as src:
            dst.write(f"\n# ── append {now_msk().strftime('%H:%M:%S')} ──\n")
            shutil.copyfileobj(src, dst)
    else:
        shutil.copy2(_LOG_FILE, archive)

    # Очищаем текущий лог
    open(_LOG_FILE, "w").close()
    size_kb = round(os.path.getsize(archive) / 1024, 1)
    print(f"✅ bot.log очищен. Архив: {archive}  ({size_kb} КБ)")


# ─── v0.9.30: Market-hours guard ────────────────────────────────────────────

def _moex_is_open() -> tuple:
    """
    Возвращает (is_open: bool, seconds_until_open: int).
    Использует канонический торговый календарь минорной версии.
    """
    is_open, seconds_until_open, _phase = _session_window()
    return is_open, seconds_until_open


# ─── v0.9.30: Score-log rotation ────────────────────────────────────────────

def rotate_score_log(max_days: int = 7, max_mb: float = 10.0):
    """
    Удаляет из signals_score_log.jsonl записи старше max_days дней.
    Если файл всё равно > max_mb МБ — обрезает по размеру (оставляет хвост).
    Вызывается при старте watch-режима.
    """
    if not os.path.exists(SCORE_LOG_FILE):
        return
    size_mb = os.path.getsize(SCORE_LOG_FILE) / 1024 / 1024
    if size_mb < 0.5:
        return  # файл маленький — не трогаем

    # v0.9.33: cutoff naive (ts[:19] в лог-файле тоже naive — без timezone)
    cutoff = now_msk().replace(tzinfo=None) - __import__("datetime").timedelta(days=max_days)
    kept   = []
    total  = 0
    try:
        with open(SCORE_LOG_FILE, "r", encoding="utf-8") as f:
            lines = f.readlines()
        total = len(lines)
        for ln in lines:
            try:
                obj = __import__("json").loads(ln)
                ts  = obj.get("ts") or obj.get("timestamp") or ""
                if ts:
                    dt = datetime.fromisoformat(ts[:19])
                    if dt >= cutoff:
                        kept.append(ln)
                else:
                    kept.append(ln)  # нет метки — оставляем
            except Exception:
                kept.append(ln)

        # Если после фильтрации всё ещё > max_mb — режем по размеру с хвоста
        # v0.9.32: проверяем размер ДО добавления строки, чтобы не превысить лимит
        mb_kept = sum(len(l.encode()) for l in kept) / 1024 / 1024
        if mb_kept > max_mb:
            trimmed = []
            acc = 0.0
            for ln in reversed(kept):
                ln_mb = len(ln.encode()) / 1024 / 1024
                if acc + ln_mb > max_mb:
                    break
                acc += ln_mb
                trimmed.append(ln)
            kept   = list(reversed(trimmed))
            mb_kept = acc

        with open(SCORE_LOG_FILE, "w", encoding="utf-8") as f:
            f.writelines(kept)
        removed = total - len(kept)
        if removed:
            print(f"🧹 score_log: удалено {removed} старых записей "
                  f"({size_mb:.1f}MB → {mb_kept:.1f}MB). Осталось {len(kept)} строк.")
    except Exception as e:
        print(f"⚠️  rotate_score_log: {e}")


# ─── v0.9.30: Export .tar.gz cleanup ────────────────────────────────────────

def cleanup_old_exports(keep: int = 5):
    """
    Удаляет старые файлы trader_export_*.tar.gz, оставляя последние `keep` штук.
    Вызывается при старте watch-режима.
    """
    _dir = os.path.dirname(os.path.abspath(__file__))
    import glob as _glob
    archives = sorted(
        _glob.glob(os.path.join(_dir, "trader_export_*.tar.gz")),
        key=os.path.getmtime
    )
    to_delete = archives[:-keep] if len(archives) > keep else []
    for path in to_delete:
        try:
            os.remove(path)
            print(f"🗑  Удалён старый экспорт: {os.path.basename(path)}")
        except Exception as e:
            print(f"⚠️  cleanup_old_exports: {e}")


# ─── v0.9.32: EOD portfolio report ──────────────────────────────────────────

# Хранит equity на момент открытия рынка в текущий день
_equity_day_start: float = 0.0
_eod_sent_date: str = ""           # дата последнего EOD-отчёта (YYYY-MM-DD МСК)
_sod_loaded_date: str = ""         # дата загрузки начального equity

_EOD_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "eod_state.json")


def _load_eod_state() -> None:
    """Загружает сохранённое состояние EOD из файла (нужно при рестарте бота)."""
    global _equity_day_start, _eod_sent_date, _sod_loaded_date
    try:
        d = load_json_file(_EOD_FILE, {}, "_load_eod_state")
        if isinstance(d, dict):
            _equity_day_start  = float(d.get("equity_day_start", 0))
            _eod_sent_date     = d.get("eod_sent_date", "")
            _sod_loaded_date   = d.get("sod_loaded_date", "")
    except Exception:
        pass


def _save_eod_state() -> None:
    try:
        save_json_file_atomic(_EOD_FILE, {
            "equity_day_start": _equity_day_start,
            "eod_sent_date":    _eod_sent_date,
            "sod_loaded_date":  _sod_loaded_date,
        }, "_save_eod_state")
    except Exception:
        pass


def _try_record_sod_equity() -> None:
    """
    Записывает equity в начале торгового дня (SOD = Start of Day).
    Вызывается при первом скане дня, когда биржа открыта.
    """
    global _equity_day_start, _sod_loaded_date
    import pytz as _ptz
    _today = datetime.now(_ptz.timezone("Europe/Moscow")).strftime("%Y-%m-%d")
    if _sod_loaded_date == _today:
        return  # уже записали сегодня
    if not _tinvest_available():
        return
    try:
        portfolio = _tinvest.get_sandbox_portfolio()   # type: ignore[union-attr]
        eq = portfolio.get("total_amount_rub", 0) if portfolio else 0
        if eq > 0:
            _equity_day_start = eq
            _sod_loaded_date  = _today
            _save_eod_state()
            logger.info("eod: SOD equity записан = %.0f (дата=%s)", eq, _today)
    except Exception as _e:
        logger.warning("eod: не удалось записать SOD equity: %s", _e)


def send_eod_report() -> None:
    """
    v0.9.32: Отправляет итоговый отчёт дня в Telegram в 18:55–19:10 МСК
    (после закрытия основной сессии, вместе с первым сканом вечерней).
    Содержит: текущий портфель, изменение за день, открытые позиции, P&L сделок.
    """
    global _eod_sent_date
    import pytz as _ptz
    _msk    = _ptz.timezone("Europe/Moscow")
    _today  = datetime.now(_msk).strftime("%Y-%m-%d")

    if _eod_sent_date == _today:
        return  # уже отправили сегодня

    if not (TELEGRAM_TOKEN and TELEGRAM_CHAT_ID):
        return

    # ── Портфель ──────────────────────────────────────────────────────────────
    equity_now: float = 0.0
    open_positions: list[str] = []
    if _tinvest_available():
        try:
            portfolio = _tinvest.get_sandbox_portfolio()   # type: ignore[union-attr]
            if portfolio:
                equity_now = portfolio.get("total_amount_rub", 0)
                for pos in portfolio.get("positions", []):
                    t   = pos.get("ticker", "?")
                    qty = pos.get("quantity", 0)
                    pnl = pos.get("pnl_pct", pos.get("pnl", 0))
                    # v0.9.34: фильтруем кэш-позиции (RUB000UTSTOM и аналоги)
                    if qty != 0 and t not in _CASH_TICKERS and pos.get("avg_price", 0) != 0:
                        emoji = "🟢" if qty > 0 else "🔴"
                        sign  = "+" if pnl >= 0 else ""
                        open_positions.append(f"{emoji}{t} {sign}{pnl:.1f}%")
        except Exception as _e:
            logger.warning("eod: не удалось получить портфель: %s", _e)

    # ── Сделки за день ────────────────────────────────────────────────────────
    try:
        state = load_state()
    except Exception:
        state = {}

    day_trades = []
    try:
        if os.path.exists(TRADE_LOG_FILE):
            with open(TRADE_LOG_FILE, "r", encoding="utf-8") as _f:
                all_trades = __import__("json").load(_f)
            for tr in all_trades:
                # exit_time формат: "YYYY-MM-DD HH:MM"
                et = tr.get("exit_time", "")
                if et.startswith(_today):
                    day_trades.append(tr)
    except Exception:
        pass

    # ── Форматируем сообщение ─────────────────────────────────────────────────
    _date_str   = datetime.now(_msk).strftime("%d.%m.%Y")
    _now_str    = datetime.now(_msk).strftime("%H:%M МСК")

    # Изменение equity за день
    if equity_now > 0 and _equity_day_start > 0:
        day_change     = equity_now - _equity_day_start
        day_change_pct = day_change / _equity_day_start * 100
        sign           = "+" if day_change >= 0 else ""
        equity_line    = (
            f"💼 Портфель: {equity_now:,.0f} ₽  "
            f"({sign}{day_change:,.0f} ₽  {sign}{day_change_pct:.2f}% за день)"
        )
    elif equity_now > 0:
        equity_line = f"💼 Портфель: {equity_now:,.0f} ₽"
    else:
        equity_line = "💼 Портфель: данные недоступны"

    # Открытые позиции
    pos_line = ("📂 Открытые: " + "  ".join(open_positions)) if open_positions else "📂 Открытых позиций нет"

    # Сделки дня
    if day_trades:
        total_pnl = sum(t.get("pnl_pct", 0) for t in day_trades)
        wins      = sum(1 for t in day_trades if t.get("pnl_pct", 0) > 0)
        trades_lines = []
        for t in day_trades:
            p   = t.get("pnl_pct", 0)
            sig = "+" if p >= 0 else ""
            res = "✅" if p > 0 else "❌"
            trades_lines.append(f"  {res} {t['ticker']} {t['direction']}  {sig}{p:.2f}%")
        trades_block = (
            f"📊 Сделок за день: {len(day_trades)}  ({wins} прибыльных)\n"
            + "\n".join(trades_lines) + f"\n  Итого: {'+' if total_pnl>=0 else ''}{total_pnl:.2f}%"
        )
    else:
        trades_block = "📊 Сделок за день: 0"

    msg = (
        f"🌙 *Итог дня — {_date_str}*\n"
        f"{'─'*30}\n"
        f"{equity_line}\n"
        f"{pos_line}\n"
        f"{'─'*30}\n"
        f"{trades_block}\n"
        f"{'─'*30}\n"
        f"⏰ {_now_str}  |  MOEX Bot {BOT_VERSION}"
    )

    tg_send(msg)
    _eod_sent_date = _today
    _save_eod_state()
    logger.info("eod: отчёт дня отправлен (%s)", _today)
    print(f"📋 EOD-отчёт отправлен в Telegram ({_today})")


def _acquire_pid_lock() -> bool:
    """
    v0.9.27: Защита от двойного запуска.
    Создаёт PID-файл. Если процесс с таким PID уже запущен — возвращает False.
    При нормальном завершении PID-файл удаляется через _release_pid_lock().
    """
    if os.path.exists(PID_FILE):
        try:
            with open(PID_FILE) as _f:
                _old_pid = int(_f.read().strip())
            os.kill(_old_pid, 0)   # SIGZERO — проверяем, жив ли процесс (не убивает)
            # Процесс жив — это дубль
            print(f"⚠️  Бот уже запущен (PID {_old_pid}). Новый экземпляр не нужен — выход.")
            logger.warning("pid_lock: already running (PID %d) — exit", _old_pid)
            return False
        except (ProcessLookupError, OSError):
            # Старый PID-файл от упавшего процесса — игнорируем, перезапишем
            pass
        except ValueError:
            pass  # PID-файл повреждён
    with open(PID_FILE, "w") as _f:
        _f.write(str(os.getpid()))
    return True


def _release_pid_lock() -> None:
    """v0.9.27: Удаляем PID-файл при завершении."""
    try:
        if os.path.exists(PID_FILE):
            os.remove(PID_FILE)
    except OSError:
        pass


def cmd_close_position(ticker: str) -> None:
    """
    v0.9.34: Ручное закрытие sandbox-позиции из CLI.
    Использование: python3 moex_bot.py --close TRNFP

    1. Вызывает sandbox_close_position() в T-Invest API.
    2. Помечает все открытые sb_-записи по этому тикеру как closed_at.
    3. Выводит результат и новый баланс портфеля.
    """
    ticker = ticker.upper().strip()
    print(f"\n🔒 Закрываем sandbox-позицию: {ticker}")

    if not _tinvest_available():
        print("❌ T-Invest API недоступен. Проверьте .env (TINVEST_TOKEN).")
        return

    # ── 1. Закрываем в T-Invest ───────────────────────────────────────────────
    try:
        result = _tinvest.sandbox_close_position(ticker)   # type: ignore[union-attr]
    except Exception as e:
        print(f"❌ Ошибка API при закрытии {ticker}: {e}")
        return

    if not result:
        print(f"⚠️  sandbox_close_position({ticker}) вернул None — позиция уже закрыта или не существует.")
    else:
        close_price = result.get("price", "?")
        print(f"✅ T-Invest: позиция {ticker} закрыта по цене {close_price}")

    # ── 2. Помечаем в state.json ──────────────────────────────────────────────
    state   = load_signals_state()
    changed = False
    for key, val in list(state.items()):
        if not key.startswith("sb_"):
            continue
        if val.get("ticker", "").upper() != ticker:
            continue
        if val.get("closed_at"):
            continue  # уже закрыта
        val["closed_at"]    = datetime.now(timezone.utc).isoformat()
        val["close_reason"] = "manual_cli"
        if result:
            val["close_price"] = result.get("price")
        changed = True
        print(f"  📝 state: {key} → closed_at = manual_cli")

    if changed:
        save_signals_state(state)
        print("  💾 signals_state.json обновлён.")
    else:
        print(f"  ℹ️  В state.json нет открытых записей по {ticker}.")

    # ── 3. Показываем текущий портфель ───────────────────────────────────────
    try:
        portfolio = _tinvest.get_sandbox_portfolio()   # type: ignore[union-attr]
        if portfolio:
            total = portfolio.get("total_amount_rub", 0)
            positions = [
                p for p in portfolio.get("positions", [])
                if p.get("ticker") not in _CASH_TICKERS and p.get("avg_price", 0) != 0
            ]
            print(f"\n💼 Портфель после закрытия: {total:,.0f} ₽")
            if positions:
                for p in positions:
                    t   = p.get("ticker")
                    qty = p.get("quantity", 0)
                    pnl = p.get("pnl_pct", 0)
                    sign = "+" if pnl >= 0 else ""
                    print(f"  {'🟢' if qty > 0 else '🔴'} {t}  ×{qty:+.0f}  PnL {sign}{pnl:.1f}%")
            else:
                print("  Открытых позиций нет.")
    except Exception as e:
        print(f"  ⚠️  Не удалось получить портфель: {e}")


def main():
    # v0.9.34: загружаем .env при любом запуске из консоли
    # (systemd подтягивает переменные через EnvironmentFile= — там это не нужно,
    #  но при ручном `python3 moex_bot.py --close` без него токены не видны)
    try:
        import dotenv as _dotenv
        _env_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), ".env")
        _dotenv.load_dotenv(_env_path, override=False)  # override=False: не перезаписываем уже заданные
    except ImportError:
        pass  # python-dotenv не установлен — переменные должны быть заданы в окружении

    watch_mode  = "--watch"      in sys.argv
    news_only   = "--news-only"  in sys.argv
    show_log    = "--trade-log"  in sys.argv
    export_csv  = "--export-csv" in sys.argv
    clear_log   = "--clear-log"  in sys.argv   # v0.9.7: архивировать и очистить лог

    # v0.9.34: ручное закрытие позиции
    if "--close" in sys.argv:
        idx = sys.argv.index("--close")
        if idx + 1 < len(sys.argv):
            cmd_close_position(sys.argv[idx + 1])
        else:
            print("❌ Укажите тикер: python3 moex_bot.py --close TRNFP")
        return

    # v0.9.7: очистка лога
    if clear_log:
        clear_bot_log()
        return

    # v0.9.1: команды трейд-лога
    if show_log:
        print_trade_log_summary()
        return

    if export_csv:
        path = export_trade_csv()
        if path:
            print(f"✅ CSV экспортирован: {path}")
        else:
            print("📋 Трейд-лог пуст — нечего экспортировать.")
        return

    # v0.9.27: Защита от двойного запуска (--watch или разовый скан)
    if not _acquire_pid_lock():
        sys.exit(0)

    try:
        _migration_summary = run_state_migrations()
        if not _migration_summary.get("skipped"):
            print(
                "🧹 state migration: "
                f"state_removed={_migration_summary.get('state_removed', 0)} "
                f"trade_removed={_migration_summary.get('trade_removed', 0)} "
                f"ntg_removed={_migration_summary.get('ntg_removed', 0)}"
            )
    except Exception as _e:
        logger.warning("state_migration skipped: %s", _e)

    # v0.9.38: проверка LOT_SIZE против MOEX ISS (single startup call).
    # WARN логируется по каждому расхождению. Не блокирующе — бот продолжит работу,
    # но крупные mismatches могут открыть неправильные позиции (кейс SBER 17.04).
    try:
        from tinvest_data import verify_lot_sizes as _verify_lots
        _mm = _verify_lots(timeout=5.0)
        if _mm:
            print(f"  ⚠️  LOT_SIZE mismatches: {len(_mm)} тикер(ов) — см. лог")
    except Exception as _e:
        logger.warning("verify_lot_sizes skipped: %s", _e)

    try:
        if watch_mode:
            print(f"🔁 Watch-режим каждые {SCAN_INTERVAL_SEC//60} мин. Ctrl+C для остановки.")
            # v0.9.30: очистка при старте; v0.9.32: восстанавливаем EOD-состояние
            rotate_score_log()
            cleanup_old_exports()
            _load_eod_state()
            while True:
                try:
                    import pytz as _ptz
                    _msk_tz  = _ptz.timezone("Europe/Moscow")
                    _now_msk = datetime.now(_msk_tz)
                    _t_msk   = _now_msk.time()
                    import datetime as _dt

                    is_open, secs = _moex_is_open()

                    # v0.9.32: EOD-отчёт — после закрытия основной сессии (18:55–19:10 МСК).
                    # Отправляется вместе с первым сканом вечерней сессии или в паузе между ними.
                    _eod_window = _dt.time(18, 55) <= _t_msk <= _dt.time(19, 10)
                    if _eod_window:
                        send_eod_report()

                    if not is_open:
                        # Биржа закрыта — спим до открытия (не более 1 ч за раз)
                        sleep_secs = min(secs, 3600)
                        mins       = sleep_secs // 60
                        _now_str   = _now_msk.strftime("%H:%M МСК")
                        print(f"🌙 [{_now_str}] Биржа закрыта. Следующая проверка через "
                              f"{mins} мин (откроется через ~{secs//60} мин).")
                        time.sleep(sleep_secs)
                        continue

                    # v0.9.32: фиксируем equity в начале дня (первый скан открытой сессии)
                    _try_record_sod_equity()

                    run_once(news_only=news_only)
                    print(f"⏳ Следующий скан через {SCAN_INTERVAL_SEC//60} мин...\n")
                    time.sleep(SCAN_INTERVAL_SEC)
                except KeyboardInterrupt:
                    print("\n👋 Остановлено")
                    break
        else:
            run_once(news_only=news_only)
    finally:
        _release_pid_lock()


if __name__ == "__main__":
    main()
